const a={"les-n3-u01-01":{pedagogical_framework:{what:{summary:"Dimensi Waktu, Peluang & Momentum Seketika (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜うちに, 〜たびに, 〜とたん（に）, 〜最中に（さいちゅうに）, 〜まで（動作の終点） dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜うちに dan 〜たびに dalam percakapan kerja wajar.",targetPatterns:["〜うちに (sementara masih ... / selagi ...)","〜たびに (setiap kali ... / tiap kali ...)","〜とたん（に） (begitu ... langsung / seketika setelah ...)","〜最中に（さいちゅうに） (di tengah-tengah ... / tepat ketika sedang ...)","〜まで（動作の終点） (sampai ... (batas akhir tindakan))"],coreVocabSample:["とどける","とどく","なれる","こわす","なおる","きめる","きまる","つたわる"]},sensei_context:{sceneIntro:"Pabrik manufaktur Nagoya saat pergantian shift kerja dan inspeksi mesin. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜うちに dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Dimensi Waktu, Peluang & Momentum Seketika",etiquette:"Gunakan frasa waktu yang tepat untuk mencegah miskomunikasi jadwal operasional bersama rekan kerja Jepang.",taboos:"Jangan gunakan とたんに untuk rencana sengaja di masa depan; pola ini khusus fakta lampau tak terduga."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜うちに",moraNote:"Jaga aksen heiban pada frasa uchi ni dan jeda mora sokon pada to-tan-ni.",soundTip:"Ucapkan 〜うちに dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜うちに",caseScenario:"Menggunakan 〜うちに tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜うちに.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜うちに sesuai kaidah.",explanation:"Kaidah koneksi 〜うちに: Vる / Vている / Adj-い / N + の + うちに."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Pabrik manufaktur Nagoya saat pergantian shift kerja dan inspeksi mesin.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Dimensi Waktu, Peluang & Momentum Seketika (Fondasi & Pemahaman Pola)",setting:"Pabrik manufaktur Nagoya saat pergantian shift kerja dan inspeksi mesin.",narrative:"Budi dan Tanaka berkoordinasi mengenai alur operasional kerja menggunakan pola 〜うちに."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"ブディさん、届けるの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、届けるの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, todokeru no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai mengantar, menyampaikan? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Tanakaさん！ 若いうちに、いろいろな経験をしてください。。",furigana:"はい、Tanakaさん！ 若いうちに、いろいろな経験をしてください。。",romaji:"Hai, Tanaka-san! うちに de susumete imasu.",idText:"Ya, Tanaka! Selagi masih muda, cari banyak pengalaman.."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"なるほど。日本に来るたびに、お土産を買います。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。日本に来るたびに、お土産を買います。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Setiap kali datang ke Jepang, saya beli oleh-oleh.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-00003",word:"届ける",reading:"とどける",romaji:"todokeru",meaning:"mengantar, menyampaikan",pos:"verb-ru",nuance:"Transitif. Bisa berarti mengantar fisik atau melaporkan ke pihak berwenang.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"届ける【とどける】を 確認【かくにん】します。",furigana:"届けるを 確認します。",romaji:"todokeru o kakunin shimasu.",idText:"Memeriksa mengantar, menyampaikan."}},{id:"vg-n3-00004",word:"届く",reading:"とどく",romaji:"todoku",meaning:"sampai, tiba",pos:"verb-u",nuance:"Intransitif — sesuatu sampai/tiba. Transitif: 届ける.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"届く【とどく】を 確認【かくにん】します。",furigana:"届くを 確認します。",romaji:"todoku o kakunin shimasu.",idText:"Memeriksa sampai, tiba."}},{id:"vg-n3-00005",word:"慣れる",reading:"なれる",romaji:"nareru",meaning:"terbiasa",pos:"verb-ru",nuance:"Dipakai dengan に — 〜に慣れる. Proses adaptasi terhadap situasi baru.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"慣れる【なれる】を 確認【かくにん】します。",furigana:"慣れるを 確認します。",romaji:"nareru o kakunin shimasu.",idText:"Memeriksa terbiasa."}},{id:"vg-n3-00007",word:"壊す",reading:"こわす",romaji:"kowasu",meaning:"merusak",pos:"verb-u",nuance:"Transitif — seseorang merusak sesuatu. Intransitif: 壊れる.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"壊す【こわす】を 確認【かくにん】します。",furigana:"壊すを 確認します。",romaji:"kowasu o kakunin shimasu.",idText:"Memeriksa merusak."}},{id:"vg-n3-00009",word:"直る",reading:"なおる",romaji:"naoru",meaning:"sembuh, diperbaiki (intransitif)",pos:"verb-u",nuance:"Intransitif — sesuatu menjadi baik kembali. Transitif: 直す.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"直る【なおる】を 確認【かくにん】します。",furigana:"直るを 確認します。",romaji:"naoru o kakunin shimasu.",idText:"Memeriksa sembuh, diperbaiki (intransitif)."}},{id:"vg-n3-00010",word:"決める",reading:"きめる",romaji:"kimeru",meaning:"memutuskan",pos:"verb-ru",nuance:"Transitif — seseorang membuat keputusan. Intransitif: 決まる.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"決める【きめる】を 確認【かくにん】します。",furigana:"決めるを 確認します。",romaji:"kimeru o kakunin shimasu.",idText:"Memeriksa memutuskan."}},{id:"vg-n3-00011",word:"決まる",reading:"きまる",romaji:"kimaru",meaning:"diputuskan, ditentukan",pos:"verb-u",nuance:"Intransitif — keputusan sudah jadi. Transitif: 決める.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"決まる【きまる】を 確認【かくにん】します。",furigana:"決まるを 確認します。",romaji:"kimaru o kakunin shimasu.",idText:"Memeriksa diputuskan, ditentukan."}},{id:"vg-n3-00013",word:"伝わる",reading:"つたわる",romaji:"tsutawaru",meaning:"tersampaikan",pos:"verb-u",nuance:"Intransitif — pesan/perasaan tersampaikan. Transitif: 伝える.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"伝わる【つたわる】を 確認【かくにん】します。",furigana:"伝わるを 確認します。",romaji:"tsutawaru o kakunin shimasu.",idText:"Memeriksa tersampaikan."}}],explanations:[{id:"exp-1",grammarId:"gn3-00007",title:"Pola: 〜うちに",formula:"Vる / Vている / Adj-い / N + の + うちに",meaning:"sementara masih ... / selagi ...",nuanceNotes:'〜うちに menyatakan bahwa suatu tindakan dilakukan selagi kondisi tertentu masih berlaku, dengan nuansa bahwa kondisi itu akan berubah. "Selagi masih...", "sebelum ... berakhir".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜うちに",idText:"sementara masih ... / selagi ..."}],examples:[{jp:"若いうちに、いろいろな経験をしてください。",romaji:"",idText:"Selagi masih muda, cari banyak pengalaman."},{jp:"温かいうちに食べてください。",romaji:"",idText:"Makanlah selagi masih hangat."},{jp:"覚えているうちにメモしておこう。",romaji:"",idText:"Selagi masih ingat, lebih baik dicatat."}]},{id:"exp-2",grammarId:"gn3-00008",title:"Pola: 〜たびに",formula:"Vる / N + の + たびに",meaning:"setiap kali ... / tiap kali ...",nuanceNotes:"〜たびに menyatakan bahwa setiap kali suatu peristiwa terjadi, konsekuensi atau kebiasaan yang sama pun terjadi.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜たびに",idText:"setiap kali ... / tiap kali ..."}],examples:[{jp:"日本に来るたびに、お土産を買います。",romaji:"",idText:"Setiap kali datang ke Jepang, saya beli oleh-oleh."},{jp:"彼の顔を見るたびに、あの日を思い出す。",romaji:"",idText:"Setiap kali melihat wajahnya, saya teringat hari itu."}]},{id:"exp-3",grammarId:"gn3-00009",title:"Pola: 〜とたん（に）",formula:"Vた + とたん（に）",meaning:"begitu ... langsung / seketika setelah ...",nuanceNotes:"〜とたん（に） menyatakan bahwa sesuatu terjadi seketika atau tiba-tiba setelah suatu tindakan selesai. Menekankan kedekatannya yang sangat singkat.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜とたん（に）",idText:"begitu ... langsung / seketika setelah ..."}],examples:[{jp:"外に出たとたん、雨が降り出した。",romaji:"",idText:"Begitu keluar, langsung hujan."},{jp:"横になったとたんに、眠ってしまった。",romaji:"",idText:"Seketika berbaring, langsung tertidur."}]},{id:"exp-4",grammarId:"gn3-00010",title:"Pola: 〜最中に（さいちゅうに）",formula:"Vている + 最中に / N + の + 最中に",meaning:"di tengah-tengah ... / tepat ketika sedang ...",nuanceNotes:"〜最中に menyatakan bahwa suatu kejadian lain terjadi tepat di tengah-tengah suatu tindakan yang sedang berlangsung, sering dengan nuansa gangguan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜最中に（さいちゅうに）",idText:"di tengah-tengah ... / tepat ketika sedang ..."}],examples:[{jp:"会議の最中に、電話が鳴った。",romaji:"",idText:"Tepat di tengah rapat, telepon berdering."},{jp:"食事している最中に、停電になった。",romaji:"",idText:"Tepat di tengah makan, listrik mati."}]},{id:"exp-5",grammarId:"gn3-00012",title:"Pola: 〜まで（動作の終点）",formula:"Vる + まで",meaning:"sampai ... (batas akhir tindakan)",nuanceNotes:"〜まで（動作の終点） menyatakan bahwa suatu tindakan berlanjut sampai kondisi tertentu terpenuhi.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜まで（動作の終点）",idText:"sampai ... (batas akhir tindakan)"}],examples:[{jp:"合格するまで、諦めません。",romaji:"",idText:"Saya tidak akan menyerah sampai lulus."},{jp:"彼が来るまで、ここで待っています。",romaji:"",idText:"Saya akan menunggu di sini sampai dia datang."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "届ける"?',sentencePrompt:'Makna kata "届ける" (とどける) dalam situasi kerja ini adalah:',options:["mengantar, menyampaikan","sampai, tiba","terbiasa","merusak"],correctAnswer:"mengantar, menyampaikan",explanation:'Makna yang tepat untuk "届ける" adalah "mengantar, menyampaikan".',diagnosticFeedback:{"sampai, tiba":'Salah: Pilihan "sampai, tiba" adalah makna dari kata "届く" (とどく), bukan arti kata "届ける".',terbiasa:'Salah: Pilihan "terbiasa" adalah makna dari kata "慣れる" (なれる), bukan arti kata "届ける".',merusak:'Salah: Pilihan "merusak" adalah makna dari kata "壊す" (こわす), bukan arti kata "届ける".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"若い（　　）、いろいろな経験をしてください。",options:["うちに","たびに","とたん","きり"],correctAnswer:"うちに",explanation:'Pola 〜うちに bermakna "sementara masih ... / selagi ...". Kalimat lengkap: "若いうちに、いろいろな経験をしてください。".',diagnosticFeedback:{たびに:'Salah: Pola "たびに" bermakna "setiap kali ... / tiap kali ...", yang tidak sesuai konteks kalimat ini.',とたん:'Salah: Pola "とたん" bermakna "begitu ... langsung / seketika setelah ...", yang tidak sesuai konteks kalimat ini.',きり:'Salah: Pola "きり" bermakna "sejak ... sampai sekarang (tanpa kembali)", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜うちに secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["温かいうちに食べてください。","温かいうちにでした食べてください。","日本に来るたびに、お土産を買います。","早く帰るつもりだったが、残業になった。"],correctAnswer:"温かいうちに食べてください。",explanation:'Kalimat yang benar dan alami adalah "温かいうちに食べてください。" (Makanlah selagi masih hangat.).',diagnosticFeedback:{"温かいうちにでした食べてください。":"Jebakan Konjugasi: Pola 〜うちに membutuhkan aturan sambung (Vる / Vている / Adj-い / N + の + うちに), bukan bentuk ini.","日本に来るたびに、お土産を買います。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜たびに: setiap kali ... / tiap kali ...), bukan kaidah 〜うちに.","早く帰るつもりだったが、残業になった。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜うちに secara tepat (sementara masih ... / selagi ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["日本に来る たびに、 お土産を 買います。","たびに、 日本に来る お土産を 買います。","日本に来る お土産を たびに、 買います。","買います。 日本に来る たびに、 お土産を"],correctAnswer:"日本に来る たびに、 お土産を 買います。",explanation:'Susunan yang benar: "日本に来る たびに、 お土産を 買います。" (Setiap kali datang ke Jepang, saya beli oleh-oleh.).',diagnosticFeedback:{"たびに、 日本に来る お土産を 買います。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","日本に来る お土産を たびに、 買います。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","買います。 日本に来る たびに、 お土産を":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["日本に来る","たびに、","お土産を","買います。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Pabrik manufaktur Nagoya saat pergantian shift kerja dan inspeksi mesin.", saat Tanaka menyampaikan arahan: 「なるほど。日本に来るたびに、お土産を買います。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜うちに dan 〜たびに dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Pabrik manufaktur Nagoya saat pergantian shift kerja dan inspeksi mesin.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜うちに!",modelAnswer:"はい、Tanakaさん！ 若いうちに、いろいろな経験をしてください。。",modelAnswerId:"Ya, Tanaka! Selagi masih muda, cari banyak pengalaman..",culturalEtiquette:"Gunakan frasa waktu yang tepat untuk mencegah miskomunikasi jadwal operasional bersama rekan kerja Jepang.",skillUnlocked:["Menguasai formulasi pola 〜うちに","Mampu menerapkan prinsip koordinasi komunikasi kerja Dimensi Waktu, Peluang & Momentum Seketika"]},pocket_summary:{keyFormula:"〜うちに (sementara masih ... / selagi ...)",coreWords:["届ける【とどける】 (mengantar, menyampaikan)","届く【とどく】 (sampai, tiba)","慣れる【なれる】 (terbiasa)","壊す【こわす】 (merusak)"],coreWarning:"Jangan gunakan とたんに untuk rencana sengaja di masa depan; pola ini khusus fakta lampau tak terduga.",quickDialogue:"A: ブディさん、届けるの 状況【じょうきょう】は どう... → B: はい、Tanakaさん！ 若いうちに、いろいろな経..."}},"les-n3-u01-02":{pedagogical_framework:{what:{summary:"Dimensi Waktu, Peluang & Momentum Seketika (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 〜ついでに, 〜ばよかった / 〜たらよかった, めったに〜ない, 〜かける / 〜かけの / 〜かけだ dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 〜ついでに dan 〜ばよかった / 〜たらよかった secara mandiri.",targetPatterns:["〜ついでに (sambil sekalian ... / sekalian ...)","〜ばよかった / 〜たらよかった (seandainya saja ... / kalau saja ...)","めったに〜ない (jarang ... / hampir tidak pernah ...)","〜かける / 〜かけの / 〜かけだ (setengah ... / belum selesai ...)"],coreVocabSample:["ふえる","へる","つたえる","ことわる","かくにんする","じゅんびする","りようする","うつる"]},sensei_context:{sceneIntro:"Pabrik manufaktur Nagoya saat pergantian shift kerja dan inspeksi mesin. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 〜ついでに dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Dimensi Waktu, Peluang & Momentum Seketika",etiquette:"Gunakan frasa waktu yang tepat untuk mencegah miskomunikasi jadwal operasional bersama rekan kerja Jepang.",taboos:"Jangan gunakan とたんに untuk rencana sengaja di masa depan; pola ini khusus fakta lampau tak terduga."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜ついでに",moraNote:"Jaga aksen heiban pada frasa uchi ni dan jeda mora sokon pada to-tan-ni.",soundTip:"Ucapkan 〜ついでに dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜ついでに",caseScenario:"Menggunakan 〜ついでに tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜ついでに.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜ついでに sesuai kaidah.",explanation:"Kaidah koneksi 〜ついでに: Vる / Vた + ついでに / N + の + ついでに."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Pabrik manufaktur Nagoya saat pergantian shift kerja dan inspeksi mesin.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Dimensi Waktu, Peluang & Momentum Seketika (Produksi Aktif & Aplikasi Nyata)",setting:"Pabrik manufaktur Nagoya saat pergantian shift kerja dan inspeksi mesin.",narrative:"Budi dan Tanaka berkoordinasi mengenai alur operasional kerja menggunakan pola 〜ついでに."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"ブディさん、増えるの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、増えるの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, fueru no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai bertambah, meningkat? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Tanakaさん！ 買い物に行くついでに、薬局にも寄ります。。",furigana:"はい、Tanakaさん！ 買い物に行くついでに、薬局にも寄ります。。",romaji:"Hai, Tanaka-san! ついでに de susumete imasu.",idText:"Ya, Tanaka! Sekalian pergi belanja, mampir juga ke apotek.."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"なるほど。傘を持ってくればよかった。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。傘を持ってくればよかった。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Kalau saja tadi bawa payung.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-00109",word:"増える",reading:"ふえる",romaji:"fueru",meaning:"bertambah, meningkat",pos:"verb-ru",nuance:"Intransitif. Transitif-nya 増やす.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"増える【ふえる】を 確認【かくにん】します。",furigana:"増えるを 確認します。",romaji:"fueru o kakunin shimasu.",idText:"Memeriksa bertambah, meningkat."}},{id:"vg-n3-00110",word:"減る",reading:"へる",romaji:"heru",meaning:"berkurang, menurun",pos:"verb-u",nuance:"Intransitif. Transitif-nya 減らす.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"減る【へる】を 確認【かくにん】します。",furigana:"減るを 確認します。",romaji:"heru o kakunin shimasu.",idText:"Memeriksa berkurang, menurun."}},{id:"vg-n3-00123",word:"伝える",reading:"つたえる",romaji:"tsutaeru",meaning:"menyampaikan, memberitahu",pos:"verb-ru",nuance:"Means 'to convey/communicate.' Transitive: 伝える (to tell someone). Compare with 伝わる (intransitive: the message gets across).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"伝える【つたえる】を 確認【かくにん】します。",furigana:"伝えるを 確認します。",romaji:"tsutaeru o kakunin shimasu.",idText:"Memeriksa menyampaikan, memberitahu."}},{id:"vg-n3-00126",word:"断る",reading:"ことわる",romaji:"kotowaru",meaning:"menolak, menampik",pos:"verb-u",nuance:"Penting dalam budaya Jepang — menolak sambil tetap sopan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"断る【ことわる】を 確認【かくにん】します。",furigana:"断るを 確認します。",romaji:"kotowaru o kakunin shimasu.",idText:"Memeriksa menolak, menampik."}},{id:"vg-n3-00127",word:"確認する",reading:"かくにんする",romaji:"kakunin suru",meaning:"mengkonfirmasi, memeriksa",pos:"verb-suru",nuance:"Sangat umum di lingkungan kerja Jepang.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"確認する【かくにんする】を 確認【かくにん】します。",furigana:"確認するを 確認します。",romaji:"kakunin suru o kakunin shimasu.",idText:"Memeriksa mengkonfirmasi, memeriksa."}},{id:"vg-n3-00128",word:"準備する",reading:"じゅんびする",romaji:"junbi suru",meaning:"mempersiapkan, bersiap",pos:"verb-suru",nuance:"Means 'to prepare.' する verb: 準備する. Slightly more formal than 用意する, which implies making something ready at hand.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"準備する【じゅんびする】を 確認【かくにん】します。",furigana:"準備するを 確認します。",romaji:"junbi suru o kakunin shimasu.",idText:"Memeriksa mempersiapkan, bersiap."}},{id:"vg-n3-00129",word:"利用する",reading:"りようする",romaji:"riyou suru",meaning:"memanfaatkan, menggunakan",pos:"verb-suru",nuance:"Lebih formal dari 使う. Untuk fasilitas, layanan, sistem.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"利用する【りようする】を 確認【かくにん】します。",furigana:"利用するを 確認します。",romaji:"riyou suru o kakunin shimasu.",idText:"Memeriksa memanfaatkan, menggunakan."}},{id:"vg-n3-00151",word:"移る",reading:"うつる",romaji:"utsuru",meaning:"pindah, beralih (sendiri)",pos:"verb-u",nuance:"Intransitif — subjek berpindah sendiri. Pasangan transitif: 移す. Berlaku untuk pindah tempat tinggal, beralihnya perhatian, hingga pergantian topik pembicaraan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"移る【うつる】を 確認【かくにん】します。",furigana:"移るを 確認します。",romaji:"utsuru o kakunin shimasu.",idText:"Memeriksa pindah, beralih (sendiri)."}}],explanations:[{id:"exp-1",grammarId:"gn3-00016",title:"Pola: 〜ついでに",formula:"Vる / Vた + ついでに / N + の + ついでに",meaning:"sambil sekalian ... / sekalian ...",nuanceNotes:'〜ついでに menyatakan memanfaatkan suatu kesempatan untuk melakukan hal lain juga: "sekalian", "sambil sekalian".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ついでに",idText:"sambil sekalian ... / sekalian ..."}],examples:[{jp:"買い物に行くついでに、薬局にも寄ります。",romaji:"",idText:"Sekalian pergi belanja, mampir juga ke apotek."},{jp:"散歩したついでに、ポストに手紙を入れた。",romaji:"",idText:"Sekalian jalan-jalan, memasukkan surat ke kotak pos."}]},{id:"exp-2",grammarId:"gn3-00037",title:"Pola: 〜ばよかった / 〜たらよかった",formula:"Vば / Vたら + よかった",meaning:"seandainya saja ... / kalau saja ...",nuanceNotes:'〜ばよかった menyatakan penyesalan atas tindakan yang tidak dilakukan atau dilakukan di masa lalu: "kalau saja tadi...", "seandainya saya...".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ばよかった / 〜たらよかった",idText:"seandainya saja ... / kalau saja ..."}],examples:[{jp:"傘を持ってくればよかった。",romaji:"",idText:"Kalau saja tadi bawa payung."},{jp:"もっと早く言ってくれたらよかったのに。",romaji:"",idText:"Seandainya saja memberitahu lebih awal."}]},{id:"exp-3",grammarId:"gn3-00045",title:"Pola: めったに〜ない",formula:"めったに + V + ない",meaning:"jarang ... / hampir tidak pernah ...",nuanceNotes:'めったに〜ない menyatakan bahwa sesuatu jarang sekali terjadi: "hampir tidak pernah", "jarang".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"めったに〜ない",idText:"jarang ... / hampir tidak pernah ..."}],examples:[{jp:"彼はめったに遅刻しない。",romaji:"",idText:"Dia hampir tidak pernah terlambat."},{jp:"この店の料理はめったに食べられない。",romaji:"",idText:"Masakan restoran ini jarang bisa dimakan."}]},{id:"exp-4",grammarId:"gn3-00053",title:"Pola: 〜かける / 〜かけの / 〜かけだ",formula:"V-ます語幹 + かける / かけの / かけだ",meaning:"setengah ... / belum selesai ...",nuanceNotes:"〜かける menyatakan suatu tindakan yang baru dimulai tapi belum selesai, atau hampir selesai. Juga bisa berarti hampir melakukan sesuatu.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜かける / 〜かけの / 〜かけだ",idText:"setengah ... / belum selesai ..."}],examples:[{jp:"食べかけのケーキがある。",romaji:"",idText:"Ada kue yang sudah dimakan setengah."},{jp:"書きかけのレポートを持ってきてください。",romaji:"",idText:"Tolong bawa laporan yang belum selesai ditulis."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "増える"?',sentencePrompt:'Makna kata "増える" (ふえる) dalam situasi kerja ini adalah:',options:["bertambah, meningkat","berkurang, menurun","menyampaikan, memberitahu","menolak, menampik"],correctAnswer:"bertambah, meningkat",explanation:'Makna yang tepat untuk "増える" adalah "bertambah, meningkat".',diagnosticFeedback:{"berkurang, menurun":'Salah: Pilihan "berkurang, menurun" adalah makna dari kata "減る" (へる), bukan arti kata "増える".',"menyampaikan, memberitahu":'Salah: Pilihan "menyampaikan, memberitahu" adalah makna dari kata "伝える" (つたえる), bukan arti kata "増える".',"menolak, menampik":'Salah: Pilihan "menolak, menampik" adalah makna dari kata "断る" (ことわる), bukan arti kata "増える".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"買い物に行く（　　）、薬局にも寄ります。",options:["ついでに","ばよかった / 〜たらよかった","めったに〜ない","きり"],correctAnswer:"ついでに",explanation:'Pola 〜ついでに bermakna "sambil sekalian ... / sekalian ...". Kalimat lengkap: "買い物に行くついでに、薬局にも寄ります。".',diagnosticFeedback:{"ばよかった / 〜たらよかった":'Salah: Pola "ばよかった / 〜たらよかった" bermakna "seandainya saja ... / kalau saja ...", yang tidak sesuai konteks kalimat ini.',"めったに〜ない":'Salah: Pola "めったに〜ない" bermakna "jarang ... / hampir tidak pernah ...", yang tidak sesuai konteks kalimat ini.',きり:'Salah: Pola "きり" bermakna "sejak ... sampai sekarang (tanpa kembali)", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜ついでに secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["散歩したついでに、ポストに手紙を入れた。","散歩したついでにでした、ポストに手紙を入れた。","傘を持ってくればよかった。","早く帰るつもりだったが、残業になった。"],correctAnswer:"散歩したついでに、ポストに手紙を入れた。",explanation:'Kalimat yang benar dan alami adalah "散歩したついでに、ポストに手紙を入れた。" (Sekalian jalan-jalan, memasukkan surat ke kotak pos.).',diagnosticFeedback:{"散歩したついでにでした、ポストに手紙を入れた。":"Jebakan Konjugasi: Pola 〜ついでに membutuhkan aturan sambung (Vる / Vた + ついでに / N + の + ついでに), bukan bentuk ini.","傘を持ってくればよかった。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜ばよかった / 〜たらよかった: seandainya saja ... / kalau saja ...), bukan kaidah 〜ついでに.","早く帰るつもりだったが、残業になった。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜ついでに secara tepat (sambil sekalian ... / sekalian ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["傘を持 ってくれ ばよかっ た。","ってくれ 傘を持 ばよかっ た。","傘を持 ばよかっ ってくれ た。","た。 傘を持 ってくれ ばよかっ"],correctAnswer:"傘を持 ってくれ ばよかっ た。",explanation:'Susunan yang benar: "傘を持 ってくれ ばよかっ た。" (Kalau saja tadi bawa payung.).',diagnosticFeedback:{"ってくれ 傘を持 ばよかっ た。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","傘を持 ばよかっ ってくれ た。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","た。 傘を持 ってくれ ばよかっ":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["傘を持","ってくれ","ばよかっ","た。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Pabrik manufaktur Nagoya saat pergantian shift kerja dan inspeksi mesin.", saat Tanaka menyampaikan arahan: 「なるほど。傘を持ってくればよかった。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 〜ついでに dan 〜ばよかった / 〜たらよかった secara mandiri.",situation:"Situasi komunikasi profesional di Pabrik manufaktur Nagoya saat pergantian shift kerja dan inspeksi mesin.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜ついでに!",modelAnswer:"はい、Tanakaさん！ 買い物に行くついでに、薬局にも寄ります。。",modelAnswerId:"Ya, Tanaka! Sekalian pergi belanja, mampir juga ke apotek..",culturalEtiquette:"Gunakan frasa waktu yang tepat untuk mencegah miskomunikasi jadwal operasional bersama rekan kerja Jepang.",skillUnlocked:["Menguasai formulasi pola 〜ついでに","Mampu menerapkan prinsip koordinasi komunikasi kerja Dimensi Waktu, Peluang & Momentum Seketika"]},pocket_summary:{keyFormula:"〜ついでに (sambil sekalian ... / sekalian ...)",coreWords:["増える【ふえる】 (bertambah, meningkat)","減る【へる】 (berkurang, menurun)","伝える【つたえる】 (menyampaikan, memberitahu)","断る【ことわる】 (menolak, menampik)"],coreWarning:"Jangan gunakan とたんに untuk rencana sengaja di masa depan; pola ini khusus fakta lampau tak terduga.",quickDialogue:"A: ブディさん、増えるの 状況【じょうきょう】は どう... → B: はい、Tanakaさん！ 買い物に行くついでに、薬..."}}},n={"les-n3-u02-01":{pedagogical_framework:{what:{summary:"Ketuntasan Tindakan, Keadaan & Perubahan Status (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜きり, 〜っぱなし, 〜たて / 〜たての, 〜切る / 〜切れる / 〜切れない, 〜上げる / 〜上がる dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜きり dan 〜っぱなし dalam percakapan kerja wajar.",targetPatterns:["〜きり (sejak ... sampai sekarang (tanpa kembali))","〜っぱなし (dibiarkan ... terus / terus-menerus ...)","〜たて / 〜たての (baru saja ... / segar ...)","〜切る / 〜切れる / 〜切れない (selesai melakukan ... sepenuhnya / tidak bisa selesai ...)","〜上げる / 〜上がる (selesai ... / menyelesaikan ...)"],coreVocabSample:["せんたく","はんだん","そしき","かんじる","かんどうする","おどろく","こまる","なやむ"]},sensei_context:{sceneIntro:"Ruang kendali lini produksi saat penyelesaian pesanan ekspor volume tinggi. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜きり dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Ketuntasan Tindakan, Keadaan & Perubahan Status",etiquette:"Laporkan selalu sisa pekerjaan yang belum tuntas dengan nada tanggung jawab profesional.",taboos:"Hindari meninggalkan mesin dalam kondisi ~ppanashi tanpa izin pengawas K3."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜きり",moraNote:"Artikulasikan vokal rangkap pada kitte / yarikiru dengan tegas tanpa memotong konsonan.",soundTip:"Ucapkan 〜きり dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜きり",caseScenario:"Menggunakan 〜きり tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜きり.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜きり sesuai kaidah.",explanation:"Kaidah koneksi 〜きり: Vた + きり / N + きり."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Ruang kendali lini produksi saat penyelesaian pesanan ekspor volume tinggi.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Ketuntasan Tindakan, Keadaan & Perubahan Status (Fondasi & Pemahaman Pola)",setting:"Ruang kendali lini produksi saat penyelesaian pesanan ekspor volume tinggi.",narrative:"Budi dan Tanaka berkoordinasi mengenai alur operasional kerja menggunakan pola 〜きり."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"ブディさん、選択の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、選択の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, sentaku no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai pilihan, pemilihan? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Tanakaさん！ 彼女は去年出かけたきり、戻ってこない。。",furigana:"はい、Tanakaさん！ 彼女は去年出かけたきり、戻ってこない。。",romaji:"Hai, Tanaka-san! きり de susumete imasu.",idText:"Ya, Tanaka! Dia pergi tahun lalu dan tidak pernah kembali sejak saat itu.."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"なるほど。電気をつけっぱなしで寝てしまった。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。電気をつけっぱなしで寝てしまった。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Tertidur dengan lampu dibiarkan menyala terus.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-00258",word:"選択",reading:"せんたく",romaji:"sentaku",meaning:"pilihan, pemilihan",pos:"noun-suru",nuance:"Tindakan memilih dari beberapa opsi. Lebih formal dari 選び (えらび). Sering dipakai dalam konteks resmi atau akademik: 選択肢 (pilihan/opsi yang tersedia).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"選択【せんたく】を 確認【かくにん】します。",furigana:"選択を 確認します。",romaji:"sentaku o kakunin shimasu.",idText:"Memeriksa pilihan, pemilihan."}},{id:"vg-n3-00259",word:"判断",reading:"はんだん",romaji:"handan",meaning:"pertimbangan, penilaian, keputusan berdasar analisis",pos:"noun-suru",nuance:"Keputusan yang dibuat berdasarkan analisis dan pertimbangan. Berbeda dari 決定 (keputusan final yang resmi) — 判断 menekankan proses berpikir dan menilai situasi.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"判断【はんだん】を 確認【かくにん】します。",furigana:"判断を 確認します。",romaji:"handan o kakunin shimasu.",idText:"Memeriksa pertimbangan, penilaian, keputusan berdasar analisis."}},{id:"vg-n3-00264",word:"組織",reading:"そしき",romaji:"soshiki",meaning:"organisasi, lembaga",pos:"noun-suru",nuance:"Kelompok yang terstruktur dengan tujuan tertentu. Juga memiliki arti 'jaringan' atau 'jaringan sel' dalam konteks biologi. Dalam konteks sosial/bisnis, mengacu pada perusahaan, instansi, atau kelompok terorganisir.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"組織【そしき】を 確認【かくにん】します。",furigana:"組織を 確認します。",romaji:"soshiki o kakunin shimasu.",idText:"Memeriksa organisasi, lembaga."}},{id:"vg-n3-00286",word:"感じる",reading:"かんじる",romaji:"kanjiru",meaning:"merasakan, merasa",pos:"verb-ru",nuance:"Kata kerja intransitif untuk merasakan sesuatu secara fisik maupun emosional. Lebih luas dari 思う (yang lebih ke opini/pikiran) — 感じる merujuk pada sensasi atau perasaan yang datang dengan sendirinya.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"感じる【かんじる】を 確認【かくにん】します。",furigana:"感じるを 確認します。",romaji:"kanjiru o kakunin shimasu.",idText:"Memeriksa merasakan, merasa."}},{id:"vg-n3-00287",word:"感動する",reading:"かんどうする",romaji:"kandou suru",meaning:"tersentuh, terharu, terkesan",pos:"verb-suru",nuance:"Menggambarkan perasaan terharu atau tersentuh yang dalam, biasanya akibat sesuatu yang indah, mengharukan, atau luar biasa. Bukan sekadar 'senang' — ada unsur getaran emosi yang kuat.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"感動する【かんどうする】を 確認【かくにん】します。",furigana:"感動するを 確認します。",romaji:"kandou suru o kakunin shimasu.",idText:"Memeriksa tersentuh, terharu, terkesan."}},{id:"vg-n3-00288",word:"驚く",reading:"おどろく",romaji:"odoroku",meaning:"terkejut, kaget",pos:"verb-u",nuance:"Reaksi spontan terhadap sesuatu yang tidak terduga. Bisa berkonotasi positif maupun negatif. Berbeda dari びっくりする yang lebih kasual dan refleks fisik — 驚く lebih luas dan bisa dipakai dalam tulisan formal.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"驚く【おどろく】を 確認【かくにん】します。",furigana:"驚くを 確認します。",romaji:"odoroku o kakunin shimasu.",idText:"Memeriksa terkejut, kaget."}},{id:"vg-n3-00289",word:"困る",reading:"こまる",romaji:"komaru",meaning:"kebingungan, kesulitan, serba salah",pos:"verb-u",nuance:"Perasaan tidak tahu harus berbuat apa karena situasi sulit atau tidak menyenangkan. Berbeda dari 悩む — 困る lebih ke situasi yang membuat repot/tidak nyaman, sedangkan 悩む lebih ke pergolakan batin dalam mengambil keputusan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"困る【こまる】を 確認【かくにん】します。",furigana:"困るを 確認します。",romaji:"komaru o kakunin shimasu.",idText:"Memeriksa kebingungan, kesulitan, serba salah."}},{id:"vg-n3-00290",word:"悩む",reading:"なやむ",romaji:"nayamu",meaning:"galau, bingung dalam dilema, merasa tersiksa batin",pos:"verb-u",nuance:"Menggambarkan keadaan batin yang bergejolak karena tidak tahu pilihan mana yang benar, atau karena beban masalah. 悩み (bentuk kata benda) juga umum. Berbeda dari 困る yang lebih ke situasi eksternal — 悩む lebih ke pergolakan internal.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"悩む【なやむ】を 確認【かくにん】します。",furigana:"悩むを 確認します。",romaji:"nayamu o kakunin shimasu.",idText:"Memeriksa galau, bingung dalam dilema, merasa tersiksa batin."}}],explanations:[{id:"exp-1",grammarId:"gn3-00054",title:"Pola: 〜きり",formula:"Vた + きり / N + きり",meaning:"sejak ... sampai sekarang (tanpa kembali)",nuanceNotes:"〜きり menyatakan bahwa setelah suatu tindakan terjadi, keadaan tersebut terus berlanjut tanpa perubahan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜きり",idText:"sejak ... sampai sekarang (tanpa kembali)"}],examples:[{jp:"彼女は去年出かけたきり、戻ってこない。",romaji:"",idText:"Dia pergi tahun lalu dan tidak pernah kembali sejak saat itu."},{jp:"二人きりで話したい。",romaji:"",idText:"Ingin bicara berdua saja."}]},{id:"exp-2",grammarId:"gn3-00055",title:"Pola: 〜っぱなし",formula:"V-ます語幹 + っぱなし",meaning:"dibiarkan ... terus / terus-menerus ...",nuanceNotes:"〜っぱなし menyatakan bahwa suatu keadaan yang diakibatkan oleh tindakan dibiarkan tanpa diselesaikan atau diperbaiki, sering bernuansa negatif.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜っぱなし",idText:"dibiarkan ... terus / terus-menerus ..."}],examples:[{jp:"電気をつけっぱなしで寝てしまった。",romaji:"",idText:"Tertidur dengan lampu dibiarkan menyala terus."},{jp:"窓を開けっぱなしにしないでください。",romaji:"",idText:"Jangan biarkan jendela terbuka terus."}]},{id:"exp-3",grammarId:"gn3-00056",title:"Pola: 〜たて / 〜たての",formula:"V-ます語幹 + たて / たての + N",meaning:"baru saja ... / segar ...",nuanceNotes:"〜たて menyatakan bahwa sesuatu baru saja selesai dikerjakan, sering dengan konotasi positif (masih segar, masih bagus).",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜たて / 〜たての",idText:"baru saja ... / segar ..."}],examples:[{jp:"炊きたてのご飯は美味しい。",romaji:"",idText:"Nasi yang baru matang itu enak."},{jp:"焼きたてのパンをどうぞ。",romaji:"",idText:"Silakan makan roti yang baru dipanggang."}]},{id:"exp-4",grammarId:"gn3-00057",title:"Pola: 〜切る / 〜切れる / 〜切れない",formula:"V-ます語幹 + 切る / 切れる / 切れない",meaning:"selesai melakukan ... sepenuhnya / tidak bisa selesai ...",nuanceNotes:"〜切る: menyelesaikan sesuatu secara total, sampai tuntas. 〜切れない: tidak bisa menyelesaikan sepenuhnya.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜切る / 〜切れる / 〜切れない",idText:"selesai melakukan ... sepenuhnya / tidak bisa selesai ..."}],examples:[{jp:"食べ切れないほどの料理が出てきた。",romaji:"",idText:"Makanan yang keluar tidak bisa dihabiskan semuanya."},{jp:"このプロジェクトを一人でやり切った。",romaji:"",idText:"Menyelesaikan proyek ini sendirian sampai tuntas."}]},{id:"exp-5",grammarId:"gn3-00058",title:"Pola: 〜上げる / 〜上がる",formula:"V-ます語幹 + 上げる (他動詞) / 上がる (自動詞)",meaning:"selesai ... / menyelesaikan ...",nuanceNotes:"〜上げる: menyelesaikan sesuatu secara menyeluruh (transitif). 〜上がる: selesai dengan sendirinya (intransitif).",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜上げる / 〜上がる",idText:"selesai ... / menyelesaikan ..."}],examples:[{jp:"レポートを書き上げた。",romaji:"",idText:"Berhasil menyelesaikan penulisan laporan."},{jp:"作品が仕上がった。",romaji:"",idText:"Karya telah selesai."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "選択"?',sentencePrompt:'Makna kata "選択" (せんたく) dalam situasi kerja ini adalah:',options:["pilihan, pemilihan","pertimbangan, penilaian, keputusan berdasar analisis","organisasi, lembaga","merasakan, merasa"],correctAnswer:"pilihan, pemilihan",explanation:'Makna yang tepat untuk "選択" adalah "pilihan, pemilihan".',diagnosticFeedback:{"pertimbangan, penilaian, keputusan berdasar analisis":'Salah: Pilihan "pertimbangan, penilaian, keputusan berdasar analisis" adalah makna dari kata "判断" (はんだん), bukan arti kata "選択".',"organisasi, lembaga":'Salah: Pilihan "organisasi, lembaga" adalah makna dari kata "組織" (そしき), bukan arti kata "選択".',"merasakan, merasa":'Salah: Pilihan "merasakan, merasa" adalah makna dari kata "感じる" (かんじる), bukan arti kata "選択".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"彼女は去年出かけた（　　）、戻ってこない。",options:["きり","っぱなし","たて / 〜たての","うえで (setelah / dalam hal)"],correctAnswer:"きり",explanation:'Pola 〜きり bermakna "sejak ... sampai sekarang (tanpa kembali)". Kalimat lengkap: "彼女は去年出かけたきり、戻ってこない。".',diagnosticFeedback:{っぱなし:'Salah: Pola "っぱなし" bermakna "dibiarkan ... terus / terus-menerus ...", yang tidak sesuai konteks kalimat ini.',"たて / 〜たての":'Salah: Pola "たて / 〜たての" bermakna "baru saja ... / segar ...", yang tidak sesuai konteks kalimat ini.',"うえで (setelah / dalam hal)":'Salah: Pola "うえで (setelah / dalam hal)" bermakna "setelah ... / dalam hal ... / untuk ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜きり secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["二人きりで話したい。","二人きりでしたで話したい。","電気をつけっぱなしで寝てしまった。","来年、日本に留学しようと思っている。"],correctAnswer:"二人きりで話したい。",explanation:'Kalimat yang benar dan alami adalah "二人きりで話したい。" (Ingin bicara berdua saja.).',diagnosticFeedback:{"二人きりでしたで話したい。":"Jebakan Konjugasi: Pola 〜きり membutuhkan aturan sambung (Vた + きり / N + きり), bukan bentuk ini.","電気をつけっぱなしで寝てしまった。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜っぱなし: dibiarkan ... terus / terus-menerus ...), bukan kaidah 〜きり.","来年、日本に留学しようと思っている。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜きり secara tepat (sejak ... sampai sekarang (tanpa kembali))."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["電気を つけっぱ なしで寝 てしまった。","つけっぱ 電気を なしで寝 てしまった。","電気を なしで寝 つけっぱ てしまった。","てしまった。 電気を つけっぱ なしで寝"],correctAnswer:"電気を つけっぱ なしで寝 てしまった。",explanation:'Susunan yang benar: "電気を つけっぱ なしで寝 てしまった。" (Tertidur dengan lampu dibiarkan menyala terus.).',diagnosticFeedback:{"つけっぱ 電気を なしで寝 てしまった。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","電気を なしで寝 つけっぱ てしまった。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","てしまった。 電気を つけっぱ なしで寝":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["電気を","つけっぱ","なしで寝","てしまった。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Ruang kendali lini produksi saat penyelesaian pesanan ekspor volume tinggi.", saat Tanaka menyampaikan arahan: 「なるほど。電気をつけっぱなしで寝てしまった。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜きり dan 〜っぱなし dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Ruang kendali lini produksi saat penyelesaian pesanan ekspor volume tinggi.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜きり!",modelAnswer:"はい、Tanakaさん！ 彼女は去年出かけたきり、戻ってこない。。",modelAnswerId:"Ya, Tanaka! Dia pergi tahun lalu dan tidak pernah kembali sejak saat itu..",culturalEtiquette:"Laporkan selalu sisa pekerjaan yang belum tuntas dengan nada tanggung jawab profesional.",skillUnlocked:["Menguasai formulasi pola 〜きり","Mampu menerapkan prinsip koordinasi komunikasi kerja Ketuntasan Tindakan, Keadaan & Perubahan Status"]},pocket_summary:{keyFormula:"〜きり (sejak ... sampai sekarang (tanpa kembali))",coreWords:["選択【せんたく】 (pilihan, pemilihan)","判断【はんだん】 (pertimbangan, penilaian, keputusan berdasar analisis)","組織【そしき】 (organisasi, lembaga)","感じる【かんじる】 (merasakan, merasa)"],coreWarning:"Hindari meninggalkan mesin dalam kondisi ~ppanashi tanpa izin pengawas K3.",quickDialogue:"A: ブディさん、選択の 状況【じょうきょう】は どうで... → B: はい、Tanakaさん！ 彼女は去年出かけたきり、..."}},"les-n3-u02-02":{pedagogical_framework:{what:{summary:"Ketuntasan Tindakan, Keadaan & Perubahan Status (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 〜ずに, 〜ちゃった / 〜ちゃう (kasual), 〜とおり（に）, 〜ものだ dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 〜ずに dan 〜ちゃった / 〜ちゃう (kasual) secara mandiri.",targetPatterns:["〜ずに (tanpa ... / tidak ... (formal))","〜ちゃった / 〜ちゃう (kasual) (sudah ... / kebablasan ... (kasual))","〜とおり（に） (sesuai dengan ... / persis seperti ...)","〜ものだ (memang sudah begitulah / wajar bahwa ...)"],coreVocabSample:["おこる","おちこむ","こうかいする","がまんする","きんちょうする","がっかりする","ほっとする","わくわくする"]},sensei_context:{sceneIntro:"Ruang kendali lini produksi saat penyelesaian pesanan ekspor volume tinggi. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 〜ずに dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Ketuntasan Tindakan, Keadaan & Perubahan Status",etiquette:"Laporkan selalu sisa pekerjaan yang belum tuntas dengan nada tanggung jawab profesional.",taboos:"Hindari meninggalkan mesin dalam kondisi ~ppanashi tanpa izin pengawas K3."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜ずに",moraNote:"Artikulasikan vokal rangkap pada kitte / yarikiru dengan tegas tanpa memotong konsonan.",soundTip:"Ucapkan 〜ずに dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜ずに",caseScenario:"Menggunakan 〜ずに tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜ずに.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜ずに sesuai kaidah.",explanation:"Kaidah koneksi 〜ずに: Vない → Vず + に."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Ruang kendali lini produksi saat penyelesaian pesanan ekspor volume tinggi.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Ketuntasan Tindakan, Keadaan & Perubahan Status (Produksi Aktif & Aplikasi Nyata)",setting:"Ruang kendali lini produksi saat penyelesaian pesanan ekspor volume tinggi.",narrative:"Budi dan Tanaka berkoordinasi mengenai alur operasional kerja menggunakan pola 〜ずに."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"ブディさん、怒るの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、怒るの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, okoru no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai marah, merasa kesal? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Tanakaさん！ 何も言わずに出て行ってしまった。。",furigana:"はい、Tanakaさん！ 何も言わずに出て行ってしまった。。",romaji:"Hai, Tanaka-san! ずに de susumete imasu.",idText:"Ya, Tanaka! Pergi begitu saja tanpa berkata apa pun.."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"なるほど。また寝坊しちゃった！ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。また寝坊しちゃった！ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Kebablasan tidur lagi!". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-00413",word:"怒る",reading:"おこる",romaji:"okoru",meaning:"marah, merasa kesal",pos:"verb-u",nuance:"怒る menggambarkan perasaan marah secara umum. Berbeda dari 叱る yang memarahi dengan tujuan mendidik (biasanya dari orang yang lebih tua/berkuasa), 怒る lebih murni mengekspresikan emosi amarah tanpa menyiratkan niat mendidik.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"怒る【おこる】を 確認【かくにん】します。",furigana:"怒るを 確認します。",romaji:"okoru o kakunin shimasu.",idText:"Memeriksa marah, merasa kesal."}},{id:"vg-n3-00416",word:"落ち込む",reading:"おちこむ",romaji:"ochikomu",meaning:"terpuruk, sangat down, kehilangan semangat",pos:"verb-u",nuance:"落ち込む menggambarkan kondisi mental yang sangat down dan kehilangan motivasi, lebih dari sekadar sedih sesaat. Berbeda dari 悲しい (かなしい) yang merupakan kata sifat untuk 'sedih', 落ち込む menyiratkan proses jatuh ke kondisi emosional yang lebih dalam dan berlangsung lebih lama.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"落ち込む【おちこむ】を 確認【かくにん】します。",furigana:"落ち込むを 確認します。",romaji:"ochikomu o kakunin shimasu.",idText:"Memeriksa terpuruk, sangat down, kehilangan semangat."}},{id:"vg-n3-00417",word:"後悔する",reading:"こうかいする",romaji:"koukai suru",meaning:"menyesal, merasa penyesalan",pos:"verb-suru",nuance:"後悔する mengacu pada penyesalan atas tindakan atau keputusan yang sudah terjadi di masa lalu. Berbeda dari 悔やむ (くやむ) yang lebih sastrawi dan terasa lebih mendalam secara emosional, 後悔する lebih umum digunakan dalam percakapan sehari-hari maupun tulisan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"後悔する【こうかいする】を 確認【かくにん】します。",furigana:"後悔するを 確認します。",romaji:"koukai suru o kakunin shimasu.",idText:"Memeriksa menyesal, merasa penyesalan."}},{id:"vg-n3-00418",word:"我慢する",reading:"がまんする",romaji:"gaman suru",meaning:"menahan diri, bersabar, bertahan",pos:"verb-suru",nuance:"我慢する menyiratkan menahan perasaan, keinginan, atau rasa sakit secara sadar — konsep ini sangat penting dalam budaya Jepang. Berbeda dari 耐える (たえる) yang terasa lebih formal dan menekankan ketahanan dalam kondisi ekstrem, 我慢する lebih sering muncul dalam percakapan sehari-hari.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"我慢する【がまんする】を 確認【かくにん】します。",furigana:"我慢するを 確認します。",romaji:"gaman suru o kakunin shimasu.",idText:"Memeriksa menahan diri, bersabar, bertahan."}},{id:"vg-n3-00419",word:"緊張する",reading:"きんちょうする",romaji:"kinchou suru",meaning:"gugup, tegang, nervous",pos:"verb-suru",nuance:"緊張する menggambarkan perasaan tegang atau gugup, baik dalam makna negatif (cemas sebelum ujian) maupun positif (tegang sebelum pertandingan penting). Berbeda dari ドキドキする yang lebih menekankan sensasi detak jantung yang cepat, 緊張する lebih luas mencakup ketegangan mental dan fisik.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"緊張する【きんちょうする】を 確認【かくにん】します。",furigana:"緊張するを 確認します。",romaji:"kinchou suru o kakunin shimasu.",idText:"Memeriksa gugup, tegang, nervous."}},{id:"vg-n3-00420",word:"がっかりする",reading:"がっかりする",romaji:"gakkari suru",meaning:"kecewa, merasa kecewa",pos:"verb-suru",nuance:"がっかりする adalah ungkapan kekecewaan yang umum dan kasual dalam percakapan sehari-hari. Berbeda dari 失望する (しつぼうする) yang lebih formal dan berat, menyiratkan kekecewaan yang serius terhadap seseorang atau sesuatu. がっかりする lebih ringan dan sering dipakai untuk situasi sehari-hari.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"がっかりするを 確認【かくにん】します。",furigana:"がっかりするを 確認します。",romaji:"gakkari suru o kakunin shimasu.",idText:"Memeriksa kecewa, merasa kecewa."}},{id:"vg-n3-00421",word:"ほっとする",reading:"ほっとする",romaji:"hotto suru",meaning:"merasa lega, napas lega",pos:"verb-suru",nuance:"ほっとする mengungkapkan rasa lega yang muncul setelah kekhawatiran atau tekanan berakhir — seperti napas lega setelah ketegangan. Berbeda dari 安心する (あんしんする) yang lebih menekankan rasa tenang dan aman secara keseluruhan, ほっとする lebih spesifik pada momen peralihan dari cemas ke lega.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"ほっとするを 確認【かくにん】します。",furigana:"ほっとするを 確認します。",romaji:"hotto suru o kakunin shimasu.",idText:"Memeriksa merasa lega, napas lega."}},{id:"vg-n3-00422",word:"わくわくする",reading:"わくわくする",romaji:"wakuwaku suru",meaning:"merasa excited, bersemangat penuh antusias",pos:"verb-suru",nuance:"わくわくする menggambarkan semangat dan antusias yang menggebu, biasanya karena mengantisipasi sesuatu yang menyenangkan. Berbeda dari 楽しみにする (たのしみにする) yang berarti 'menantikan sesuatu', わくわくする lebih menekankan perasaan gembira yang sudah terasa saat ini, bukan sekadar harapan ke depan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"わくわくするを 確認【かくにん】します。",furigana:"わくわくするを 確認します。",romaji:"wakuwaku suru o kakunin shimasu.",idText:"Memeriksa merasa excited, bersemangat penuh antusias."}}],explanations:[{id:"exp-1",grammarId:"gn3-00060",title:"Pola: 〜ずに",formula:"Vない → Vず + に",meaning:"tanpa ... / tidak ... (formal)",nuanceNotes:"〜ずに adalah bentuk formal dari ないで: tanpa melakukan sesuatu.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ずに",idText:"tanpa ... / tidak ... (formal)"}],examples:[{jp:"何も言わずに出て行ってしまった。",romaji:"",idText:"Pergi begitu saja tanpa berkata apa pun."},{jp:"食べずにずっと仕事をしていた。",romaji:"",idText:"Terus bekerja tanpa makan."}]},{id:"exp-2",grammarId:"gn3-00061",title:"Pola: 〜ちゃった / 〜ちゃう (kasual)",formula:"Vて + しまった → ちゃった / Vて + しまう → ちゃう",meaning:"sudah ... / kebablasan ... (kasual)",nuanceNotes:"〜ちゃった adalah kontraksi kasual dari てしまった: selesai secara tidak sengaja atau dengan rasa menyesal.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ちゃった / 〜ちゃう (kasual)",idText:"sudah ... / kebablasan ... (kasual)"}],examples:[{jp:"また寝坊しちゃった！",romaji:"",idText:"Kebablasan tidur lagi!"},{jp:"言わない方がよかったかも。言っちゃった。",romaji:"",idText:"Mungkin lebih baik tidak dikatakan. Telanjur bilang."}]},{id:"exp-3",grammarId:"gn3-00069",title:"Pola: 〜とおり（に）",formula:"Vた / N + の + とおり（に）",meaning:"sesuai dengan ... / persis seperti ...",nuanceNotes:"〜とおり（に） menyatakan melakukan sesuatu persis seperti yang ditunjukkan, dikatakan, atau diinstruksikan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜とおり（に）",idText:"sesuai dengan ... / persis seperti ..."}],examples:[{jp:"先生に言われたとおりにやってみました。",romaji:"",idText:"Saya mencoba melakukannya persis seperti yang dikatakan guru."},{jp:"予想したとおりになりました。",romaji:"",idText:"Hasilnya persis seperti yang diperkirakan."}]},{id:"exp-4",grammarId:"gn3-00072",title:"Pola: 〜ものだ",formula:"Vる / Adjい + ものだ",meaning:"memang sudah begitulah / wajar bahwa ...",nuanceNotes:"〜ものだ digunakan untuk: (1) menyatakan kebenaran umum atau sifat alami, (2) kenangan akan kebiasaan di masa lalu, (3) rasa kagum.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ものだ",idText:"memang sudah begitulah / wajar bahwa ..."}],examples:[{jp:"人生は思い通りにならないものだ。",romaji:"",idText:"Memang hidup tidak selalu berjalan sesuai keinginan."},{jp:"子どもの頃はよく川で遊んだものだ。",romaji:"",idText:"Waktu kecil dulu sering bermain di sungai."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "怒る"?',sentencePrompt:'Makna kata "怒る" (おこる) dalam situasi kerja ini adalah:',options:["marah, merasa kesal","terpuruk, sangat down, kehilangan semangat","menyesal, merasa penyesalan","menahan diri, bersabar, bertahan"],correctAnswer:"marah, merasa kesal",explanation:'Makna yang tepat untuk "怒る" adalah "marah, merasa kesal".',diagnosticFeedback:{"terpuruk, sangat down, kehilangan semangat":'Salah: Pilihan "terpuruk, sangat down, kehilangan semangat" adalah makna dari kata "落ち込む" (おちこむ), bukan arti kata "怒る".',"menyesal, merasa penyesalan":'Salah: Pilihan "menyesal, merasa penyesalan" adalah makna dari kata "後悔する" (こうかいする), bukan arti kata "怒る".',"menahan diri, bersabar, bertahan":'Salah: Pilihan "menahan diri, bersabar, bertahan" adalah makna dari kata "我慢する" (がまんする), bukan arti kata "怒る".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"何も言わ（　　）出て行ってしまった。",options:["ずに","ちゃった / 〜ちゃう (kasual)","とおり","うえで (setelah / dalam hal)"],correctAnswer:"ずに",explanation:'Pola 〜ずに bermakna "tanpa ... / tidak ... (formal)". Kalimat lengkap: "何も言わずに出て行ってしまった。".',diagnosticFeedback:{"ちゃった / 〜ちゃう (kasual)":'Salah: Pola "ちゃった / 〜ちゃう (kasual)" bermakna "sudah ... / kebablasan ... (kasual)", yang tidak sesuai konteks kalimat ini.',とおり:'Salah: Pola "とおり" bermakna "sesuai dengan ... / persis seperti ...", yang tidak sesuai konteks kalimat ini.',"うえで (setelah / dalam hal)":'Salah: Pola "うえで (setelah / dalam hal)" bermakna "setelah ... / dalam hal ... / untuk ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜ずに secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["食べずにずっと仕事をしていた。","食べずにでしたずっと仕事をしていた。","また寝坊しちゃった！","来年、日本に留学しようと思っている。"],correctAnswer:"食べずにずっと仕事をしていた。",explanation:'Kalimat yang benar dan alami adalah "食べずにずっと仕事をしていた。" (Terus bekerja tanpa makan.).',diagnosticFeedback:{"食べずにでしたずっと仕事をしていた。":"Jebakan Konjugasi: Pola 〜ずに membutuhkan aturan sambung (Vない → Vず + に), bukan bentuk ini.","また寝坊しちゃった！":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜ちゃった / 〜ちゃう (kasual): sudah ... / kebablasan ... (kasual)), bukan kaidah 〜ずに.","来年、日本に留学しようと思っている。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜ずに secara tepat (tanpa ... / tidak ... (formal))."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["また寝 坊し ちゃ った！","坊し また寝 ちゃ った！","また寝 ちゃ 坊し った！","った！ また寝 坊し ちゃ"],correctAnswer:"また寝 坊し ちゃ った！",explanation:'Susunan yang benar: "また寝 坊し ちゃ った！" (Kebablasan tidur lagi!).',diagnosticFeedback:{"坊し また寝 ちゃ った！":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","また寝 ちゃ 坊し った！":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","った！ また寝 坊し ちゃ":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["また寝","坊し","ちゃ","った！"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Ruang kendali lini produksi saat penyelesaian pesanan ekspor volume tinggi.", saat Tanaka menyampaikan arahan: 「なるほど。また寝坊しちゃった！ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 〜ずに dan 〜ちゃった / 〜ちゃう (kasual) secara mandiri.",situation:"Situasi komunikasi profesional di Ruang kendali lini produksi saat penyelesaian pesanan ekspor volume tinggi.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜ずに!",modelAnswer:"はい、Tanakaさん！ 何も言わずに出て行ってしまった。。",modelAnswerId:"Ya, Tanaka! Pergi begitu saja tanpa berkata apa pun..",culturalEtiquette:"Laporkan selalu sisa pekerjaan yang belum tuntas dengan nada tanggung jawab profesional.",skillUnlocked:["Menguasai formulasi pola 〜ずに","Mampu menerapkan prinsip koordinasi komunikasi kerja Ketuntasan Tindakan, Keadaan & Perubahan Status"]},pocket_summary:{keyFormula:"〜ずに (tanpa ... / tidak ... (formal))",coreWords:["怒る【おこる】 (marah, merasa kesal)","落ち込む【おちこむ】 (terpuruk, sangat down, kehilangan semangat)","後悔する【こうかいする】 (menyesal, merasa penyesalan)","我慢する【がまんする】 (menahan diri, bersabar, bertahan)"],coreWarning:"Hindari meninggalkan mesin dalam kondisi ~ppanashi tanpa izin pengawas K3.",quickDialogue:"A: ブディさん、怒るの 状況【じょうきょう】は どうで... → B: はい、Tanakaさん！ 何も言わずに出て行ってし..."}}},e={"les-n3-u03-01":{pedagogical_framework:{what:{summary:"Pengalaman, Kesiapan & Gradasi Seiring Waktu (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜うえで (setelah / dalam hal), 〜とく / 〜といて (kasual), 〜ようになる, 〜たことがある, 〜ているところだ dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜うえで (setelah / dalam hal) dan 〜とく / 〜といて (kasual) dalam percakapan kerja wajar.",targetPatterns:["〜うえで (setelah / dalam hal) (setelah ... / dalam hal ... / untuk ...)","〜とく / 〜といて (kasual) (melakukan ... terlebih dahulu (kasual))","〜ようになる (menjadi bisa ..., mulai bisa ...)","〜たことがある (pernah ... (pengalaman masa lalu))","〜ているところだ (sedang dalam proses ..., tepat sedang ...)"],coreVocabSample:["おえる","ひらく","とじる","あがる","あげる","さがる","さげる","あつまる"]},sensei_context:{sceneIntro:"Sesi evaluasi magang triwulan bersama mentor di ruang konsultasi. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜うえで (setelah / dalam hal) dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Pengalaman, Kesiapan & Gradasi Seiring Waktu",etiquette:"Tunjukkan rasa syukur atas bimbingan mentor saat menjelaskan kemajuan kemampuan bahasa dan teknis.",taboos:"Jangan tertukar antara につれて (perubahan alami satu arah) dengan にしたがって (juga bisa bermakna mematuhi aturan)."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜うえで (setelah / dalam hal)",moraNote:"Lafalkan morfem penghubung ni-tsu-re-te secara mengalir tanpa aksen mendadak di tengah frasa.",soundTip:"Ucapkan 〜うえで (setelah / dalam hal) dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜うえで (setelah / dalam hal)",caseScenario:"Menggunakan 〜うえで (setelah / dalam hal) tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜うえで (setelah / dalam hal).",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜うえで (setelah / dalam hal) sesuai kaidah.",explanation:"Kaidah koneksi 〜うえで (setelah / dalam hal): Vた / N + の + うえで."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Sesi evaluasi magang triwulan bersama mentor di ruang konsultasi.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Pengalaman, Kesiapan & Gradasi Seiring Waktu (Fondasi & Pemahaman Pola)",setting:"Sesi evaluasi magang triwulan bersama mentor di ruang konsultasi.",narrative:"Budi dan Tanaka berkoordinasi mengenai alur operasional kerja menggunakan pola 〜うえで (setelah / dalam hal)."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"ブディさん、終えるの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、終えるの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, oeru no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai menyelesaikan, merampungkan, mengakhiri? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Tanakaさん！ よく考えたうえで、決断します。。",furigana:"はい、Tanakaさん！ よく考えたうえで、決断します。。",romaji:"Hai, Tanaka-san! うえで (setelah / dalam hal) de susumete imasu.",idText:"Ya, Tanaka! Setelah memikirkan dengan baik, saya akan mengambil keputusan.."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"なるほど。宿題やっとくね。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。宿題やっとくね。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "PR kukerjakan dulu ya.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-00541",word:"終える",reading:"おえる",romaji:"oeru",meaning:"menyelesaikan, merampungkan, mengakhiri",pos:"verb-ru",nuance:"Transitif — subjek secara aktif menyelesaikan atau merampungkan suatu pekerjaan/tugas. Lebih formal dan disengaja daripada 終わる. Misalnya: 仕事を終える (merampungkan pekerjaan) terasa lebih formal dari 仕事が終わる. Dipakai saat menekankan bahwa sang pelaku benar-benar menuntaskan sesuatu.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"終える【おえる】を 確認【かくにん】します。",furigana:"終えるを 確認します。",romaji:"oeru o kakunin shimasu.",idText:"Memeriksa menyelesaikan, merampungkan, mengakhiri."}},{id:"vg-n3-00542",word:"開く",reading:"ひらく",romaji:"hiraku",meaning:"membuka, terbuka; mengadakan (acara)",pos:"verb-u",nuance:"Kata kerja ganda: sebagai intransitif ドアが開く (pintu terbuka sendiri); sebagai transitif ドアを開く (membuka pintu). Juga dipakai untuk mengadakan acara: 会議を開く (mengadakan rapat). Berbeda dari 開ける (あける) yang lebih umum untuk tindakan sehari-hari membuka benda, 開く (ひらく) terasa lebih formal dan juga dipakai untuk buku, bunga, dan acara.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"開く【ひらく】を 確認【かくにん】します。",furigana:"開くを 確認します。",romaji:"hiraku o kakunin shimasu.",idText:"Memeriksa membuka, terbuka; mengadakan (acara)."}},{id:"vg-n3-00543",word:"閉じる",reading:"とじる",romaji:"tojiru",meaning:"menutup, memejamkan",pos:"verb-ru",nuance:"Transitif — menutup buku, mata, toko, atau situasi. Berbeda dari 閉める (しめる) yang lebih dipakai untuk menutup pintu, jendela, atau kotak. 閉じる lebih cocok untuk buku (本を閉じる), mata (目を閉じる), dan file/aplikasi. 閉まる (しまる) adalah pasangan intransitifnya.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"閉じる【とじる】を 確認【かくにん】します。",furigana:"閉じるを 確認します。",romaji:"tojiru o kakunin shimasu.",idText:"Memeriksa menutup, memejamkan."}},{id:"vg-n3-00544",word:"上がる",reading:"あがる",romaji:"agaru",meaning:"naik, meningkat, masuk ke dalam (dari luar)",pos:"verb-u",nuance:"Intransitif — sesuatu naik atau meningkat dengan sendirinya. Pasangannya 上げる (transitif) berarti seseorang menaikkan sesuatu. 上がる memiliki banyak arti: naik (tangga, harga), berhenti (hujan: 雨が上がる), masuk rumah dari luar (どうぞ上がってください). Konteks sangat penting untuk membedakan artinya.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"上がる【あがる】を 確認【かくにん】します。",furigana:"上がるを 確認します。",romaji:"agaru o kakunin shimasu.",idText:"Memeriksa naik, meningkat, masuk ke dalam (dari luar)."}},{id:"vg-n3-00545",word:"上げる",reading:"あげる",romaji:"ageru",meaning:"menaikkan, meningkatkan, mengangkat",pos:"verb-ru",nuance:"Transitif — subjek menaikkan atau mengangkat objek. Pasangannya 上がる (intransitif) menyatakan sesuatu naik sendiri. Perhatikan: 上げる juga berarti 'memberikan' (memberi ke atas, kepada orang lain/hewan), dan berfungsi sebagai verba bantu て上げる yang menunjukkan melakukan sesuatu untuk orang lain.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"上げる【あげる】を 確認【かくにん】します。",furigana:"上げるを 確認します。",romaji:"ageru o kakunin shimasu.",idText:"Memeriksa menaikkan, meningkatkan, mengangkat."}},{id:"vg-n3-00546",word:"下がる",reading:"さがる",romaji:"sagaru",meaning:"turun, menurun, mundur",pos:"verb-u",nuance:"Intransitif — sesuatu turun atau berkurang dengan sendirinya. Pasangannya 下げる (transitif) berarti subjek menurunkan sesuatu. Pakai 下がる untuk harga, suhu, kualitas, atau posisi yang turun sendiri: 気温が下がる (suhu turun), 評価が下がる (penilaian menurun). Juga berarti 'mundur' secara fisik.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"下がる【さがる】を 確認【かくにん】します。",furigana:"下がるを 確認します。",romaji:"sagaru o kakunin shimasu.",idText:"Memeriksa turun, menurun, mundur."}},{id:"vg-n3-00547",word:"下げる",reading:"さげる",romaji:"sageru",meaning:"menurunkan, mengurangi, memelankan",pos:"verb-ru",nuance:"Transitif — subjek secara aktif menurunkan objek. Pasangannya 下がる (intransitif) menyatakan sesuatu turun sendiri. Dipakai untuk harga, volume suara, temperatur, dan benda fisik: 値段を下げる (menurunkan harga), 音量を下げる (memelankan volume). Juga: 頭を下げる = membungkuk sebagai bentuk hormat atau permintaan maaf.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"下げる【さげる】を 確認【かくにん】します。",furigana:"下げるを 確認します。",romaji:"sageru o kakunin shimasu.",idText:"Memeriksa menurunkan, mengurangi, memelankan."}},{id:"vg-n3-00548",word:"集まる",reading:"あつまる",romaji:"atsumaru",meaning:"berkumpul, berhimpun, terkumpul",pos:"verb-u",nuance:"Intransitif — orang, benda, atau informasi berkumpul dengan sendirinya tanpa agen yang secara aktif mengumpulkannya. Pasangannya 集める (transitif) berarti seseorang secara aktif mengumpulkan. Pakai 集まる untuk situasi di mana kumpulan terjadi secara alami: 人が集まる (orang-orang berkumpul), 情報が集まる (informasi terhimpun).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"集まる【あつまる】を 確認【かくにん】します。",furigana:"集まるを 確認します。",romaji:"atsumaru o kakunin shimasu.",idText:"Memeriksa berkumpul, berhimpun, terkumpul."}}],explanations:[{id:"exp-1",grammarId:"gn3-00091",title:"Pola: 〜うえで (setelah / dalam hal)",formula:"Vた / N + の + うえで",meaning:"setelah ... / dalam hal ... / untuk ...",nuanceNotes:"〜うえで memiliki dua makna: (1) setelah melakukan X, barulah Y (urutan); (2) dalam konteks atau bidang X.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜うえで (setelah / dalam hal)",idText:"setelah ... / dalam hal ... / untuk ..."}],examples:[{jp:"よく考えたうえで、決断します。",romaji:"",idText:"Setelah memikirkan dengan baik, saya akan mengambil keputusan."},{jp:"ビジネスの上では、礼儀が大切です。",romaji:"",idText:"Dalam hal bisnis, kesopanan itu penting."}]},{id:"exp-2",grammarId:"gn3-00102",title:"Pola: 〜とく / 〜といて (kasual)",formula:"Vて + おく → とく / といて",meaning:"melakukan ... terlebih dahulu (kasual)",nuanceNotes:"〜とく / 〜といて adalah kontraksi kasual dari 〜ておく / 〜ておいて.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜とく / 〜といて (kasual)",idText:"melakukan ... terlebih dahulu (kasual)"}],examples:[{jp:"宿題やっとくね。",romaji:"",idText:"PR kukerjakan dulu ya."},{jp:"ドアを開けといてください。",romaji:"",idText:"Tolong biarkan pintu dibuka dulu."}]},{id:"exp-3",grammarId:"gn3-00125",title:"Pola: 〜ようになる",formula:"V-plain / V-potential + ようになる",meaning:"menjadi bisa ..., mulai bisa ...",nuanceNotes:"〜ようになる menyatakan perubahan kemampuan, kebiasaan, atau keadaan yang terjadi secara bertahap seiring waktu. Pola ini digunakan untuk menggambarkan situasi sekarang yang berbeda dari sebelumnya, seringkali sebagai hasil dari proses belajar atau perubahan kondisi.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ようになる",idText:"menjadi bisa ..., mulai bisa ..."}],examples:[{jp:"練習したら、漢字が書けるようになった。",romaji:"",idText:"Setelah berlatih, saya jadi bisa menulis kanji."},{jp:"最近、早起きできるようになった。",romaji:"",idText:"Belakangan ini saya sudah bisa bangun pagi."},{jp:"日本語が上手くなって、ニュースが聞けるようになった。",romaji:"",idText:"Bahasa Jepangku makin baik, dan saya jadi bisa mendengarkan berita."}]},{id:"exp-4",grammarId:"gn3-00126",title:"Pola: 〜たことがある",formula:"V-た + ことがある",meaning:"pernah ... (pengalaman masa lalu)",nuanceNotes:"〜たことがある digunakan untuk menyatakan pengalaman di masa lalu yang pernah dialami setidaknya sekali. Berbeda dari bentuk lampau biasa, pola ini berfokus pada apakah suatu peristiwa pernah terjadi dalam kehidupan seseorang, bukan kapan tepatnya terjadi. Bentuk negatifnya adalah 〜たことがない (belum pernah).",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜たことがある",idText:"pernah ... (pengalaman masa lalu)"}],examples:[{jp:"富士山に登ったことがある。",romaji:"",idText:"Saya pernah mendaki Gunung Fuji."},{jp:"刺身を食べたことがない。",romaji:"",idText:"Saya belum pernah makan sashimi."},{jp:"子供の頃、海外に住んでいたことがある。",romaji:"",idText:"Waktu kecil, saya pernah tinggal di luar negeri."}]},{id:"exp-5",grammarId:"gn3-00129",title:"Pola: 〜ているところだ",formula:"V-て + いるところだ",meaning:"sedang dalam proses ..., tepat sedang ...",nuanceNotes:"〜ているところだ menyatakan bahwa suatu tindakan sedang berlangsung tepat pada saat itu juga. Pola ini lebih menekankan bahwa tindakan sedang berada di tengah-tengahnya, bukan sekadar menyatakan keadaan berlangsung. Sering digunakan saat seseorang datang tiba-tiba dan pembicara menjelaskan apa yang sedang dilakukannya.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ているところだ",idText:"sedang dalam proses ..., tepat sedang ..."}],examples:[{jp:"今、レポートを書いているところだ。",romaji:"",idText:"Saya sedang dalam proses menulis laporan sekarang."},{jp:"ちょうど昼ごはんを食べているところです。",romaji:"",idText:"Saya tepat sedang makan siang."},{jp:"今まさに出発しようとしているところだ。",romaji:"",idText:"Saya tepat sedang bersiap untuk berangkat sekarang."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "終える"?',sentencePrompt:'Makna kata "終える" (おえる) dalam situasi kerja ini adalah:',options:["menyelesaikan, merampungkan, mengakhiri","membuka, terbuka; mengadakan (acara)","menutup, memejamkan","naik, meningkat, masuk ke dalam (dari luar)"],correctAnswer:"menyelesaikan, merampungkan, mengakhiri",explanation:'Makna yang tepat untuk "終える" adalah "menyelesaikan, merampungkan, mengakhiri".',diagnosticFeedback:{"membuka, terbuka; mengadakan (acara)":'Salah: Pilihan "membuka, terbuka; mengadakan (acara)" adalah makna dari kata "開く" (ひらく), bukan arti kata "終える".',"menutup, memejamkan":'Salah: Pilihan "menutup, memejamkan" adalah makna dari kata "閉じる" (とじる), bukan arti kata "終える".',"naik, meningkat, masuk ke dalam (dari luar)":'Salah: Pilihan "naik, meningkat, masuk ke dalam (dari luar)" adalah makna dari kata "上がる" (あがる), bukan arti kata "終える".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"よく考えた（　　）、決断します。",options:["うえで","とく / 〜といて (kasual)","ようになる","てある"],correctAnswer:"うえで",explanation:'Pola 〜うえで (setelah / dalam hal) bermakna "setelah ... / dalam hal ... / untuk ...". Kalimat lengkap: "よく考えたうえで、決断します。".',diagnosticFeedback:{"とく / 〜といて (kasual)":'Salah: Pola "とく / 〜といて (kasual)" bermakna "melakukan ... terlebih dahulu (kasual)", yang tidak sesuai konteks kalimat ini.',ようになる:'Salah: Pola "ようになる" bermakna "menjadi bisa ..., mulai bisa ...", yang tidak sesuai konteks kalimat ini.',てある:'Salah: Pola "てある" bermakna "sudah dilakukan (keadaan hasil dari tindakan sengaja)", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜うえで (setelah / dalam hal) secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["ビジネスの上では、礼儀が大切です。","ビジネスの上では、礼儀が大切です。でした","宿題やっとくね。","今ごろ着いているはずです。"],correctAnswer:"ビジネスの上では、礼儀が大切です。",explanation:'Kalimat yang benar dan alami adalah "ビジネスの上では、礼儀が大切です。" (Dalam hal bisnis, kesopanan itu penting.).',diagnosticFeedback:{"ビジネスの上では、礼儀が大切です。でした":"Jebakan Konjugasi: Pola 〜うえで (setelah / dalam hal) membutuhkan aturan sambung (Vた / N + の + うえで), bukan bentuk ini.","宿題やっとくね。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜とく / 〜といて (kasual): melakukan ... terlebih dahulu (kasual)), bukan kaidah 〜うえで (setelah / dalam hal).","今ごろ着いているはずです。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜うえで (setelah / dalam hal) secara tepat (setelah ... / dalam hal ... / untuk ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["宿題や っと くね 。","っと 宿題や くね 。","宿題や くね っと 。","。 宿題や っと くね"],correctAnswer:"宿題や っと くね 。",explanation:'Susunan yang benar: "宿題や っと くね 。" (PR kukerjakan dulu ya.).',diagnosticFeedback:{"っと 宿題や くね 。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","宿題や くね っと 。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","。 宿題や っと くね":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["宿題や","っと","くね","。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Sesi evaluasi magang triwulan bersama mentor di ruang konsultasi.", saat Tanaka menyampaikan arahan: 「なるほど。宿題やっとくね。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜うえで (setelah / dalam hal) dan 〜とく / 〜といて (kasual) dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Sesi evaluasi magang triwulan bersama mentor di ruang konsultasi.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜うえで (setelah / dalam hal)!",modelAnswer:"はい、Tanakaさん！ よく考えたうえで、決断します。。",modelAnswerId:"Ya, Tanaka! Setelah memikirkan dengan baik, saya akan mengambil keputusan..",culturalEtiquette:"Tunjukkan rasa syukur atas bimbingan mentor saat menjelaskan kemajuan kemampuan bahasa dan teknis.",skillUnlocked:["Menguasai formulasi pola 〜うえで (setelah / dalam hal)","Mampu menerapkan prinsip koordinasi komunikasi kerja Pengalaman, Kesiapan & Gradasi Seiring Waktu"]},pocket_summary:{keyFormula:"〜うえで (setelah / dalam hal) (setelah ... / dalam hal ... / untuk ...)",coreWords:["終える【おえる】 (menyelesaikan, merampungkan, mengakhiri)","開く【ひらく】 (membuka, terbuka; mengadakan (acara))","閉じる【とじる】 (menutup, memejamkan)","上がる【あがる】 (naik, meningkat, masuk ke dalam (dari luar))"],coreWarning:"Jangan tertukar antara につれて (perubahan alami satu arah) dengan にしたがって (juga bisa bermakna mematuhi aturan).",quickDialogue:"A: ブディさん、終えるの 状況【じょうきょう】は どう... → B: はい、Tanakaさん！ よく考えたうえで、決断し..."}},"les-n3-u03-02":{pedagogical_framework:{what:{summary:"Pengalaman, Kesiapan & Gradasi Seiring Waktu (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 〜たばかりだ, 〜てしまう, 〜てみる, 〜ておく dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 〜たばかりだ dan 〜てしまう secara mandiri.",targetPatterns:["〜たばかりだ (baru saja selesai ..., baru saja ...)","〜てしまう (sudah telanjur ..., (menyesal) sudah ...)","〜てみる (mencoba melakukan ..., coba-coba ...)","〜ておく (melakukan terlebih dahulu (persiapan))"],coreVocabSample:["かたづける","せいりする","そうじする","せんたくする","すいじする","かいものする","せつやくする","ちょきんする"]},sensei_context:{sceneIntro:"Sesi evaluasi magang triwulan bersama mentor di ruang konsultasi. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 〜たばかりだ dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Pengalaman, Kesiapan & Gradasi Seiring Waktu",etiquette:"Tunjukkan rasa syukur atas bimbingan mentor saat menjelaskan kemajuan kemampuan bahasa dan teknis.",taboos:"Jangan tertukar antara につれて (perubahan alami satu arah) dengan にしたがって (juga bisa bermakna mematuhi aturan)."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜たばかりだ",moraNote:"Lafalkan morfem penghubung ni-tsu-re-te secara mengalir tanpa aksen mendadak di tengah frasa.",soundTip:"Ucapkan 〜たばかりだ dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜たばかりだ",caseScenario:"Menggunakan 〜たばかりだ tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜たばかりだ.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜たばかりだ sesuai kaidah.",explanation:"Kaidah koneksi 〜たばかりだ: V-た + ばかりだ."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Sesi evaluasi magang triwulan bersama mentor di ruang konsultasi.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Pengalaman, Kesiapan & Gradasi Seiring Waktu (Produksi Aktif & Aplikasi Nyata)",setting:"Sesi evaluasi magang triwulan bersama mentor di ruang konsultasi.",narrative:"Budi dan Tanaka berkoordinasi mengenai alur operasional kerja menggunakan pola 〜たばかりだ."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"ブディさん、片付けるの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、片付けるの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, katazukeru no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai membereskan, merapikan (sesuatu yang berantakan)? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Tanakaさん！ 日本に来たばかりで、まだ慣れていない。。",furigana:"はい、Tanakaさん！ 日本に来たばかりで、まだ慣れていない。。",romaji:"Hai, Tanaka-san! たばかりだ de susumete imasu.",idText:"Ya, Tanaka! Saya baru saja tiba di Jepang dan belum terbiasa.."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"なるほど。財布を忘れてしまった。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。財布を忘れてしまった。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Saya sudah telanjur lupa membawa dompet.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-00706",word:"片付ける",reading:"かたづける",romaji:"katazukeru",meaning:"membereskan, merapikan (sesuatu yang berantakan)",pos:"verb-ru",nuance:"Menekankan tindakan membereskan sesuatu yang berantakan atau tidak pada tempatnya — ada nuansa membuang/menyingkirkan dan menyimpan kembali. Berbeda dari 整理する yang menekankan proses menyortir dan mengorganisir secara sistematis; 片付ける lebih spontan dan berorientasi pada hasil visual (tempat menjadi rapi).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"片付ける【かたづける】を 確認【かくにん】します。",furigana:"片付けるを 確認します。",romaji:"katazukeru o kakunin shimasu.",idText:"Memeriksa membereskan, merapikan (sesuatu yang berantakan)."}},{id:"vg-n3-00707",word:"整理する",reading:"せいりする",romaji:"seiri suru",meaning:"mengorganisasi, menyortir, menata secara sistematis",pos:"verb-suru",nuance:"Menekankan proses menyortir dan mengklasifikasikan agar mudah ditemukan kembali — lebih analitis dan sistematis dari 片付ける. Bisa dipakai untuk benda fisik (dokumen, barang) maupun abstrak (pikiran, informasi). 片付ける = beresin supaya nggak berantakan; 整理する = susun supaya terstruktur.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"整理する【せいりする】を 確認【かくにん】します。",furigana:"整理するを 確認します。",romaji:"seiri suru o kakunin shimasu.",idText:"Memeriksa mengorganisasi, menyortir, menata secara sistematis."}},{id:"vg-n3-00708",word:"掃除する",reading:"そうじする",romaji:"souji suru",meaning:"membersihkan (tempat), menyapu, mengepel",pos:"verb-suru",nuance:"Fokus pada membersihkan kotoran dan debu dari suatu tempat — menyapu lantai, mengepel, mengelap permukaan. Berbeda dari 片付ける yang fokus pada merapikan benda-benda yang berantakan; 掃除する bisa dilakukan di tempat yang sudah rapi tapi kotor. Keduanya sering dilakukan bersamaan tapi maknanya berbeda.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"掃除する【そうじする】を 確認【かくにん】します。",furigana:"掃除するを 確認します。",romaji:"souji suru o kakunin shimasu.",idText:"Memeriksa membersihkan (tempat), menyapu, mengepel."}},{id:"vg-n3-00709",word:"洗濯する",reading:"せんたくする",romaji:"sentaku suru",meaning:"mencuci pakaian, melakukan laundry",pos:"verb-suru",nuance:"Secara spesifik merujuk pada mencuci pakaian atau tekstil — tidak dipakai untuk mencuci benda lain seperti piring (洗い物) atau tangan (手を洗う). Kata ini mencakup seluruh proses dari cuci hingga jemur. Di Jepang 洗濯 sangat terkait dengan mesin cuci dan rutinitas pagi.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"洗濯する【せんたくする】を 確認【かくにん】します。",furigana:"洗濯するを 確認します。",romaji:"sentaku suru o kakunin shimasu.",idText:"Memeriksa mencuci pakaian, melakukan laundry."}},{id:"vg-n3-00710",word:"炊事する",reading:"すいじする",romaji:"suiji suru",meaning:"memasak (istilah formal atau tulisan), mengurusi dapur",pos:"verb-suru",nuance:"Istilah formal untuk kegiatan memasak dan mengurus dapur — jarang dipakai dalam percakapan sehari-hari. Berbeda dari 料理する yang lebih umum dan natural dalam percakapan; 炊事する lebih sering muncul dalam tulisan, dokumen resmi, atau konteks militer/institusional (misalnya 炊事係 = petugas dapur).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"炊事する【すいじする】を 確認【かくにん】します。",furigana:"炊事するを 確認します。",romaji:"suiji suru o kakunin shimasu.",idText:"Memeriksa memasak (istilah formal atau tulisan), mengurusi dapur."}},{id:"vg-n3-00711",word:"買い物する",reading:"かいものする",romaji:"kaimono suru",meaning:"berbelanja, pergi membeli sesuatu",pos:"verb-suru",nuance:"Merujuk pada kegiatan belanja secara umum — bahan makanan, kebutuhan rumah tangga, pakaian, dll. Berbeda dari ショッピングする yang berkonotasi belanja untuk kesenangan/rekreasi (mall, fashion); 買い物する lebih netral dan mencakup belanja kebutuhan sehari-hari maupun rekreasi.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"買い物する【かいものする】を 確認【かくにん】します。",furigana:"買い物するを 確認します。",romaji:"kaimono suru o kakunin shimasu.",idText:"Memeriksa berbelanja, pergi membeli sesuatu."}},{id:"vg-n3-00712",word:"節約する",reading:"せつやくする",romaji:"setsuyaku suru",meaning:"berhemat, menghemat (uang atau sumber daya)",pos:"verb-suru",nuance:"Menekankan upaya aktif mengurangi pengeluaran atau penggunaan sumber daya — bisa untuk uang, listrik, air, dll. Berbeda dari 貯金する yang fokus pada menabung (menyimpan uang); 節約する adalah tindakan menahan diri dari pengeluaran, sedangkan 貯金する adalah hasil dari penghematan itu yang disimpan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"節約する【せつやくする】を 確認【かくにん】します。",furigana:"節約するを 確認します。",romaji:"setsuyaku suru o kakunin shimasu.",idText:"Memeriksa berhemat, menghemat (uang atau sumber daya)."}},{id:"vg-n3-00713",word:"貯金する",reading:"ちょきんする",romaji:"chokin suru",meaning:"menabung, menyisihkan uang",pos:"verb-suru",nuance:"Secara spesifik merujuk pada menyimpan uang secara rutin untuk tujuan tertentu — tabungan pribadi, bukan investasi. Berbeda dari 節約する yang berarti menahan pengeluaran; 貯金する adalah tindakan menyimpan uang yang sudah dihemat ke rekening atau celengan. Keduanya saling melengkapi.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"貯金する【ちょきんする】を 確認【かくにん】します。",furigana:"貯金するを 確認します。",romaji:"chokin suru o kakunin shimasu.",idText:"Memeriksa menabung, menyisihkan uang."}}],explanations:[{id:"exp-1",grammarId:"gn3-00130",title:"Pola: 〜たばかりだ",formula:"V-た + ばかりだ",meaning:"baru saja selesai ..., baru saja ...",nuanceNotes:"〜たばかりだ menyatakan bahwa suatu tindakan baru saja selesai dilakukan, dengan penekanan bahwa waktu yang berlalu sejak tindakan itu sangat singkat. Pola ini mengungkapkan kebaruan suatu peristiwa dari sudut pandang pembicara.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜たばかりだ",idText:"baru saja selesai ..., baru saja ..."}],examples:[{jp:"日本に来たばかりで、まだ慣れていない。",romaji:"",idText:"Saya baru saja tiba di Jepang dan belum terbiasa."},{jp:"彼女は大学を卒業したばかりだ。",romaji:"",idText:"Dia baru saja lulus dari universitas."},{jp:"今、ご飯を食べたばかりだから、お腹がいっぱいです。",romaji:"",idText:"Karena baru saja makan, perut saya sudah kenyang."}]},{id:"exp-2",grammarId:"gn3-00131",title:"Pola: 〜てしまう",formula:"V-て + しまう",meaning:"sudah telanjur ..., (menyesal) sudah ...",nuanceNotes:"〜てしまう memiliki dua makna utama: (1) menyelesaikan suatu tindakan sepenuhnya, sering dengan nuansa penyesalan atau hal yang tidak diinginkan; (2) sesuatu terjadi di luar kendali atau tanpa disengaja. Dalam percakapan kasual, sering dipendekkan menjadi 〜ちゃう (affirmative) atau 〜ちゃった (lampau).",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜てしまう",idText:"sudah telanjur ..., (menyesal) sudah ..."}],examples:[{jp:"財布を忘れてしまった。",romaji:"",idText:"Saya sudah telanjur lupa membawa dompet."},{jp:"ケーキを全部食べてしまった。",romaji:"",idText:"Kue itu sudah habis termakan semua (menyesal)."},{jp:"大切なデータを消してしまった。",romaji:"",idText:"Saya sudah telanjur menghapus data penting."}]},{id:"exp-3",grammarId:"gn3-00132",title:"Pola: 〜てみる",formula:"V-て + みる",meaning:"mencoba melakukan ..., coba-coba ...",nuanceNotes:'〜てみる menyatakan bahwa seseorang mencoba melakukan sesuatu untuk pertama kali atau untuk mengetahui hasilnya. Secara harfiah berarti "melakukan dan melihat (hasilnya)". Pola ini menyiratkan rasa penasaran atau keinginan untuk menguji sesuatu.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜てみる",idText:"mencoba melakukan ..., coba-coba ..."}],examples:[{jp:"この料理を食べてみた。とてもおいしかった。",romaji:"",idText:"Saya mencoba makan masakan ini. Ternyata sangat enak."},{jp:"一度、和服を着てみたい。",romaji:"",idText:"Saya ingin mencoba memakai kimono sekali."},{jp:"新しいアプリを使ってみたら、便利だった。",romaji:"",idText:"Setelah mencoba menggunakan aplikasi baru, ternyata praktis."}]},{id:"exp-4",grammarId:"gn3-00133",title:"Pola: 〜ておく",formula:"V-て + おく",meaning:"melakukan terlebih dahulu (persiapan)",nuanceNotes:'〜ておく menyatakan tindakan yang dilakukan sebelumnya sebagai persiapan untuk sesuatu di masa depan, atau membiarkan suatu keadaan tetap sebagaimana adanya. Kata おく (oku) secara harfiah berarti "meletakkan/meninggalkan", sehingga pola ini mengandung makna melakukan sesuatu dan "meninggalkannya" dalam keadaan siap.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ておく",idText:"melakukan terlebih dahulu (persiapan)"}],examples:[{jp:"旅行前にホテルを予約しておいた。",romaji:"",idText:"Saya sudah memesan hotel lebih dahulu sebelum bepergian."},{jp:"明日の会議のために資料を準備しておいてください。",romaji:"",idText:"Tolong siapkan materi lebih dahulu untuk rapat besok."},{jp:"窓を開けておきましょう。",romaji:"",idText:"Mari biarkan jendela tetap terbuka (untuk persiapan)."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "片付ける"?',sentencePrompt:'Makna kata "片付ける" (かたづける) dalam situasi kerja ini adalah:',options:["membereskan, merapikan (sesuatu yang berantakan)","mengorganisasi, menyortir, menata secara sistematis","membersihkan (tempat), menyapu, mengepel","mencuci pakaian, melakukan laundry"],correctAnswer:"membereskan, merapikan (sesuatu yang berantakan)",explanation:'Makna yang tepat untuk "片付ける" adalah "membereskan, merapikan (sesuatu yang berantakan)".',diagnosticFeedback:{"mengorganisasi, menyortir, menata secara sistematis":'Salah: Pilihan "mengorganisasi, menyortir, menata secara sistematis" adalah makna dari kata "整理する" (せいりする), bukan arti kata "片付ける".',"membersihkan (tempat), menyapu, mengepel":'Salah: Pilihan "membersihkan (tempat), menyapu, mengepel" adalah makna dari kata "掃除する" (そうじする), bukan arti kata "片付ける".',"mencuci pakaian, melakukan laundry":'Salah: Pilihan "mencuci pakaian, melakukan laundry" adalah makna dari kata "洗濯する" (せんたくする), bukan arti kata "片付ける".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"日本に来（　　）、まだ慣れていない。",options:["たばかりで","てしまう","てみる","てある"],correctAnswer:"たばかりで",explanation:'Pola 〜たばかりだ bermakna "baru saja selesai ..., baru saja ...". Kalimat lengkap: "日本に来たばかりで、まだ慣れていない。".',diagnosticFeedback:{てしまう:'Salah: Pola "てしまう" bermakna "sudah telanjur ..., (menyesal) sudah ...", yang tidak sesuai konteks kalimat ini.',てみる:'Salah: Pola "てみる" bermakna "mencoba melakukan ..., coba-coba ...", yang tidak sesuai konteks kalimat ini.',てある:'Salah: Pola "てある" bermakna "sudah dilakukan (keadaan hasil dari tindakan sengaja)", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜たばかりだ secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["彼女は大学を卒業したばかりだ。","彼女は大学を卒業したばかりだでした。","財布を忘れてしまった。","今ごろ着いているはずです。"],correctAnswer:"彼女は大学を卒業したばかりだ。",explanation:'Kalimat yang benar dan alami adalah "彼女は大学を卒業したばかりだ。" (Dia baru saja lulus dari universitas.).',diagnosticFeedback:{"彼女は大学を卒業したばかりだでした。":"Jebakan Konjugasi: Pola 〜たばかりだ membutuhkan aturan sambung (V-た + ばかりだ), bukan bentuk ini.","財布を忘れてしまった。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜てしまう: sudah telanjur ..., (menyesal) sudah ...), bukan kaidah 〜たばかりだ.","今ごろ着いているはずです。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜たばかりだ secara tepat (baru saja selesai ..., baru saja ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["財布を 忘れ てし まった。","忘れ 財布を てし まった。","財布を てし 忘れ まった。","まった。 財布を 忘れ てし"],correctAnswer:"財布を 忘れ てし まった。",explanation:'Susunan yang benar: "財布を 忘れ てし まった。" (Saya sudah telanjur lupa membawa dompet.).',diagnosticFeedback:{"忘れ 財布を てし まった。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","財布を てし 忘れ まった。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","まった。 財布を 忘れ てし":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["財布を","忘れ","てし","まった。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Sesi evaluasi magang triwulan bersama mentor di ruang konsultasi.", saat Tanaka menyampaikan arahan: 「なるほど。財布を忘れてしまった。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 〜たばかりだ dan 〜てしまう secara mandiri.",situation:"Situasi komunikasi profesional di Sesi evaluasi magang triwulan bersama mentor di ruang konsultasi.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜たばかりだ!",modelAnswer:"はい、Tanakaさん！ 日本に来たばかりで、まだ慣れていない。。",modelAnswerId:"Ya, Tanaka! Saya baru saja tiba di Jepang dan belum terbiasa..",culturalEtiquette:"Tunjukkan rasa syukur atas bimbingan mentor saat menjelaskan kemajuan kemampuan bahasa dan teknis.",skillUnlocked:["Menguasai formulasi pola 〜たばかりだ","Mampu menerapkan prinsip koordinasi komunikasi kerja Pengalaman, Kesiapan & Gradasi Seiring Waktu"]},pocket_summary:{keyFormula:"〜たばかりだ (baru saja selesai ..., baru saja ...)",coreWords:["片付ける【かたづける】 (membereskan, merapikan (sesuatu yang berantakan))","整理する【せいりする】 (mengorganisasi, menyortir, menata secara sistematis)","掃除する【そうじする】 (membersihkan (tempat), menyapu, mengepel)","洗濯する【せんたくする】 (mencuci pakaian, melakukan laundry)"],coreWarning:"Jangan tertukar antara につれて (perubahan alami satu arah) dengan にしたがって (juga bisa bermakna mematuhi aturan).",quickDialogue:"A: ブディさん、片付けるの 状況【じょうきょう】は ど... → B: はい、Tanakaさん！ 日本に来たばかりで、まだ..."}}},i={"les-n3-u04-01":{pedagogical_framework:{what:{summary:"Penyesalan Masa Lalu & Harapan Hipotetis (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜てある, 〜とともに, 〜につれて, 〜に従って, 〜ばよかった dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜てある dan 〜とともに dalam percakapan kerja wajar.",targetPatterns:["〜てある (sudah dilakukan (keadaan hasil dari tindakan sengaja))","〜とともに (bersamaan dengan ..., bersama-sama dengan ...)","〜につれて (seiring dengan ..., semakin ... semakin ...)","〜に従って (sesuai dengan ..., mengikuti ..., seiring dengan ...)","〜ばよかった (seandainya tadi aku ..., andai saja aku ... (penyesalan lampau))"],coreVocabSample:["しんぽ","すいせん","すくう","すぐれる","スケート","すごす","すすめる","すすめる"]},sensei_context:{sceneIntro:"Briefing insiden keselamatan kerja setelah terjadi keterlambatan pengiriman logistik. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜てある dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Penyesalan Masa Lalu & Harapan Hipotetis",etiquette:"Dalam budaya kerja Jepang, pengakuan penyesalan introspektif (hansei) adalah langkah awal perbaikan Kaizen.",taboos:"Jangan menyalahkan rekan lain saat menyatakan penyesalan dalam forum resmi perusahaan."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜てある",moraNote:"Gunakan intonasi turun lembut pada akhir kalimat ba yokatta untuk mencerminkan nada introspeksi tulus.",soundTip:"Ucapkan 〜てある dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜てある",caseScenario:"Menggunakan 〜てある tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜てある.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜てある sesuai kaidah.",explanation:"Kaidah koneksi 〜てある: V-て (他動詞) + ある."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Briefing insiden keselamatan kerja setelah terjadi keterlambatan pengiriman logistik.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Penyesalan Masa Lalu & Harapan Hipotetis (Fondasi & Pemahaman Pola)",setting:"Briefing insiden keselamatan kerja setelah terjadi keterlambatan pengiriman logistik.",narrative:"Budi dan Tanaka berkoordinasi mengenai alur operasional kerja menggunakan pola 〜てある."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"ブディさん、進歩の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、進歩の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, shinpo no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai kemajuan, perkembangan (ke arah lebih baik)? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Tanakaさん！ 黒板に予定が書いてある。。",furigana:"はい、Tanakaさん！ 黒板に予定が書いてある。。",romaji:"Hai, Tanaka-san! てある de susumete imasu.",idText:"Ya, Tanaka! Jadwal sudah dituliskan di papan tulis (masih ada di sana).."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"なるほど。時間とともに、傷は癒えていった。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。時間とともに、傷は癒えていった。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Seiring dengan waktu, luka itu perlahan sembuh.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-00892",word:"進歩",reading:"しんぽ",romaji:"shinpo",meaning:"kemajuan, perkembangan (ke arah lebih baik)",pos:"verb-suru",nuance:"Kemajuan atau peningkatan mutu ke tahap yang lebih tinggi dan canggih, terutama dalam sains, teknologi, kemampuan individu, atau peradaban (科学の進歩 - kemajuan sains). Berbeda dengan 発達 (hattatsu) yang mencakup pertumbuhan fisik/fisiologis, dan 進化 (shinka) yang berarti evolusi.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"進歩【しんぽ】を 確認【かくにん】します。",furigana:"進歩を 確認します。",romaji:"shinpo o kakunin shimasu.",idText:"Memeriksa kemajuan, perkembangan (ke arah lebih baik)."}},{id:"vg-n3-00900",word:"推薦",reading:"すいせん",romaji:"suisen",meaning:"rekomendasi, pencalonan, pengusulan",pos:"verb-suru",nuance:"Menyarankan atau mengusulkan seseorang atau karya kepada pihak lain karena dinilai berkemampuan atau bermutu tinggi (seperti 推薦状 - surat rekomendasi, 推薦入試 - seleksi masuk jalur rekomendasi). Berbeda dengan 提案 (teian) yang mengusulkan rencana/ide, 推薦 berfokus mengusulkan kandidat atau pilihan unggulan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"推薦【すいせん】を 確認【かくにん】します。",furigana:"推薦を 確認します。",romaji:"suisen o kakunin shimasu.",idText:"Memeriksa rekomendasi, pencalonan, pengusulan."}},{id:"vg-n3-00907",word:"救う",reading:"すくう",romaji:"sukuu",meaning:"menyelamatkan, menolong (dari bahaya/kesusahan berat)",pos:"verb-u",nuance:"Kata kerja transitif godan golongan 1. Menyelamatkan seseorang dari mara bahaya, maut, krisis ekonomi berat, atau kesengsaraan hidup (misal 命を救う - menyelamatkan nyawa, 危機から救う - menyelamatkan dari krisis). Nuansanya jauh lebih serius, dramatis, dan mendalam dibandingkan 助ける (tasukeru) yang bisa untuk tolong-menolong ringan harian.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"救う【すくう】を 確認【かくにん】します。",furigana:"救うを 確認します。",romaji:"sukuu o kakunin shimasu.",idText:"Memeriksa menyelamatkan, menolong (dari bahaya/kesusahan berat)."}},{id:"vg-n3-00908",word:"優れる",reading:"すぐれる",romaji:"sugureru",meaning:"unggul, menonjol, prima (kualitas/kondisi)",pos:"verb-ru",nuance:"Kata kerja intransitif ichidan. Menunjukkan keunggulan dalam bakat, mutu, performa, atau teknologi melebihi standar biasa (seperti 優れた才能 - bakat luar biasa, 性能が優れている - performanya unggul). Bentuk negatifnya (優れない) sangat umum digunakan secara idiomatik untuk kondisi badan yang kurang fit (体調が優れない - kurang enak badan).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"優れる【すぐれる】を 確認【かくにん】します。",furigana:"優れるを 確認します。",romaji:"sugureru o kakunin shimasu.",idText:"Memeriksa unggul, menonjol, prima (kualitas/kondisi)."}},{id:"vg-n3-00909",word:"スケート",reading:"スケート",romaji:"sukeeto",meaning:"seluncur es, sepatu luncur; bermain skating",pos:"verb-suru",nuance:"Olahraga meluncur di atas permukaan es menggunakan sepatu berbilah pisau (アイススケート) atau meluncur di lantai dengan sepatu roda (インラインスケート). Digabung dengan する menjadi kata kerja meluncur/bermain seluncur es (スケートをする).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"スケートを 確認【かくにん】します。",furigana:"スケートを 確認します。",romaji:"sukeeto o kakunin shimasu.",idText:"Memeriksa seluncur es, sepatu luncur; bermain skating."}},{id:"vg-n3-00911",word:"過ごす",reading:"すごす",romaji:"sugosu",meaning:"menghabiskan (waktu), melewatkan, menjalani (masa/hari)",pos:"verb-u",nuance:"Kata kerja transitif godan golongan 1. Digunakan dengan objek rentang waktu (seperti 休日を過ごす - menghabiskan liburan, 一生を過ごす - menjalani seumur hidup). Menunjukkan cara seseorang mengisi dan menjalani kurun waktu tertentu. Sering juga bertindak sebagai sufiks verba penanda 'berlebihan' (seperti 食べ過ごす, 寝過ごす).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"過ごす【すごす】を 確認【かくにん】します。",furigana:"過ごすを 確認します。",romaji:"sugosu o kakunin shimasu.",idText:"Memeriksa menghabiskan (waktu), melewatkan, menjalani (masa/hari)."}},{id:"vg-n3-00913",word:"進める",reading:"すすめる",romaji:"susumeru",meaning:"memajukan, melanjutkan, menjalankan (pekerjaan/rencana)",pos:"verb-ru",nuance:"Kata kerja transitif ichidan (pasangan transitif dari 進む - susumu). Menggerakkan sesuatu ke depan, baik secara fisik (memajukan jarum jam: 時計の針を進める) maupun abstrak (menjalankan proyek, memajukan proses negosiasi: 計画を進める). Berbeda makna dan kanji dengan 勧める (menganjurkan/menawari) dan 薦める (merekomendasikan orang).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"進める【すすめる】を 確認【かくにん】します。",furigana:"進めるを 確認します。",romaji:"susumeru o kakunin shimasu.",idText:"Memeriksa memajukan, melanjutkan, menjalankan (pekerjaan/rencana)."}},{id:"vg-n3-00914",word:"勧める",reading:"すすめる",romaji:"susumeru",meaning:"menyarankan, menganjurkan, menawari (tindakan/barang)",pos:"verb-ru",nuance:"Kata kerja transitif ichidan. Mengajak, menawari, atau menganjurkan seseorang untuk melakukan hal tertentu atau mencoba sesuatu yang baik (seperti お茶を勧める - menawari teh, 禁煙を勧める - menganjurkan berhenti merokok). Berbeda dengan 進める (memajukan) dan 薦める (merekomendasikan orang untuk posisi/buku unggulan).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"勧める【すすめる】を 確認【かくにん】します。",furigana:"勧めるを 確認します。",romaji:"susumeru o kakunin shimasu.",idText:"Memeriksa menyarankan, menganjurkan, menawari (tindakan/barang)."}}],explanations:[{id:"exp-1",grammarId:"gn3-00134",title:"Pola: 〜てある",formula:"V-て (他動詞) + ある",meaning:"sudah dilakukan (keadaan hasil dari tindakan sengaja)",nuanceNotes:"〜てある menyatakan suatu keadaan yang merupakan hasil dari tindakan yang sengaja dilakukan oleh seseorang. Berbeda dari 〜ている yang hanya menyatakan keadaan, 〜てある menyiratkan bahwa ada orang yang sengaja melakukan tindakan itu untuk suatu tujuan. Pola ini hanya digunakan dengan kata kerja transitif (他動詞).",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜てある",idText:"sudah dilakukan (keadaan hasil dari tindakan sengaja)"}],examples:[{jp:"黒板に予定が書いてある。",romaji:"",idText:"Jadwal sudah dituliskan di papan tulis (masih ada di sana)."},{jp:"明日のために、お弁当が作ってある。",romaji:"",idText:"Bekal untuk besok sudah dibuat (dan siap)."},{jp:"部屋に花が飾ってある。",romaji:"",idText:"Bunga sudah dipajang di kamar (ada yang meletakkannya dengan sengaja)."}]},{id:"exp-2",grammarId:"gn3-00145",title:"Pola: 〜とともに",formula:"N + とともに / V-plain + とともに",meaning:"bersamaan dengan ..., bersama-sama dengan ...",nuanceNotes:'〜とともに memiliki dua makna utama: (1) "bersama dengan" — menyatakan bahwa dua hal atau orang melakukan sesuatu secara bersamaan; (2) "seiring dengan" — menyatakan bahwa dua perubahan terjadi secara paralel. Dalam makna kedua, fungsinya mirip dengan 〜につれて atau 〜に従って.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜とともに",idText:"bersamaan dengan ..., bersama-sama dengan ..."}],examples:[{jp:"時間とともに、傷は癒えていった。",romaji:"",idText:"Seiring dengan waktu, luka itu perlahan sembuh."},{jp:"彼女は家族とともに、旅行に出かけた。",romaji:"",idText:"Dia pergi berwisata bersama keluarganya."},{jp:"技術の進歩とともに、生活が便利になった。",romaji:"",idText:"Seiring dengan kemajuan teknologi, kehidupan menjadi lebih praktis."}]},{id:"exp-3",grammarId:"gn3-00146",title:"Pola: 〜につれて",formula:"V-plain / N + につれて",meaning:"seiring dengan ..., semakin ... semakin ...",nuanceNotes:"〜につれて menyatakan bahwa seiring suatu hal berubah atau berkembang, hal lain juga berubah secara proporsional dan bertahap. Hubungan ini bersifat paralel dan terus-menerus: ketika A berubah, B pun ikut berubah. Biasanya digunakan untuk perubahan yang terjadi secara alami dari waktu ke waktu.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜につれて",idText:"seiring dengan ..., semakin ... semakin ..."}],examples:[{jp:"年をとるにつれて、体力が落ちてきた。",romaji:"",idText:"Seiring bertambahnya usia, stamina pun mulai menurun."},{jp:"春が近づくにつれて、気温が上がってきた。",romaji:"",idText:"Seiring mendekatnya musim semi, suhu pun mulai naik."},{jp:"経験を積むにつれて、仕事が上手くなった。",romaji:"",idText:"Seiring bertambahnya pengalaman, pekerjaan pun menjadi semakin baik."}]},{id:"exp-4",grammarId:"gn3-00147",title:"Pola: 〜に従って",formula:"N + に従って / V-plain + に従って",meaning:"sesuai dengan ..., mengikuti ..., seiring dengan ...",nuanceNotes:'〜に従って memiliki dua makna: (1) "mengikuti/sesuai dengan" — menyatakan bahwa seseorang bertindak sesuai dengan aturan, instruksi, atau pedoman tertentu; (2) "seiring dengan" — menyatakan bahwa perubahan terjadi paralel dengan perubahan lain. Makna kedua mirip dengan 〜につれて.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜に従って",idText:"sesuai dengan ..., mengikuti ..., seiring dengan ..."}],examples:[{jp:"規則に従って、行動してください。",romaji:"",idText:"Tolong bertindak sesuai dengan aturan yang berlaku."},{jp:"時代が変わるに従って、言葉も変化する。",romaji:"",idText:"Seiring perubahan zaman, kata-kata pun ikut berubah."},{jp:"地図に従って、目的地を目指した。",romaji:"",idText:"Saya menuju tujuan sesuai dengan peta."}]},{id:"exp-5",grammarId:"gn3-00163",title:"Pola: 〜ばよかった",formula:"V-ば (conditional) + よかった",meaning:"seandainya tadi aku ..., andai saja aku ... (penyesalan lampau)",nuanceNotes:"〜ばよかった menyatakan penyesalan atas sesuatu yang tidak dilakukan di masa lalu — pembicara menginginkan tindakan berbeda dari yang terjadi. Pola ini dibentuk dengan mengubah verba ke bentuk kondisional ば, kemudian menambahkan よかった (seharusnya baik). Digunakan saat pembicara menyesal tidak melakukan sesuatu.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ばよかった",idText:"seandainya tadi aku ..., andai saja aku ... (penyesalan lampau)"}],examples:[{jp:"傘を持ってくればよかった。",romaji:"",idText:"Seandainya tadi aku membawa payung."},{jp:"もっと早く起きればよかった。",romaji:"",idText:"Andai saja tadi aku bangun lebih awal."},{jp:"彼に正直に話せばよかったと後悔している。",romaji:"",idText:"Aku menyesal — andai saja aku berbicara jujur kepadanya."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "進歩"?',sentencePrompt:'Makna kata "進歩" (しんぽ) dalam situasi kerja ini adalah:',options:["kemajuan, perkembangan (ke arah lebih baik)","rekomendasi, pencalonan, pengusulan","menyelamatkan, menolong (dari bahaya/kesusahan berat)","unggul, menonjol, prima (kualitas/kondisi)"],correctAnswer:"kemajuan, perkembangan (ke arah lebih baik)",explanation:'Makna yang tepat untuk "進歩" adalah "kemajuan, perkembangan (ke arah lebih baik)".',diagnosticFeedback:{"rekomendasi, pencalonan, pengusulan":'Salah: Pilihan "rekomendasi, pencalonan, pengusulan" adalah makna dari kata "推薦" (すいせん), bukan arti kata "進歩".',"menyelamatkan, menolong (dari bahaya/kesusahan berat)":'Salah: Pilihan "menyelamatkan, menolong (dari bahaya/kesusahan berat)" adalah makna dari kata "救う" (すくう), bukan arti kata "進歩".',"unggul, menonjol, prima (kualitas/kondisi)":'Salah: Pilihan "unggul, menonjol, prima (kualitas/kondisi)" adalah makna dari kata "優れる" (すぐれる), bukan arti kata "進歩".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"黒板に予定が書い（　　）。",options:["てある","とともに","につれて","つもりだった"],correctAnswer:"てある",explanation:'Pola 〜てある bermakna "sudah dilakukan (keadaan hasil dari tindakan sengaja)". Kalimat lengkap: "黒板に予定が書いてある。".',diagnosticFeedback:{とともに:'Salah: Pola "とともに" bermakna "bersamaan dengan ..., bersama-sama dengan ...", yang tidak sesuai konteks kalimat ini.',につれて:'Salah: Pola "につれて" bermakna "seiring dengan ..., semakin ... semakin ...", yang tidak sesuai konteks kalimat ini.',つもりだった:'Salah: Pola "つもりだった" bermakna "tadinya bermaksud ... / rencananya ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜てある secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["明日のために、お弁当が作ってある。","明日のために、お弁当が作ってあるでした。","時間とともに、傷は癒えていった。","今こそ行動するときだ！"],correctAnswer:"明日のために、お弁当が作ってある。",explanation:'Kalimat yang benar dan alami adalah "明日のために、お弁当が作ってある。" (Bekal untuk besok sudah dibuat (dan siap).).',diagnosticFeedback:{"明日のために、お弁当が作ってあるでした。":"Jebakan Konjugasi: Pola 〜てある membutuhkan aturan sambung (V-て (他動詞) + ある), bukan bentuk ini.","時間とともに、傷は癒えていった。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜とともに: bersamaan dengan ..., bersama-sama dengan ...), bukan kaidah 〜てある.","今こそ行動するときだ！":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜てある secara tepat (sudah dilakukan (keadaan hasil dari tindakan sengaja))."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["時間とともに 、 傷は癒えていった 。","、 時間とともに 傷は癒えていった 。","時間とともに 傷は癒えていった 、 。","。 時間とともに 、 傷は癒えていった"],correctAnswer:"時間とともに 、 傷は癒えていった 。",explanation:'Susunan yang benar: "時間とともに 、 傷は癒えていった 。" (Seiring dengan waktu, luka itu perlahan sembuh.).',diagnosticFeedback:{"、 時間とともに 傷は癒えていった 。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","時間とともに 傷は癒えていった 、 。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","。 時間とともに 、 傷は癒えていった":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["時間とともに","、","傷は癒えていった","。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Briefing insiden keselamatan kerja setelah terjadi keterlambatan pengiriman logistik.", saat Tanaka menyampaikan arahan: 「なるほど。時間とともに、傷は癒えていった。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜てある dan 〜とともに dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Briefing insiden keselamatan kerja setelah terjadi keterlambatan pengiriman logistik.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜てある!",modelAnswer:"はい、Tanakaさん！ 黒板に予定が書いてある。。",modelAnswerId:"Ya, Tanaka! Jadwal sudah dituliskan di papan tulis (masih ada di sana)..",culturalEtiquette:"Dalam budaya kerja Jepang, pengakuan penyesalan introspektif (hansei) adalah langkah awal perbaikan Kaizen.",skillUnlocked:["Menguasai formulasi pola 〜てある","Mampu menerapkan prinsip koordinasi komunikasi kerja Penyesalan Masa Lalu & Harapan Hipotetis"]},pocket_summary:{keyFormula:"〜てある (sudah dilakukan (keadaan hasil dari tindakan sengaja))",coreWords:["進歩【しんぽ】 (kemajuan, perkembangan (ke arah lebih baik))","推薦【すいせん】 (rekomendasi, pencalonan, pengusulan)","救う【すくう】 (menyelamatkan, menolong (dari bahaya/kesusahan berat))","優れる【すぐれる】 (unggul, menonjol, prima (kualitas/kondisi))"],coreWarning:"Jangan menyalahkan rekan lain saat menyatakan penyesalan dalam forum resmi perusahaan.",quickDialogue:"A: ブディさん、進歩の 状況【じょうきょう】は どうで... → B: はい、Tanakaさん！ 黒板に予定が書いてある。..."}},"les-n3-u04-02":{pedagogical_framework:{what:{summary:"Penyesalan Masa Lalu & Harapan Hipotetis (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 〜ればよかった, 〜なければよかった, 〜とよかった, 〜（よ）うとする / 〜（よ）うとしない dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 〜ればよかった dan 〜なければよかった secara mandiri.",targetPatterns:["〜ればよかった (seandainya ..., kalau saja ... (penyesalan, fokus pada verba berakhiran れば))","〜なければよかった (seandainya tidak ..., andai tidak ... (penyesalan sudah melakukan sesuatu))","〜とよかった (seandainya ..., kalau saja ... (penyesalan lampau, nuansa fatalistis))","〜（よ）うとする / 〜（よ）うとしない (berusaha / hendak melakukan ... / tidak mau ...)"],coreVocabSample:["えんじょ","えんぜつ","えんそう","おいつく","おう","おうえん","おうじる","おうだん"]},sensei_context:{sceneIntro:"Briefing insiden keselamatan kerja setelah terjadi keterlambatan pengiriman logistik. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 〜ればよかった dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Penyesalan Masa Lalu & Harapan Hipotetis",etiquette:"Dalam budaya kerja Jepang, pengakuan penyesalan introspektif (hansei) adalah langkah awal perbaikan Kaizen.",taboos:"Jangan menyalahkan rekan lain saat menyatakan penyesalan dalam forum resmi perusahaan."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜ればよかった",moraNote:"Gunakan intonasi turun lembut pada akhir kalimat ba yokatta untuk mencerminkan nada introspeksi tulus.",soundTip:"Ucapkan 〜ればよかった dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜ればよかった",caseScenario:"Menggunakan 〜ればよかった tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜ればよかった.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜ればよかった sesuai kaidah.",explanation:"Kaidah koneksi 〜ればよかった: V-れば (ichidan / suru / kuru conditional) + よかった."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Briefing insiden keselamatan kerja setelah terjadi keterlambatan pengiriman logistik.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Penyesalan Masa Lalu & Harapan Hipotetis (Produksi Aktif & Aplikasi Nyata)",setting:"Briefing insiden keselamatan kerja setelah terjadi keterlambatan pengiriman logistik.",narrative:"Budi dan Tanaka berkoordinasi mengenai alur operasional kerja menggunakan pola 〜ればよかった."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"ブディさん、援助の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、援助の 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, enjo no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai bantuan, pertolongan, sokongan? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Tanakaさん！ もっとよく勉強すればよかった。。",furigana:"はい、Tanakaさん！ もっとよく勉強すればよかった。。",romaji:"Hai, Tanaka-san! ればよかった de susumete imasu.",idText:"Ya, Tanaka! Seandainya aku belajar lebih giat dulu.."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Pabrik",avatar:"🧑‍💼",jp:"なるほど。あんなことを言わなければよかった。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。あんなことを言わなければよかった。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Seandainya aku tidak mengucapkan hal seperti itu.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-01084",word:"援助",reading:"えんじょ",romaji:"enjo",meaning:"bantuan, pertolongan, sokongan",pos:"verb-suru",nuance:"Pemberian bantuan finansial, logistik, atau daya tenaga kepada mereka yang berada dalam kondisi kesulitan (援助する). Bersifat lebih formal daripada 手伝い (tetsudai) yang merupakan bantuan tenaga ringan sehari-hari, dan sering dipakai dalam skala internasional (国際援助) atau permodalan usaha.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"援助【えんじょ】を 確認【かくにん】します。",furigana:"援助を 確認します。",romaji:"enjo o kakunin shimasu.",idText:"Memeriksa bantuan, pertolongan, sokongan."}},{id:"vg-n3-01086",word:"演説",reading:"えんぜつ",romaji:"enzetsu",meaning:"pidato, orasi politik",pos:"verb-suru",nuance:"Merujuk pada pidato resmi di hadapan khalayak ramai, khususnya yang berkaitan dengan politik, kampanye, atau pandangan sosial. Berbeda dengan スピーチ (supiichi) yang bisa dipakai untuk sambutan santai di pesta atau pernikahan, 演説 jauh lebih formal dan berbobot politis.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"演説【えんぜつ】を 確認【かくにん】します。",furigana:"演説を 確認します。",romaji:"enzetsu o kakunin shimasu.",idText:"Memeriksa pidato, orasi politik."}},{id:"vg-n3-01087",word:"演奏",reading:"えんそう",romaji:"ensou",meaning:"pertunjukan musik, memainkan alat musik",pos:"verb-suru",nuance:"Digunakan khusus untuk memainkan alat musik atau membawakan karya musik di depan penonton atau dalam rekaman. Berbeda dengan 演技 (engi) yang merujuk pada seni peran/akting, serta berbeda dengan 歌う (utau) yang berfokus pada melantunkan vokal.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"演奏【えんそう】を 確認【かくにん】します。",furigana:"演奏を 確認します。",romaji:"ensou o kakunin shimasu.",idText:"Memeriksa pertunjukan musik, memainkan alat musik."}},{id:"vg-n3-01088",word:"追い付く",reading:"おいつく",romaji:"oitsuku",meaning:"menyusul, mengejar ketertinggalan",pos:"verb-u",nuance:"Merujuk pada tindakan mempercepat langkah atau usaha untuk menyamai posisi seseorang yang berada di depan, baik secara fisik maupun non-fisik (seperti prestasi atau pelajaran). Berbeda dengan 追いつめる (oitsumeru) yang berarti menyudutkan atau memojokkan lawan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"追い付く【おいつく】を 確認【かくにん】します。",furigana:"追い付くを 確認します。",romaji:"oitsuku o kakunin shimasu.",idText:"Memeriksa menyusul, mengejar ketertinggalan."}},{id:"vg-n3-01090",word:"追う",reading:"おう",romaji:"ou",meaning:"mengejar, memburu, mengikuti tren",pos:"verb-u",nuance:"Berarti mengejar atau membuntuti sesuatu yang bergerak di depan, baik sasaran fisik maupun hal abstrak seperti mimpi atau tren (流行を追う). Berbeda dengan 追いかける (oikakeru) yang lebih berfokus pada gerakan fisik langsung yang aktif memburu seketika.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"追う【おう】を 確認【かくにん】します。",furigana:"追うを 確認します。",romaji:"ou o kakunin shimasu.",idText:"Memeriksa mengejar, memburu, mengikuti tren."}},{id:"vg-n3-01091",word:"応援",reading:"おうえん",romaji:"ouen",meaning:"dukungan, sorakan semangat, bantuan",pos:"verb-suru",nuance:"Bisa berarti bersorak memberi semangat pada pertandingan olahraga maupun memberi dukungan moral atau bantuan tenaga kepada seseorang. Berbeda dengan 支持 (shiji) yang bernuansa dukungan politik atau persetujuan gagasan secara formal.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"応援【おうえん】を 確認【かくにん】します。",furigana:"応援を 確認します。",romaji:"ouen o kakunin shimasu.",idText:"Memeriksa dukungan, sorakan semangat, bantuan."}},{id:"vg-n3-01094",word:"応じる",reading:"おうじる",romaji:"oujiru",meaning:"menanggapi, memenuhi, menyesuaikan dengan",pos:"verb-ru",nuance:"Digunakan bersama partikel に dalam pola 〜に応じる, yang berarti merespons permintaan, ajakan, atau tawaran secara positif, atau menyesuaikan langkah dengan kondisi tertentu. Berbeda dengan 答える (kotaeru) yang sekadar menjawab pertanyaan lisan atau tes.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"応じる【おうじる】を 確認【かくにん】します。",furigana:"応じるを 確認します。",romaji:"oujiru o kakunin shimasu.",idText:"Memeriksa menanggapi, memenuhi, menyesuaikan dengan."}},{id:"vg-n3-01095",word:"横断",reading:"おうだん",romaji:"oudan",meaning:"menyeberang, melintasi (secara melintang)",pos:"verb-suru",nuance:"Menyeberang dari satu sisi ke sisi lain secara melintang, sering dipakai untuk jalan raya (横断歩道) atau perjalanan menjelajahi daratan dari barat ke timur. Berlawanan dengan 縦断 (juudan) yang berarti melintasi secara membujur dari utara ke selatan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"横断【おうだん】を 確認【かくにん】します。",furigana:"横断を 確認します。",romaji:"oudan o kakunin shimasu.",idText:"Memeriksa menyeberang, melintasi (secara melintang)."}}],explanations:[{id:"exp-1",grammarId:"gn3-00164",title:"Pola: 〜ればよかった",formula:"V-れば (ichidan / suru / kuru conditional) + よかった",meaning:"seandainya ..., kalau saja ... (penyesalan, fokus pada verba berakhiran れば)",nuanceNotes:"〜ればよかった adalah varian dari pola penyesalan 〜ばよかった yang muncul khususnya pada verba ichidan (食べれば, 見れば), verba suru (すれば), dan verba kuru (くれば). Maknanya identik — menyesal tidak melakukan sesuatu di masa lalu. Dalam bahasa lisan, 〜ればよかった sangat sering terdengar karena banyak verba sehari-hari termasuk kelompok ini.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ればよかった",idText:"seandainya ..., kalau saja ... (penyesalan, fokus pada verba berakhiran れば)"}],examples:[{jp:"もっとよく勉強すればよかった。",romaji:"",idText:"Seandainya aku belajar lebih giat dulu."},{jp:"早めに予約すればよかったな。",romaji:"",idText:"Kalau saja aku memesan lebih awal ya."},{jp:"彼女の話をちゃんと聞けばよかった。",romaji:"",idText:"Andai saja aku mendengarkan ceritanya dengan benar."}]},{id:"exp-2",grammarId:"gn3-00165",title:"Pola: 〜なければよかった",formula:"V-ない (stem) + なければよかった",meaning:"seandainya tidak ..., andai tidak ... (penyesalan sudah melakukan sesuatu)",nuanceNotes:'〜なければよかった menyatakan penyesalan atas sesuatu yang sudah dilakukan — pembicara berharap tidak melakukannya. Ini adalah kebalikan dari 〜ばよかった. Menggunakan bentuk negatif kondisional (〜なければ = kalau tidak), pola ini menyiratkan "seandainya saja aku tidak melakukan X, pasti lebih baik".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜なければよかった",idText:"seandainya tidak ..., andai tidak ... (penyesalan sudah melakukan sesuatu)"}],examples:[{jp:"あんなことを言わなければよかった。",romaji:"",idText:"Seandainya aku tidak mengucapkan hal seperti itu."},{jp:"お酒を飲まなければよかった。",romaji:"",idText:"Andai saja aku tidak minum alkohol tadi."},{jp:"余計なことに首を突っ込まなければよかった。",romaji:"",idText:"Seandainya aku tidak ikut campur dalam urusan yang tidak perlu itu."}]},{id:"exp-3",grammarId:"gn3-00166",title:"Pola: 〜とよかった",formula:"V-plain (past) + とよかった / V-dict + とよかった",meaning:"seandainya ..., kalau saja ... (penyesalan lampau, nuansa fatalistis)",nuanceNotes:"〜とよかった menyatakan penyesalan bahwa sesuatu tidak terjadi seperti yang diinginkan. Pola ini menggunakan partikel と (sebagai kutipan kondisi) diikuti よかった. Sedikit berbeda dari 〜ばよかった, pola ini sering muncul bersama verba berupa klausa penuh atau ungkapan seperti 〜すればよかった → 〜するとよかった dalam konteks informal.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜とよかった",idText:"seandainya ..., kalau saja ... (penyesalan lampau, nuansa fatalistis)"}],examples:[{jp:"もっと早く相談するとよかったのに。",romaji:"",idText:"Seandainya aku berkonsultasi lebih awal tadi."},{jp:"写真を撮るとよかったなあ。",romaji:"",idText:"Kalau saja tadi aku mengambil foto ya."},{jp:"地図を確認するとよかった。",romaji:"",idText:"Andai saja aku mengecek peta dulu."}]},{id:"exp-4",grammarId:"gn3-00059",title:"Pola: 〜（よ）うとする / 〜（よ）うとしない",formula:"Vよう + とする / としない",meaning:"berusaha / hendak melakukan ... / tidak mau ...",nuanceNotes:"〜ようとする: berusaha melakukan sesuatu atau hendak melakukan. 〜ようとしない: tidak mau / tidak berusaha sama sekali.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜（よ）うとする / 〜（よ）うとしない",idText:"berusaha / hendak melakukan ... / tidak mau ..."}],examples:[{jp:"電車に乗ろうとしたとき、財布がないことに気づいた。",romaji:"",idText:"Ketika hendak naik kereta, saya sadar dompet tidak ada."},{jp:"彼は謝ろうとしない。",romaji:"",idText:"Dia tidak mau meminta maaf."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "援助"?',sentencePrompt:'Makna kata "援助" (えんじょ) dalam situasi kerja ini adalah:',options:["bantuan, pertolongan, sokongan","pidato, orasi politik","pertunjukan musik, memainkan alat musik","menyusul, mengejar ketertinggalan"],correctAnswer:"bantuan, pertolongan, sokongan",explanation:'Makna yang tepat untuk "援助" adalah "bantuan, pertolongan, sokongan".',diagnosticFeedback:{"pidato, orasi politik":'Salah: Pilihan "pidato, orasi politik" adalah makna dari kata "演説" (えんぜつ), bukan arti kata "援助".',"pertunjukan musik, memainkan alat musik":'Salah: Pilihan "pertunjukan musik, memainkan alat musik" adalah makna dari kata "演奏" (えんそう), bukan arti kata "援助".',"menyusul, mengejar ketertinggalan":'Salah: Pilihan "menyusul, mengejar ketertinggalan" adalah makna dari kata "追い付く" (おいつく), bukan arti kata "援助".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"もっとよく勉強す（　　）。",options:["ればよかった","なければよかった","とよかった","つもりだった"],correctAnswer:"ればよかった",explanation:'Pola 〜ればよかった bermakna "seandainya ..., kalau saja ... (penyesalan, fokus pada verba berakhiran れば)". Kalimat lengkap: "もっとよく勉強すればよかった。".',diagnosticFeedback:{なければよかった:'Salah: Pola "なければよかった" bermakna "seandainya tidak ..., andai tidak ... (penyesalan sudah melakukan sesuatu)", yang tidak sesuai konteks kalimat ini.',とよかった:'Salah: Pola "とよかった" bermakna "seandainya ..., kalau saja ... (penyesalan lampau, nuansa fatalistis)", yang tidak sesuai konteks kalimat ini.',つもりだった:'Salah: Pola "つもりだった" bermakna "tadinya bermaksud ... / rencananya ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜ればよかった secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["早めに予約すればよかったな。","早めに予約すればよかったでしたな。","あんなことを言わなければよかった。","今こそ行動するときだ！"],correctAnswer:"早めに予約すればよかったな。",explanation:'Kalimat yang benar dan alami adalah "早めに予約すればよかったな。" (Kalau saja aku memesan lebih awal ya.).',diagnosticFeedback:{"早めに予約すればよかったでしたな。":"Jebakan Konjugasi: Pola 〜ればよかった membutuhkan aturan sambung (V-れば (ichidan / suru / kuru conditional) + よかった), bukan bentuk ini.","あんなことを言わなければよかった。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜なければよかった: seandainya tidak ..., andai tidak ... (penyesalan sudah melakukan sesuatu)), bukan kaidah 〜ればよかった.","今こそ行動するときだ！":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜ればよかった secara tepat (seandainya ..., kalau saja ... (penyesalan, fokus pada verba berakhiran れば))."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["あんな ことを 言わなければ よかった。","ことを あんな 言わなければ よかった。","あんな 言わなければ ことを よかった。","よかった。 あんな ことを 言わなければ"],correctAnswer:"あんな ことを 言わなければ よかった。",explanation:'Susunan yang benar: "あんな ことを 言わなければ よかった。" (Seandainya aku tidak mengucapkan hal seperti itu.).',diagnosticFeedback:{"ことを あんな 言わなければ よかった。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","あんな 言わなければ ことを よかった。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","よかった。 あんな ことを 言わなければ":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["あんな","ことを","言わなければ","よかった。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Briefing insiden keselamatan kerja setelah terjadi keterlambatan pengiriman logistik.", saat Tanaka menyampaikan arahan: 「なるほど。あんなことを言わなければよかった。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 〜ればよかった dan 〜なければよかった secara mandiri.",situation:"Situasi komunikasi profesional di Briefing insiden keselamatan kerja setelah terjadi keterlambatan pengiriman logistik.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜ればよかった!",modelAnswer:"はい、Tanakaさん！ もっとよく勉強すればよかった。。",modelAnswerId:"Ya, Tanaka! Seandainya aku belajar lebih giat dulu..",culturalEtiquette:"Dalam budaya kerja Jepang, pengakuan penyesalan introspektif (hansei) adalah langkah awal perbaikan Kaizen.",skillUnlocked:["Menguasai formulasi pola 〜ればよかった","Mampu menerapkan prinsip koordinasi komunikasi kerja Penyesalan Masa Lalu & Harapan Hipotetis"]},pocket_summary:{keyFormula:"〜ればよかった (seandainya ..., kalau saja ... (penyesalan, fokus pada verba berakhiran れば))",coreWords:["援助【えんじょ】 (bantuan, pertolongan, sokongan)","演説【えんぜつ】 (pidato, orasi politik)","演奏【えんそう】 (pertunjukan musik, memainkan alat musik)","追い付く【おいつく】 (menyusul, mengejar ketertinggalan)"],coreWarning:"Jangan menyalahkan rekan lain saat menyatakan penyesalan dalam forum resmi perusahaan.",quickDialogue:"A: ブディさん、援助の 状況【じょうきょう】は どうで... → B: はい、Tanakaさん！ もっとよく勉強すればよか..."}}},t={"les-n3-u05-01":{pedagogical_framework:{what:{summary:"Niat Terencana, Tekad Matang & Kebiasaan Disiplin (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜つもりだった, 〜ことにしている / 〜ことにした, 〜ことになっている / 〜ことになった, 〜に〜られた (pasif dengan objek yang menderita), 〜られている (pasif — keadaan berlanjut) dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜つもりだった dan 〜ことにしている / 〜ことにした dalam percakapan kerja wajar.",targetPatterns:["〜つもりだった (tadinya bermaksud ... / rencananya ...)","〜ことにしている / 〜ことにした (sudah membiasakan diri / memutuskan untuk ...)","〜ことになっている / 〜ことになった (sudah ditetapkan / sesuai aturan ...)","〜に〜られた (pasif dengan objek yang menderita) (dilakukan X kepada saya oleh ...)","〜られている (pasif — keadaan berlanjut) (sedang di- / diketahui bahwa ...)"],coreVocabSample:["キャンプ","きゅうけい","きゅうしゅう","きゅうじょ","きゅうそく","きょうぎ","きょうきゅう","きょうちょう"]},sensei_context:{sceneIntro:"Rapat awal tahun divisi engineering dalam menyusun Key Performance Indicators. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜つもりだった dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Niat Terencana, Tekad Matang & Kebiasaan Disiplin",etiquette:"Ungkapkan target dengan struktur tegas namun tetap terbuka terhadap arahan pimpinan tim.",taboos:"Hindari memakai 〜tsumori da di hadapan atasan jika konteksnya terdengar sok mengatur keputusan sepihak."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜つもりだった",moraNote:"Perhatikan mora panjang pada tsu-mo-ri dan ko-to-ni-shi-te-i-ru.",soundTip:"Ucapkan 〜つもりだった dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜つもりだった",caseScenario:"Menggunakan 〜つもりだった tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜つもりだった.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜つもりだった sesuai kaidah.",explanation:"Kaidah koneksi 〜つもりだった: Vる / Vない + つもりだった."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Rapat awal tahun divisi engineering dalam menyusun Key Performance Indicators.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Niat Terencana, Tekad Matang & Kebiasaan Disiplin (Fondasi & Pemahaman Pola)",setting:"Rapat awal tahun divisi engineering dalam menyusun Key Performance Indicators.",narrative:"Budi dan Kenji berkoordinasi mengenai alur operasional kerja menggunakan pola 〜つもりだった."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Senior Engineer",avatar:"👨‍💻",jp:"ブディさん、キャンプの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、キャンプの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, kyanpu no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai berkemah, kamping? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Kenjiさん！ 早く帰るつもりだったが、残業になった。。",furigana:"はい、Kenjiさん！ 早く帰るつもりだったが、残業になった。。",romaji:"Hai, Kenji-san! つもりだった de susumete imasu.",idText:"Ya, Kenji! Tadinya bermaksud pulang cepat, tapi harus lembur.."},{id:"d3",speaker:"Kenji",speakerRole:"Senior Engineer",avatar:"👨‍💻",jp:"なるほど。毎朝30分ウォーキングすることにしている。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。毎朝30分ウォーキングすることにしている。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Sudah membiasakan diri berjalan kaki 30 menit setiap pagi.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-01268",word:"キャンプ",reading:"キャンプ",romaji:"kyanpu",meaning:"berkemah, kamping",pos:"verb-suru",nuance:"Kegiatan berekreasi di alam terbuka dengan mendirikan tenda dan menginap bersama keluarga atau teman (seperti キャンプ場 - bumi perkemahan, キャンプファイヤー - api unggun perkemahan). Di Jepang juga sangat populer istilah ソロキャンプ (kamping sendirian).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"キャンプを 確認【かくにん】します。",furigana:"キャンプを 確認します。",romaji:"kyanpu o kakunin shimasu.",idText:"Memeriksa berkemah, kamping."}},{id:"vg-n3-01270",word:"休憩",reading:"きゅうけい",romaji:"kyuukei",meaning:"istirahat sejenak, jeda rehat",pos:"verb-suru",nuance:"Menghentikan aktivitas belajar, bekerja, atau berolahraga untuk waktu singkat guna menyegarkan diri sebelum dilanjutkan kembali (seperti 休憩時間 - waktu istirahat sejenak, 休憩室 - ruang rehat). Berbeda dengan 休息 (kyuusoku) yang merujuk pada istirahat lebih santai dan panjang untuk memulihkan stamina secara menyeluruh.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"休憩【きゅうけい】を 確認【かくにん】します。",furigana:"休憩を 確認します。",romaji:"kyuukei o kakunin shimasu.",idText:"Memeriksa istirahat sejenak, jeda rehat."}},{id:"vg-n3-01272",word:"吸収",reading:"きゅうしゅう",romaji:"kyuushuu",meaning:"penyerapan, menyerap (cairan/pengetahuan)",pos:"verb-suru",nuance:"Menyerap cairan, zat, atau energi ke bagian dalam (seperti スポンジが水を吸収する - spons menyerap air), atau secara kiasan menyerap informasi, ilmu, dan kebudayaan ke dalam pemahaman diri (知識を吸収する - menyerap ilmu).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"吸収【きゅうしゅう】を 確認【かくにん】します。",furigana:"吸収を 確認します。",romaji:"kyuushuu o kakunin shimasu.",idText:"Memeriksa penyerapan, menyerap (cairan/pengetahuan)."}},{id:"vg-n3-01273",word:"救助",reading:"きゅうじょ",romaji:"kyuujo",meaning:"penyelamatan, evakuasi, pertolongan korban",pos:"verb-suru",nuance:"Menyelamatkan atau mengevakuasi korban yang berada dalam bahaya maut, bencana alam, atau kecelakaan (seperti 救助隊 - tim SAR/penyelamat, 救助活動 - operasi penyelamatan). Berbeda dengan 助ける (tasukeru) yang bisa berupa pertolongan ringan sehari-hari, 救助 adalah istilah formal untuk keadaan darurat hidup-mati.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"救助【きゅうじょ】を 確認【かくにん】します。",furigana:"救助を 確認します。",romaji:"kyuujo o kakunin shimasu.",idText:"Memeriksa penyelamatan, evakuasi, pertolongan korban."}},{id:"vg-n3-01275",word:"休息",reading:"きゅうそく",romaji:"kyuusoku",meaning:"istirahat, rehat santai, pemulihan tenaga",pos:"verb-suru",nuance:"Mengambil waktu untuk beristirahat secara tenang guna menyegarkan kembali fisik dan pikiran setelah lelah bekerja atau beraktivitas berat (seperti 休息をとる - beristirahat santai, 休息の場 - tempat beristirahat). Berbeda dengan 休憩 (kyuukei) yang hanya jeda waktu singkat, 休息 menekankan relaksasi dan pemulihan stamina yang lebih mendalam.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"休息【きゅうそく】を 確認【かくにん】します。",furigana:"休息を 確認します。",romaji:"kyuusoku o kakunin shimasu.",idText:"Memeriksa istirahat, rehat santai, pemulihan tenaga."}},{id:"vg-n3-01278",word:"競技",reading:"きょうぎ",romaji:"kyougi",meaning:"pertandingan, perlombaan olahraga, cabang olahraga",pos:"verb-suru",nuance:"Adu keterampilan fisik atau ketangkasan dalam perlombaan yang memiliki peraturan resmi dan terstandar (seperti 競技場 - arena perlombaan/stadion, 陸上競技 - cabang atletik, 競技者 - atlet peserta). Berbeda dengan 試合 (shiai) yang berfokus pada laga spesifik antara dua pihak, 競技 mencakup cabang atau nomor perlombaan itu secara umum.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"競技【きょうぎ】を 確認【かくにん】します。",furigana:"競技を 確認します。",romaji:"kyougi o kakunin shimasu.",idText:"Memeriksa pertandingan, perlombaan olahraga, cabang olahraga."}},{id:"vg-n3-01280",word:"供給",reading:"きょうきゅう",romaji:"kyoukyuu",meaning:"pasokan, penyediaan, suplai",pos:"verb-suru",nuance:"Menyalurkan atau menyediakan komoditas, daya listrik, bahan bakar, atau air yang dibutuhkan oleh masyarakat atau pasar secara berkesinambungan (seperti 電力の供給 - pasokan listrik, 供給不足 - kekurangan pasokan). Merupakan pasangan konsep ekonomi dari kata 需要 (juyou - permintaan): 需要と供給 (permintaan dan penawaran/pasokan).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"供給【きょうきゅう】を 確認【かくにん】します。",furigana:"供給を 確認します。",romaji:"kyoukyuu o kakunin shimasu.",idText:"Memeriksa pasokan, penyediaan, suplai."}},{id:"vg-n3-01282",word:"強調",reading:"きょうちょう",romaji:"kyouchou",meaning:"penekanan, menggarisbawahi, penegasan",pos:"verb-suru",nuance:"Memberi sorotan kuat atau menegaskan kata atau poin penting dalam pembicaraan atau tulisan agar menarik perhatian pendengar (seperti 重要性を強調する - menekankan arti pentingnya). Berbeda dengan 主張 (shuchou) yang berfokus pada pendirian atau argumen pendapat pribadi, 強調 berfokus pada cara menonjolkan suatu poin.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"強調【きょうちょう】を 確認【かくにん】します。",furigana:"強調を 確認します。",romaji:"kyouchou o kakunin shimasu.",idText:"Memeriksa penekanan, menggarisbawahi, penegasan."}}],explanations:[{id:"exp-1",grammarId:"gn3-00077",title:"Pola: 〜つもりだった",formula:"Vる / Vない + つもりだった",meaning:"tadinya bermaksud ... / rencananya ...",nuanceNotes:"〜つもりだった menyatakan niat atau rencana di masa lalu yang akhirnya tidak terlaksana.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜つもりだった",idText:"tadinya bermaksud ... / rencananya ..."}],examples:[{jp:"早く帰るつもりだったが、残業になった。",romaji:"",idText:"Tadinya bermaksud pulang cepat, tapi harus lembur."},{jp:"怒らないつもりだったのに、つい怒ってしまった。",romaji:"",idText:"Rencananya tidak mau marah, tapi tanpa sengaja marah juga."}]},{id:"exp-2",grammarId:"gn3-00081",title:"Pola: 〜ことにしている / 〜ことにした",formula:"Vる / Vない + ことにしている / ことにした",meaning:"sudah membiasakan diri / memutuskan untuk ...",nuanceNotes:"〜ことにしている: kebiasaan yang sudah mapan atas keputusan sendiri. 〜ことにした: keputusan yang baru diambil.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ことにしている / 〜ことにした",idText:"sudah membiasakan diri / memutuskan untuk ..."}],examples:[{jp:"毎朝30分ウォーキングすることにしている。",romaji:"",idText:"Sudah membiasakan diri berjalan kaki 30 menit setiap pagi."},{jp:"タバコをやめることにした。",romaji:"",idText:"Memutuskan untuk berhenti merokok."}]},{id:"exp-3",grammarId:"gn3-00082",title:"Pola: 〜ことになっている / 〜ことになった",formula:"Vる / Vない + ことになっている / ことになった",meaning:"sudah ditetapkan / sesuai aturan ...",nuanceNotes:"〜ことになっている: ada aturan atau kesepakatan yang berlaku. 〜ことになった: keputusan yang datang dari luar diri sendiri.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ことになっている / 〜ことになった",idText:"sudah ditetapkan / sesuai aturan ..."}],examples:[{jp:"会議は毎週月曜日に行われることになっています。",romaji:"",idText:"Rapat ditetapkan diadakan setiap Senin."},{jp:"来月転勤することになった。",romaji:"",idText:"Diputuskan bahwa bulan depan saya pindah tugas."}]},{id:"exp-4",grammarId:"gn3-00084",title:"Pola: 〜に〜られた (pasif dengan objek yang menderita)",formula:"N (orang) + に + N(部位) + を + Vられた",meaning:"dilakukan X kepada saya oleh ...",nuanceNotes:"〜に〜られた mengungkapkan pasif penderitaan: subjek terkena dampak negatif dari tindakan orang lain terhadap bagian tubuh atau miliknya.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜に〜られた (pasif dengan objek yang menderita)",idText:"dilakukan X kepada saya oleh ..."}],examples:[{jp:"電車で財布を盗まれた。",romaji:"",idText:"Dompet saya dicuri di kereta."},{jp:"友だちに秘密を話されてしまった。",romaji:"",idText:"Rahasia saya dibocorkan oleh teman."}]},{id:"exp-5",grammarId:"gn3-00085",title:"Pola: 〜られている (pasif — keadaan berlanjut)",formula:"Vられて + いる",meaning:"sedang di- / diketahui bahwa ...",nuanceNotes:'〜られている digunakan untuk menyatakan keadaan yang merupakan hasil pasif (banyak digunakan dalam teks akademis/berita): "diketahui", "dipercaya", "digunakan".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜られている (pasif — keadaan berlanjut)",idText:"sedang di- / diketahui bahwa ..."}],examples:[{jp:"この薬は世界中で広く使われています。",romaji:"",idText:"Obat ini banyak digunakan di seluruh dunia."},{jp:"彼の絵は美術館に飾られています。",romaji:"",idText:"Lukisannya dipajang di museum."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "キャンプ"?',sentencePrompt:'Makna kata "キャンプ" (キャンプ) dalam situasi kerja ini adalah:',options:["berkemah, kamping","istirahat sejenak, jeda rehat","penyerapan, menyerap (cairan/pengetahuan)","penyelamatan, evakuasi, pertolongan korban"],correctAnswer:"berkemah, kamping",explanation:'Makna yang tepat untuk "キャンプ" adalah "berkemah, kamping".',diagnosticFeedback:{"istirahat sejenak, jeda rehat":'Salah: Pilihan "istirahat sejenak, jeda rehat" adalah makna dari kata "休憩" (きゅうけい), bukan arti kata "キャンプ".',"penyerapan, menyerap (cairan/pengetahuan)":'Salah: Pilihan "penyerapan, menyerap (cairan/pengetahuan)" adalah makna dari kata "吸収" (きゅうしゅう), bukan arti kata "キャンプ".',"penyelamatan, evakuasi, pertolongan korban":'Salah: Pilihan "penyelamatan, evakuasi, pertolongan korban" adalah makna dari kata "救助" (きゅうじょ), bukan arti kata "キャンプ".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"早く帰る（　　）が、残業になった。",options:["つもりだった","ことにしている / 〜ことにした","ことになっている / 〜ことになった","ようと思う"],correctAnswer:"つもりだった",explanation:'Pola 〜つもりだった bermakna "tadinya bermaksud ... / rencananya ...". Kalimat lengkap: "早く帰るつもりだったが、残業になった。".',diagnosticFeedback:{"ことにしている / 〜ことにした":'Salah: Pola "ことにしている / 〜ことにした" bermakna "sudah membiasakan diri / memutuskan untuk ...", yang tidak sesuai konteks kalimat ini.',"ことになっている / 〜ことになった":'Salah: Pola "ことになっている / 〜ことになった" bermakna "sudah ditetapkan / sesuai aturan ...", yang tidak sesuai konteks kalimat ini.',ようと思う:'Salah: Pola "ようと思う" bermakna "berniat untuk ..., berencana untuk ... (niat yang baru atau sedang dipertimbangkan)", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜つもりだった secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["怒らないつもりだったのに、つい怒ってしまった。","怒らないつもりだったでしたのに、つい怒ってしまった。","毎朝30分ウォーキングすることにしている。","この料理は子どもっぽい。"],correctAnswer:"怒らないつもりだったのに、つい怒ってしまった。",explanation:'Kalimat yang benar dan alami adalah "怒らないつもりだったのに、つい怒ってしまった。" (Rencananya tidak mau marah, tapi tanpa sengaja marah juga.).',diagnosticFeedback:{"怒らないつもりだったでしたのに、つい怒ってしまった。":"Jebakan Konjugasi: Pola 〜つもりだった membutuhkan aturan sambung (Vる / Vない + つもりだった), bukan bentuk ini.","毎朝30分ウォーキングすることにしている。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜ことにしている / 〜ことにした: sudah membiasakan diri / memutuskan untuk ...), bukan kaidah 〜つもりだった.","この料理は子どもっぽい。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜つもりだった secara tepat (tadinya bermaksud ... / rencananya ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["毎朝3 0分ウォ ーキング することにしている。","0分ウォ 毎朝3 ーキング することにしている。","毎朝3 ーキング 0分ウォ することにしている。","することにしている。 毎朝3 0分ウォ ーキング"],correctAnswer:"毎朝3 0分ウォ ーキング することにしている。",explanation:'Susunan yang benar: "毎朝3 0分ウォ ーキング することにしている。" (Sudah membiasakan diri berjalan kaki 30 menit setiap pagi.).',diagnosticFeedback:{"0分ウォ 毎朝3 ーキング することにしている。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","毎朝3 ーキング 0分ウォ することにしている。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","することにしている。 毎朝3 0分ウォ ーキング":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["毎朝3","0分ウォ","ーキング","することにしている。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Rapat awal tahun divisi engineering dalam menyusun Key Performance Indicators.", saat Kenji menyampaikan arahan: 「なるほど。毎朝30分ウォーキングすることにしている。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜つもりだった dan 〜ことにしている / 〜ことにした dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Rapat awal tahun divisi engineering dalam menyusun Key Performance Indicators.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜つもりだった!",modelAnswer:"はい、Kenjiさん！ 早く帰るつもりだったが、残業になった。。",modelAnswerId:"Ya, Kenji! Tadinya bermaksud pulang cepat, tapi harus lembur..",culturalEtiquette:"Ungkapkan target dengan struktur tegas namun tetap terbuka terhadap arahan pimpinan tim.",skillUnlocked:["Menguasai formulasi pola 〜つもりだった","Mampu menerapkan prinsip koordinasi komunikasi kerja Niat Terencana, Tekad Matang & Kebiasaan Disiplin"]},pocket_summary:{keyFormula:"〜つもりだった (tadinya bermaksud ... / rencananya ...)",coreWords:["キャンプ【キャンプ】 (berkemah, kamping)","休憩【きゅうけい】 (istirahat sejenak, jeda rehat)","吸収【きゅうしゅう】 (penyerapan, menyerap (cairan/pengetahuan))","救助【きゅうじょ】 (penyelamatan, evakuasi, pertolongan korban)"],coreWarning:"Hindari memakai 〜tsumori da di hadapan atasan jika konteksnya terdengar sok mengatur keputusan sepihak.",quickDialogue:"A: ブディさん、キャンプの 状況【じょうきょう】は ど... → B: はい、Kenjiさん！ 早く帰るつもりだったが、残..."}},"les-n3-u05-02":{pedagogical_framework:{what:{summary:"Niat Terencana, Tekad Matang & Kebiasaan Disiplin (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 〜ことにする, 〜ようにする, 〜ていくつもりだ, 〜てくるつもりだ dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 〜ことにする dan 〜ようにする secara mandiri.",targetPatterns:["〜ことにする (memutuskan untuk ..., sengaja melakukan ...)","〜ようにする (berusaha agar ..., mengupayakan ...)","〜ていくつもりだ (berencana akan terus ..., akan melanjutkan ...)","〜てくるつもりだ (berencana akan datang sambil ..., akan kembali setelah ...)"],coreVocabSample:["このむ","こぼす","こぼれる","ころす","こんざつ","こんやく","こんらん","さいばん"]},sensei_context:{sceneIntro:"Rapat awal tahun divisi engineering dalam menyusun Key Performance Indicators. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 〜ことにする dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Niat Terencana, Tekad Matang & Kebiasaan Disiplin",etiquette:"Ungkapkan target dengan struktur tegas namun tetap terbuka terhadap arahan pimpinan tim.",taboos:"Hindari memakai 〜tsumori da di hadapan atasan jika konteksnya terdengar sok mengatur keputusan sepihak."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜ことにする",moraNote:"Perhatikan mora panjang pada tsu-mo-ri dan ko-to-ni-shi-te-i-ru.",soundTip:"Ucapkan 〜ことにする dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜ことにする",caseScenario:"Menggunakan 〜ことにする tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜ことにする.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜ことにする sesuai kaidah.",explanation:"Kaidah koneksi 〜ことにする: V-plain (非過去) + ことにする."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Rapat awal tahun divisi engineering dalam menyusun Key Performance Indicators.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Niat Terencana, Tekad Matang & Kebiasaan Disiplin (Produksi Aktif & Aplikasi Nyata)",setting:"Rapat awal tahun divisi engineering dalam menyusun Key Performance Indicators.",narrative:"Budi dan Kenji berkoordinasi mengenai alur operasional kerja menggunakan pola 〜ことにする."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Senior Engineer",avatar:"👨‍💻",jp:"ブディさん、好むの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、好むの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, konomu no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai menyukai, menggemari, lebih memilih, menyenangi? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Kenjiさん！ 来年、日本語の試験を受けることにした。。",furigana:"はい、Kenjiさん！ 来年、日本語の試験を受けることにした。。",romaji:"Hai, Kenji-san! ことにする de susumete imasu.",idText:"Ya, Kenji! Saya memutuskan untuk ikut ujian bahasa Jepang tahun depan.."},{id:"d3",speaker:"Kenji",speakerRole:"Senior Engineer",avatar:"👨‍💻",jp:"なるほど。毎日、野菜を食べるようにしている。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。毎日、野菜を食べるようにしている。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Saya berusaha untuk makan sayuran setiap hari.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-01445",word:"好む",reading:"このむ",romaji:"konomu",meaning:"menyukai, menggemari, lebih memilih, menyenangi",pos:"verb-u",nuance:"Kata kerja transitif godan yang bermakna memiliki kecenderungan menyukai atau lebih memilih suatu hal secara mantap. Lebih bernuansa objektif dan formal dibanding kata sifat 好き (suki). Sering muncul dalam bentuk pasif/ungkapan tertulis: 好まれる (banyak digemari orang) atau 好ましくない (kurang berkenan / tidak diinginkan).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"好む【このむ】を 確認【かくにん】します。",furigana:"好むを 確認します。",romaji:"konomu o kakunin shimasu.",idText:"Memeriksa menyukai, menggemari, lebih memilih, menyenangi."}},{id:"vg-n3-01446",word:"こぼす",reading:"こぼす",romaji:"kobosu",meaning:"menumpahkan (cairan); mengeluhkan, menumpahkan isi hati",pos:"verb-u",nuance:"Kata kerja transitif godan (他動詞). Arti harfiahnya menjatuhkan atau menumpahkan cairan atau butiran dari wadahnya secara tidak sengaja (お茶をこぼす / menumpahkan teh). Arti kiasannya adalah mengeluarkan gerutuan atau unek-unek (愚痴をこぼす / menumpahkan keluhan). Pasangan intransitifnya adalah こぼれる (tumpah/tercecer).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"こぼすを 確認【かくにん】します。",furigana:"こぼすを 確認します。",romaji:"kobosu o kakunin shimasu.",idText:"Memeriksa menumpahkan (cairan); mengeluhkan, menumpahkan isi hati."}},{id:"vg-n3-01447",word:"こぼれる",reading:"こぼれる",romaji:"koboreru",meaning:"tumpah, meluap, tercecer keluar; terpancar (senyuman/air mata)",pos:"verb-ru",nuance:"Kata kerja intransitif ichidan (自動詞). Menggambarkan zat cair, cahaya, atau butiran yang melimpah keluar dari wadahnya tanpa disengaja (contoh: 涙がこぼれる / air mata berlinang tumpah, 笑みがこぼれる / senyuman mengembang secara spontan). Pasangan transitifnya adalah こぼす (menumpahkan).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"こぼれるを 確認【かくにん】します。",furigana:"こぼれるを 確認します。",romaji:"koboreru o kakunin shimasu.",idText:"Memeriksa tumpah, meluap, tercecer keluar; terpancar (senyuman/air mata)."}},{id:"vg-n3-01453",word:"殺す",reading:"ころす",romaji:"korosu",meaning:"membunuh; menahan, meredam (napas, tawa, suara, emosi)",pos:"verb-u",nuance:"Secara harfiah berarti merenggut nyawa makhluk hidup (人や虫を殺す). Namun dalam tataran N3 dan sastra naratif, sangat sering berpasangan dengan ungkapan indra untuk meredam sesuatu: 息を殺す (iki o korosu - menahan napas agar tidak bersuara sama sekali), 笑いを殺す (menahan tawa), 声を殺して泣く (menangis teredam).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"殺す【ころす】を 確認【かくにん】します。",furigana:"殺すを 確認します。",romaji:"korosu o kakunin shimasu.",idText:"Memeriksa membunuh; menahan, meredam (napas, tawa, suara, emosi)."}},{id:"vg-n3-01455",word:"混雑",reading:"こんざつ",romaji:"konzatsu",meaning:"kepadatan, kesesakan, berjejal-jejal, keramaian macet",pos:"verb-suru",nuance:"Situasi ketika banyak orang atau kendaraan berkumpul memenuhi suatu ruang sehingga gerak menjadi sempit dan padat (seperti: 混雑した電車 / kereta yang sesak, 道路の混雑 / kemacetan jalan). Berbeda dengan 混乱 (konran) yang menitikberatkan pada situasi kacau balau atau hilangnya ketertiban aturan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"混雑【こんざつ】を 確認【かくにん】します。",furigana:"混雑を 確認します。",romaji:"konzatsu o kakunin shimasu.",idText:"Memeriksa kepadatan, kesesakan, berjejal-jejal, keramaian macet."}},{id:"vg-n3-01458",word:"婚約",reading:"こんやく",romaji:"konyaku",meaning:"pertunangan, ikatan janji nikah",pos:"verb-suru",nuance:"Janji resmi antara pasangan pria dan wanita untuk melangkah ke jenjang ikatan pernikahan (婚約する / bertunangan). Sering muncul dalam frasa 婚約指輪 (cincin tunangan) dan 婚約者 (tunangan). Berbeda dengan 結婚 (kekkon) yang merupakan perkawinan resmi yang telah terdaftar.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"婚約【こんやく】を 確認【かくにん】します。",furigana:"婚約を 確認します。",romaji:"konyaku o kakunin shimasu.",idText:"Memeriksa pertunangan, ikatan janji nikah."}},{id:"vg-n3-01459",word:"混乱",reading:"こんらん",romaji:"konran",meaning:"kekacauan, kerancuan, kebingungan, huru-hara",pos:"verb-suru",nuance:"Kondisi tidak teratur dan ricuh pada situasi sosial atau sistem kerja (seperti server komputer mati mendadak, kepanikan gempa bumi), atau kondisi isi kepala seseorang yang kalut dan bingung akibat informasi bertubi-tubi (頭が混乱する). Berbeda dengan 混雑 (konzatsu) yang hanya berarti berjejal fisik orang/kendaraan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"混乱【こんらん】を 確認【かくにん】します。",furigana:"混乱を 確認します。",romaji:"konran o kakunin shimasu.",idText:"Memeriksa kekacauan, kerancuan, kebingungan, huru-hara."}},{id:"vg-n3-01467",word:"裁判",reading:"さいばん",romaji:"saiban",meaning:"pengadilan, persidangan, peradilan hukum",pos:"verb-suru",nuance:"Proses hukum formal di mana hakim mengadili perkara pidana atau sengketa perdata untuk menjatuhkan putusan keadilan (裁判を起こす / menggugat ke pengadilan, 裁判長 / ketua majelis hakim). Gedung atau lembaga peradilannya disebut 裁判所 (saibansho).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"裁判【さいばん】を 確認【かくにん】します。",furigana:"裁判を 確認します。",romaji:"saiban o kakunin shimasu.",idText:"Memeriksa pengadilan, persidangan, peradilan hukum."}}],explanations:[{id:"exp-1",grammarId:"gn3-00121",title:"Pola: 〜ことにする",formula:"V-plain (非過去) + ことにする",meaning:"memutuskan untuk ..., sengaja melakukan ...",nuanceNotes:"〜ことにする menyatakan keputusan yang dibuat oleh pembicara sendiri secara sadar dan sengaja. Digunakan ketika seseorang memilih untuk melakukan atau tidak melakukan sesuatu atas kehendak sendiri. Bentuk 〜ことにしている menunjukkan kebiasaan atau kebijakan pribadi yang sudah diputuskan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ことにする",idText:"memutuskan untuk ..., sengaja melakukan ..."}],examples:[{jp:"来年、日本語の試験を受けることにした。",romaji:"",idText:"Saya memutuskan untuk ikut ujian bahasa Jepang tahun depan."},{jp:"毎朝、早起きすることにしている。",romaji:"",idText:"Saya sudah membiasakan diri bangun pagi setiap hari."},{jp:"健康のために、お酒を飲まないことにした。",romaji:"",idText:"Saya memutuskan untuk tidak minum alkohol demi kesehatan."}]},{id:"exp-2",grammarId:"gn3-00124",title:"Pola: 〜ようにする",formula:"V-plain / V-ない + ようにする",meaning:"berusaha agar ..., mengupayakan ...",nuanceNotes:"〜ようにする menyatakan usaha atau upaya yang dilakukan secara sadar agar sesuatu terjadi atau tidak terjadi. Pola ini menunjukkan niat untuk mengubah kebiasaan atau mempertahankan suatu perilaku tertentu. Bentuk 〜ようにしている menekankan bahwa usaha tersebut sedang dilakukan secara terus-menerus.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ようにする",idText:"berusaha agar ..., mengupayakan ..."}],examples:[{jp:"毎日、野菜を食べるようにしている。",romaji:"",idText:"Saya berusaha untuk makan sayuran setiap hari."},{jp:"遅刻しないようにしてください。",romaji:"",idText:"Tolong berusaha untuk tidak terlambat."},{jp:"睡眠を十分に取るようにしています。",romaji:"",idText:"Saya berusaha untuk tidur dengan cukup."}]},{id:"exp-3",grammarId:"gn3-00127",title:"Pola: 〜ていくつもりだ",formula:"V-て + いくつもりだ",meaning:"berencana akan terus ..., akan melanjutkan ...",nuanceNotes:"〜ていくつもりだ menyatakan rencana atau niat untuk melanjutkan suatu tindakan ke depan, dari sekarang menuju masa depan. Gabungan dari bentuk て + いく (bergerak maju) + つもりだ (berniat), pola ini menekankan kesinambungan tindakan yang akan terus dilakukan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ていくつもりだ",idText:"berencana akan terus ..., akan melanjutkan ..."}],examples:[{jp:"これからも日本語を勉強していくつもりだ。",romaji:"",idText:"Saya berencana untuk terus belajar bahasa Jepang ke depannya."},{jp:"この仕事を続けていくつもりです。",romaji:"",idText:"Saya berniat untuk melanjutkan pekerjaan ini."},{jp:"環境のために、節電していくつもりだ。",romaji:"",idText:"Saya berencana untuk terus menghemat listrik demi lingkungan."}]},{id:"exp-4",grammarId:"gn3-00128",title:"Pola: 〜てくるつもりだ",formula:"V-て + くるつもりだ",meaning:"berencana akan datang sambil ..., akan kembali setelah ...",nuanceNotes:"〜てくるつもりだ menyatakan rencana untuk melakukan suatu tindakan lalu kembali ke titik asal, atau rencana untuk pergi melakukan sesuatu dan kemudian kembali. Gabungan て + くる menggambarkan gerakan yang mengandung unsur kembali ke pembicara atau ke lokasi referensi.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜てくるつもりだ",idText:"berencana akan datang sambil ..., akan kembali setelah ..."}],examples:[{jp:"コンビニで飲み物を買ってくるつもりだ。",romaji:"",idText:"Saya berencana pergi membeli minuman di konbini (lalu kembali)."},{jp:"図書館で調べてくるつもりです。",romaji:"",idText:"Saya berencana pergi mencari informasi di perpustakaan."},{jp:"少し外を歩いてくるつもりだ。",romaji:"",idText:"Saya berencana jalan-jalan sebentar di luar (lalu kembali)."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "好む"?',sentencePrompt:'Makna kata "好む" (このむ) dalam situasi kerja ini adalah:',options:["menyukai, menggemari, lebih memilih, menyenangi","menumpahkan (cairan); mengeluhkan, menumpahkan isi hati","tumpah, meluap, tercecer keluar; terpancar (senyuman/air mata)","membunuh; menahan, meredam (napas, tawa, suara, emosi)"],correctAnswer:"menyukai, menggemari, lebih memilih, menyenangi",explanation:'Makna yang tepat untuk "好む" adalah "menyukai, menggemari, lebih memilih, menyenangi".',diagnosticFeedback:{"menumpahkan (cairan); mengeluhkan, menumpahkan isi hati":'Salah: Pilihan "menumpahkan (cairan); mengeluhkan, menumpahkan isi hati" adalah makna dari kata "こぼす" (こぼす), bukan arti kata "好む".',"tumpah, meluap, tercecer keluar; terpancar (senyuman/air mata)":'Salah: Pilihan "tumpah, meluap, tercecer keluar; terpancar (senyuman/air mata)" adalah makna dari kata "こぼれる" (こぼれる), bukan arti kata "好む".',"membunuh; menahan, meredam (napas, tawa, suara, emosi)":'Salah: Pilihan "membunuh; menahan, meredam (napas, tawa, suara, emosi)" adalah makna dari kata "殺す" (ころす), bukan arti kata "好む".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"来年、日本語の試験を受ける（　　）。",options:["ことにした","ようにする","ていくつもりだ","ようと思う"],correctAnswer:"ことにした",explanation:'Pola 〜ことにする bermakna "memutuskan untuk ..., sengaja melakukan ...". Kalimat lengkap: "来年、日本語の試験を受けることにした。".',diagnosticFeedback:{ようにする:'Salah: Pola "ようにする" bermakna "berusaha agar ..., mengupayakan ...", yang tidak sesuai konteks kalimat ini.',ていくつもりだ:'Salah: Pola "ていくつもりだ" bermakna "berencana akan terus ..., akan melanjutkan ...", yang tidak sesuai konteks kalimat ini.',ようと思う:'Salah: Pola "ようと思う" bermakna "berniat untuk ..., berencana untuk ... (niat yang baru atau sedang dipertimbangkan)", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜ことにする secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["毎朝、早起きすることにしている。","毎朝、早起きすることにしている。でした","毎日、野菜を食べるようにしている。","この料理は子どもっぽい。"],correctAnswer:"毎朝、早起きすることにしている。",explanation:'Kalimat yang benar dan alami adalah "毎朝、早起きすることにしている。" (Saya sudah membiasakan diri bangun pagi setiap hari.).',diagnosticFeedback:{"毎朝、早起きすることにしている。でした":"Jebakan Konjugasi: Pola 〜ことにする membutuhkan aturan sambung (V-plain (非過去) + ことにする), bukan bentuk ini.","毎日、野菜を食べるようにしている。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜ようにする: berusaha agar ..., mengupayakan ...), bukan kaidah 〜ことにする.","この料理は子どもっぽい。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜ことにする secara tepat (memutuskan untuk ..., sengaja melakukan ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["毎日、 野菜を 食べるように している。","野菜を 毎日、 食べるように している。","毎日、 食べるように 野菜を している。","している。 毎日、 野菜を 食べるように"],correctAnswer:"毎日、 野菜を 食べるように している。",explanation:'Susunan yang benar: "毎日、 野菜を 食べるように している。" (Saya berusaha untuk makan sayuran setiap hari.).',diagnosticFeedback:{"野菜を 毎日、 食べるように している。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","毎日、 食べるように 野菜を している。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","している。 毎日、 野菜を 食べるように":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["毎日、","野菜を","食べるように","している。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Rapat awal tahun divisi engineering dalam menyusun Key Performance Indicators.", saat Kenji menyampaikan arahan: 「なるほど。毎日、野菜を食べるようにしている。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 〜ことにする dan 〜ようにする secara mandiri.",situation:"Situasi komunikasi profesional di Rapat awal tahun divisi engineering dalam menyusun Key Performance Indicators.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜ことにする!",modelAnswer:"はい、Kenjiさん！ 来年、日本語の試験を受けることにした。。",modelAnswerId:"Ya, Kenji! Saya memutuskan untuk ikut ujian bahasa Jepang tahun depan..",culturalEtiquette:"Ungkapkan target dengan struktur tegas namun tetap terbuka terhadap arahan pimpinan tim.",skillUnlocked:["Menguasai formulasi pola 〜ことにする","Mampu menerapkan prinsip koordinasi komunikasi kerja Niat Terencana, Tekad Matang & Kebiasaan Disiplin"]},pocket_summary:{keyFormula:"〜ことにする (memutuskan untuk ..., sengaja melakukan ...)",coreWords:["好む【このむ】 (menyukai, menggemari, lebih memilih, menyenangi)","こぼす【こぼす】 (menumpahkan (cairan); mengeluhkan, menumpahkan isi hati)","こぼれる【こぼれる】 (tumpah, meluap, tercecer keluar; terpancar (senyuman/air mata))","殺す【ころす】 (membunuh; menahan, meredam (napas, tawa, suara, emosi))"],coreWarning:"Hindari memakai 〜tsumori da di hadapan atasan jika konteksnya terdengar sok mengatur keputusan sepihak.",quickDialogue:"A: ブディさん、好むの 状況【じょうきょう】は どうで... → B: はい、Kenjiさん！ 来年、日本語の試験を受ける..."}}},r={"les-n3-u06-01":{pedagogical_framework:{what:{summary:"Kehendak Spontan, Upaya Maksimal & Aksi Mendekat (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜ようと思う, 〜ようとしている, 〜ようとする, 〜としたら / 〜とすれば, 〜ば〜ほど dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜ようと思う dan 〜ようとしている dalam percakapan kerja wajar.",targetPatterns:["〜ようと思う (berniat untuk ..., berencana untuk ... (niat yang baru atau sedang dipertimbangkan))","〜ようとしている (sedang berusaha untuk ..., sedang mencoba ..., hampir akan ...)","〜ようとする (berusaha untuk ..., mencoba untuk ... (upaya, belum tentu berhasil))","〜としたら / 〜とすれば (seandainya ... / jika misalnya ...)","〜ば〜ほど (semakin ... semakin ...)"],coreVocabSample:["わける","わる","アップ","あてる","いためる","いためる","いどう","うまる"]},sensei_context:{sceneIntro:"Area bengkel mesin perkakas saat mendiagnosis motor listrik yang mogok. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜ようと思う dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Kehendak Spontan, Upaya Maksimal & Aksi Mendekat",etiquette:"Saat rekan kerja tampak kesulitan, tawarkan bantuan dengan kalimat ajakan empatik sebelum mengambil alih.",taboos:"Jangan menghakimi sikap rekan dengan 〜you to shinai secara langsung di hadapan orang bersangkutan."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜ようと思う",moraNote:"Jaga kesinambungan vokal panjang ou pada ikoukei (shi-you, i-kou).",soundTip:"Ucapkan 〜ようと思う dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜ようと思う",caseScenario:"Menggunakan 〜ようと思う tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜ようと思う.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜ようと思う sesuai kaidah.",explanation:"Kaidah koneksi 〜ようと思う: V-volitional (よう / おう) + と思う."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Area bengkel mesin perkakas saat mendiagnosis motor listrik yang mogok.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Kehendak Spontan, Upaya Maksimal & Aksi Mendekat (Fondasi & Pemahaman Pola)",setting:"Area bengkel mesin perkakas saat mendiagnosis motor listrik yang mogok.",narrative:"Budi dan Kenji berkoordinasi mengenai alur operasional kerja menggunakan pola 〜ようと思う."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Senior Engineer",avatar:"👨‍💻",jp:"ブディさん、分けるの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、分けるの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, wakeru no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai membagi, memisahkan, memilah, mendistribusikan? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Kenjiさん！ 来年、日本に留学しようと思っている。。",furigana:"はい、Kenjiさん！ 来年、日本に留学しようと思っている。。",romaji:"Hai, Kenji-san! ようと思う de susumete imasu.",idText:"Ya, Kenji! Aku berniat untuk belajar di Jepang tahun depan.."},{id:"d3",speaker:"Kenji",speakerRole:"Senior Engineer",avatar:"👨‍💻",jp:"なるほど。彼女は泣くのをこらえようとしている。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。彼女は泣くのをこらえようとしている。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Dia sedang berusaha menahan tangisnya.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-01654",word:"分ける",reading:"わける",romaji:"wakeru",meaning:"membagi, memisahkan, memilah, mendistribusikan",pos:"verb-ru",nuance:"Kata kerja transitif (他動詞). Pasangannya adalah 分かれる (wakareru). Dipakai saat seseorang secara sadar membagi suatu benda menjadi beberapa bagian (misalnya kue atau uang), memilah barang ke dalam beberapa kategori (misalnya memilah jenis sampah), atau mendistribusikan porsi secara adil kepada orang lain.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"分ける【わける】を 確認【かくにん】します。",furigana:"分けるを 確認します。",romaji:"wakeru o kakunin shimasu.",idText:"Memeriksa membagi, memisahkan, memilah, mendistribusikan."}},{id:"vg-n3-01660",word:"割る",reading:"わる",romaji:"waru",meaning:"memecahkan, membagi angka, mengencerkan minuman",pos:"verb-u",nuance:"Kata kerja transitif (他動詞). Memiliki ragam penggunaan: memecahkan benda getas atau cangkang seperti kaca atau telur (卵を割る), membagi angka matematika (10を2で割る), atau mencampur minuman keras dengan air maupun soda agar lebih encer (お酒を水で割る). Berbeda dengan 壊す (kowasu) yang merusak fungsi benda secara umum, 割る menekankan terbelahnya fisik benda menjadi serpihan pecahan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"割る【わる】を 確認【かくにん】します。",furigana:"割るを 確認します。",romaji:"waru o kakunin shimasu.",idText:"Memeriksa memecahkan, membagi angka, mengencerkan minuman."}},{id:"vg-n3-01667",word:"アップ",reading:"アップ",romaji:"appu",meaning:"peningkatan, kenaikan mutu/gaji; bidikan jarak dekat",pos:"verb-suru",nuance:"Kata serapan dari bahasa Inggris 'up' yang lazim dipakai sebagai kata kerja suru untuk menyatakan lonjakan performa, kecakapan, atau penghasilan (misalnya 給料アップ / kenaikan upah, スキルアップ / peningkatan kemampuan). Dalam bidang kamera atau video juga berarti bidikan jarak dekat (close-up). Berbeda dengan 上昇 (joushou) yang bernada kaku, アップ sangat populer dan santai.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"アップを 確認【かくにん】します。",furigana:"アップを 確認します。",romaji:"appu o kakunin shimasu.",idText:"Memeriksa peningkatan, kenaikan mutu/gaji; bidikan jarak dekat."}},{id:"vg-n3-01668",word:"宛てる",reading:"あてる",romaji:"ateru",meaning:"mengalamatkan, mengarahkan surat kepada, menujukan",pos:"verb-ru",nuance:"Digunakan ketika mengarahkan surat kiriman, berkas pos, atau surel kepada pihak penerima tertentu. Pola umumnya adalah [penerima] に宛てて書く ([penerima] ni atete kaku - menulis yang dialamatkan kepada ...). Berbeda dengan 当てる (menempelkan atau menebak sasaran), 宛てる memakai kanji 宛 yang berfokus khusus pada penerima komunikasi tertulis.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"宛てる【あてる】を 確認【かくにん】します。",furigana:"宛てるを 確認します。",romaji:"ateru o kakunin shimasu.",idText:"Memeriksa mengalamatkan, mengarahkan surat kepada, menujukan."}},{id:"vg-n3-01675",word:"傷める",reading:"いためる",romaji:"itameru",meaning:"mencederai organ tubuh, melukai hati, merusak benda",pos:"verb-ru",nuance:"Kata kerja transitif (他動詞). Dipakai untuk merusak struktur fisik benda rapuh, mencederai otot atau sendi anggota badan (contoh: 腰を傷める / mencederai pinggang), atau menyakiti perasaan batin seseorang (contoh: 胸を傷める / merasa teriris pilu). Hati-hati jangan tertukar dengan 炒める (itameru) yang bermakna menumis bahan masakan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"傷める【いためる】を 確認【かくにん】します。",furigana:"傷めるを 確認します。",romaji:"itameru o kakunin shimasu.",idText:"Memeriksa mencederai organ tubuh, melukai hati, merusak benda."}},{id:"vg-n3-01676",word:"炒める",reading:"いためる",romaji:"itameru",meaning:"menumis, menggoreng singkat dengan sedikit minyak",pos:"verb-ru",nuance:"Kata kerja transitif kuliner yang bermakna memasak sayuran atau daging di atas wajan panas menggunakan sedikit minyak goreng sambil terus diaduk (contoh: 野菜炒め / tumis sayur campur). Berbeda dengan 揚げる (ageru) yang menggoreng terendam dalam banyak minyak, 炒める menitikberatkan pada teknik menumis cepat dengan api sedang hingga besar.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"炒める【いためる】を 確認【かくにん】します。",furigana:"炒めるを 確認します。",romaji:"itameru o kakunin shimasu.",idText:"Memeriksa menumis, menggoreng singkat dengan sedikit minyak."}},{id:"vg-n3-01678",word:"異動",reading:"いどう",romaji:"idou",meaning:"mutasi pegawai, rotasi jabatan, alih tugas staf",pos:"verb-suru",nuance:"Merujuk spesifik pada rotasi penugasan status jabatan, perpindahan divisi kerja, atau mutasi cabang kantor karyawan dalam struktur organisasi (contoh: 人事異動 / rotasi kepegawaian). Hati-hati jangan tertukar homofonnya dengan 移動 (idou - berpindah tempat fisik dari lokasi A ke B), karena 異動 memakai kanji 異 yang menyiratkan perubahan posisi status kepegawaian.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"異動【いどう】を 確認【かくにん】します。",furigana:"異動を 確認します。",romaji:"idou o kakunin shimasu.",idText:"Memeriksa mutasi pegawai, rotasi jabatan, alih tugas staf."}},{id:"vg-n3-01680",word:"埋まる",reading:"うまる",romaji:"umaru",meaning:"tertimbun, terkubur di bawah timbunan; terisi penuh",pos:"verb-u",nuance:"Kata kerja intransitif (自動詞). Pasangannya adalah 埋める (umeru - menimbun/mengisi). Dipakai ketika objek tertimbun timbunan tanah, sampah, atau salju lebat, maupun saat alokasi kursi, kuota, atau agenda jadwal terisi penuh tanpa celah lowong (contoh: 予定が埋まる / jadwal penuh terisi, 席が埋まる / deretan bangku terisi padat).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"埋まる【うまる】を 確認【かくにん】します。",furigana:"埋まるを 確認します。",romaji:"umaru o kakunin shimasu.",idText:"Memeriksa tertimbun, terkubur di bawah timbunan; terisi penuh."}}],explanations:[{id:"exp-1",grammarId:"gn3-00170",title:"Pola: 〜ようと思う",formula:"V-volitional (よう / おう) + と思う",meaning:"berniat untuk ..., berencana untuk ... (niat yang baru atau sedang dipertimbangkan)",nuanceNotes:'〜ようと思う menyatakan niat atau rencana yang baru saja terbentuk atau sedang dipikirkan oleh pembicara. Menggunakan bentuk volitional verba (よう untuk ichidan/suru/kuru, おう untuk godan) diikuti と思う. Pola ini menggambarkan keputusan atau rencana yang belum sepenuhnya pasti — masih dalam tahap "berniat".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ようと思う",idText:"berniat untuk ..., berencana untuk ... (niat yang baru atau sedang dipertimbangkan)"}],examples:[{jp:"来年、日本に留学しようと思っている。",romaji:"",idText:"Aku berniat untuk belajar di Jepang tahun depan."},{jp:"少しダイエットしようと思っているんだ。",romaji:"",idText:"Aku lagi berencana untuk sedikit diet nih."},{jp:"この仕事を辞めようと思っている。",romaji:"",idText:"Aku sedang memikirkan untuk berhenti dari pekerjaan ini."}]},{id:"exp-2",grammarId:"gn3-00171",title:"Pola: 〜ようとしている",formula:"V-volitional (よう / おう) + としている",meaning:"sedang berusaha untuk ..., sedang mencoba ..., hampir akan ...",nuanceNotes:"〜ようとしている menggambarkan keadaan di mana seseorang sedang dalam proses mencoba atau berusaha melakukan sesuatu, atau hampir akan melakukannya. Berbeda dari 〜ようとする yang menekankan upaya tunggal, 〜ようとしている menggambarkan kondisi yang sedang berlangsung (progressive state). Bisa juga dipakai untuk menggambarkan sesuatu yang sedang dalam ambang terjadi.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ようとしている",idText:"sedang berusaha untuk ..., sedang mencoba ..., hampir akan ..."}],examples:[{jp:"彼女は泣くのをこらえようとしている。",romaji:"",idText:"Dia sedang berusaha menahan tangisnya."},{jp:"会社を立て直そうとしているところだ。",romaji:"",idText:"Kami sedang dalam proses berupaya membenahi perusahaan."},{jp:"日が沈もうとしている。",romaji:"",idText:"Matahari hampir akan terbenam."}]},{id:"exp-3",grammarId:"gn3-00172",title:"Pola: 〜ようとする",formula:"V-volitional (よう / おう) + とする",meaning:"berusaha untuk ..., mencoba untuk ... (upaya, belum tentu berhasil)",nuanceNotes:"〜ようとする menyatakan upaya atau usaha untuk melakukan sesuatu, dengan penekanan bahwa hasilnya belum tentu berhasil. Sering mengandung nuansa bahwa ada hambatan, rintangan, atau ketidakpastian dalam tindakan tersebut. Berbeda dari 〜ようとしている yang menekankan proses berlangsung, 〜ようとする lebih menekankan satu momen upaya.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ようとする",idText:"berusaha untuk ..., mencoba untuk ... (upaya, belum tentu berhasil)"}],examples:[{jp:"逃げようとしたが、捕まえられた。",romaji:"",idText:"Dia berusaha melarikan diri, namun berhasil ditangkap."},{jp:"ドアを開けようとしたが、鍵がかかっていた。",romaji:"",idText:"Aku mencoba membuka pintu, tapi ternyata terkunci."},{jp:"何かを言おうとしたが、言葉が出なかった。",romaji:"",idText:"Aku berusaha mengatakan sesuatu, tapi kata-kata tidak keluar."}]},{id:"exp-4",grammarId:"gn3-00013",title:"Pola: 〜としたら / 〜とすれば",formula:"V/Adj plain / N + としたら / とすれば",meaning:"seandainya ... / jika misalnya ...",nuanceNotes:'〜としたら / 〜とすれば digunakan untuk kondisi hipotetis: "seandainya", "andai kata". Menyatakan kondisi yang masih dalam perkiraan atau belum terjadi.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜としたら / 〜とすれば",idText:"seandainya ... / jika misalnya ..."}],examples:[{jp:"宝くじが当たったとしたら、何をしますか。",romaji:"",idText:"Seandainya menang lotre, apa yang akan kamu lakukan?"},{jp:"彼が正直に言ったとすれば、信じます。",romaji:"",idText:"Seandainya dia berkata jujur, saya percaya."}]},{id:"exp-5",grammarId:"gn3-00014",title:"Pola: 〜ば〜ほど",formula:"Vば + Vる + ほど / Adj-ければ + Adj + ほど",meaning:"semakin ... semakin ...",nuanceNotes:"〜ば〜ほど menyatakan hubungan proporsional: semakin satu hal meningkat, semakin hal lain juga meningkat.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ば〜ほど",idText:"semakin ... semakin ..."}],examples:[{jp:"練習すればするほど、上手になります。",romaji:"",idText:"Semakin banyak berlatih, semakin mahir."},{jp:"考えれば考えるほど、わからなくなる。",romaji:"",idText:"Semakin dipikir, semakin tidak mengerti."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "分ける"?',sentencePrompt:'Makna kata "分ける" (わける) dalam situasi kerja ini adalah:',options:["membagi, memisahkan, memilah, mendistribusikan","memecahkan, membagi angka, mengencerkan minuman","peningkatan, kenaikan mutu/gaji; bidikan jarak dekat","mengalamatkan, mengarahkan surat kepada, menujukan"],correctAnswer:"membagi, memisahkan, memilah, mendistribusikan",explanation:'Makna yang tepat untuk "分ける" adalah "membagi, memisahkan, memilah, mendistribusikan".',diagnosticFeedback:{"memecahkan, membagi angka, mengencerkan minuman":'Salah: Pilihan "memecahkan, membagi angka, mengencerkan minuman" adalah makna dari kata "割る" (わる), bukan arti kata "分ける".',"peningkatan, kenaikan mutu/gaji; bidikan jarak dekat":'Salah: Pilihan "peningkatan, kenaikan mutu/gaji; bidikan jarak dekat" adalah makna dari kata "アップ" (アップ), bukan arti kata "分ける".',"mengalamatkan, mengarahkan surat kepada, menujukan":'Salah: Pilihan "mengalamatkan, mengarahkan surat kepada, menujukan" adalah makna dari kata "宛てる" (あてる), bukan arti kata "分ける".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"来年、日本に留学し（　　）。",options:["ようと思っている","ようとしている","ようとする","はずだ / 〜はずがない"],correctAnswer:"ようと思っている",explanation:'Pola 〜ようと思う bermakna "berniat untuk ..., berencana untuk ... (niat yang baru atau sedang dipertimbangkan)". Kalimat lengkap: "来年、日本に留学しようと思っている。".',diagnosticFeedback:{ようとしている:'Salah: Pola "ようとしている" bermakna "sedang berusaha untuk ..., sedang mencoba ..., hampir akan ...", yang tidak sesuai konteks kalimat ini.',ようとする:'Salah: Pola "ようとする" bermakna "berusaha untuk ..., mencoba untuk ... (upaya, belum tentu berhasil)", yang tidak sesuai konteks kalimat ini.',"はずだ / 〜はずがない":'Salah: Pola "はずだ / 〜はずがない" bermakna "seharusnya ... / tidak mungkin ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜ようと思う secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["少しダイエットしようと思っているんだ。","少しダイエットしようと思っているんだ。でした","彼女は泣くのをこらえようとしている。","この建物では、禁煙することになっている。"],correctAnswer:"少しダイエットしようと思っているんだ。",explanation:'Kalimat yang benar dan alami adalah "少しダイエットしようと思っているんだ。" (Aku lagi berencana untuk sedikit diet nih.).',diagnosticFeedback:{"少しダイエットしようと思っているんだ。でした":"Jebakan Konjugasi: Pola 〜ようと思う membutuhkan aturan sambung (V-volitional (よう / おう) + と思う), bukan bentuk ini.","彼女は泣くのをこらえようとしている。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜ようとしている: sedang berusaha untuk ..., sedang mencoba ..., hampir akan ...), bukan kaidah 〜ようと思う.","この建物では、禁煙することになっている。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜ようと思う secara tepat (berniat untuk ..., berencana untuk ... (niat yang baru atau sedang dipertimbangkan))."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["彼女は 泣くのを こらえようと している。","泣くのを 彼女は こらえようと している。","彼女は こらえようと 泣くのを している。","している。 彼女は 泣くのを こらえようと"],correctAnswer:"彼女は 泣くのを こらえようと している。",explanation:'Susunan yang benar: "彼女は 泣くのを こらえようと している。" (Dia sedang berusaha menahan tangisnya.).',diagnosticFeedback:{"泣くのを 彼女は こらえようと している。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","彼女は こらえようと 泣くのを している。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","している。 彼女は 泣くのを こらえようと":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["彼女は","泣くのを","こらえようと","している。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Area bengkel mesin perkakas saat mendiagnosis motor listrik yang mogok.", saat Kenji menyampaikan arahan: 「なるほど。彼女は泣くのをこらえようとしている。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜ようと思う dan 〜ようとしている dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Area bengkel mesin perkakas saat mendiagnosis motor listrik yang mogok.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜ようと思う!",modelAnswer:"はい、Kenjiさん！ 来年、日本に留学しようと思っている。。",modelAnswerId:"Ya, Kenji! Aku berniat untuk belajar di Jepang tahun depan..",culturalEtiquette:"Saat rekan kerja tampak kesulitan, tawarkan bantuan dengan kalimat ajakan empatik sebelum mengambil alih.",skillUnlocked:["Menguasai formulasi pola 〜ようと思う","Mampu menerapkan prinsip koordinasi komunikasi kerja Kehendak Spontan, Upaya Maksimal & Aksi Mendekat"]},pocket_summary:{keyFormula:"〜ようと思う (berniat untuk ..., berencana untuk ... (niat yang baru atau sedang dipertimbangkan))",coreWords:["分ける【わける】 (membagi, memisahkan, memilah, mendistribusikan)","割る【わる】 (memecahkan, membagi angka, mengencerkan minuman)","アップ【アップ】 (peningkatan, kenaikan mutu/gaji; bidikan jarak dekat)","宛てる【あてる】 (mengalamatkan, mengarahkan surat kepada, menujukan)"],coreWarning:"Jangan menghakimi sikap rekan dengan 〜you to shinai secara langsung di hadapan orang bersangkutan.",quickDialogue:"A: ブディさん、分けるの 状況【じょうきょう】は どう... → B: はい、Kenjiさん！ 来年、日本に留学しようと思..."}},"les-n3-u06-02":{pedagogical_framework:{what:{summary:"Kehendak Spontan, Upaya Maksimal & Aksi Mendekat (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola もし〜たなら / 〜たら, 〜ないことには, 〜なぜなら〜からだ, 〜てはじめて dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan もし〜たなら / 〜たら dan 〜ないことには secara mandiri.",targetPatterns:["もし〜たなら / 〜たら (seandainya / kalau saja (hipotetis kuat))","〜ないことには (kalau tidak ..., tanpa ... tidak mungkin ...)","〜なぜなら〜からだ (karena ... (penjelasan alasan))","〜てはじめて (baru setelah ... / justru ketika ... baru sadar)"],coreVocabSample:["ためる","たんじょう","ダンス","ちこく","ちゅうし","ちゅうしゃ","ちゅうもく","ちゅうもん"]},sensei_context:{sceneIntro:"Area bengkel mesin perkakas saat mendiagnosis motor listrik yang mogok. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola もし〜たなら / 〜たら dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Kehendak Spontan, Upaya Maksimal & Aksi Mendekat",etiquette:"Saat rekan kerja tampak kesulitan, tawarkan bantuan dengan kalimat ajakan empatik sebelum mengambil alih.",taboos:"Jangan menghakimi sikap rekan dengan 〜you to shinai secara langsung di hadapan orang bersangkutan."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: もし〜たなら / 〜たら",moraNote:"Jaga kesinambungan vokal panjang ou pada ikoukei (shi-you, i-kou).",soundTip:"Ucapkan もし〜たなら / 〜たら dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: もし〜たなら / 〜たら",caseScenario:"Menggunakan もし〜たなら / 〜たら tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola もし〜たなら / 〜たら.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum もし〜たなら / 〜たら sesuai kaidah.",explanation:"Kaidah koneksi もし〜たなら / 〜たら: もし + V/Adj + たなら / たら."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Area bengkel mesin perkakas saat mendiagnosis motor listrik yang mogok.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Kehendak Spontan, Upaya Maksimal & Aksi Mendekat (Produksi Aktif & Aplikasi Nyata)",setting:"Area bengkel mesin perkakas saat mendiagnosis motor listrik yang mogok.",narrative:"Budi dan Kenji berkoordinasi mengenai alur operasional kerja menggunakan pola もし〜たなら / 〜たら."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Senior Engineer",avatar:"👨‍💻",jp:"ブディさん、溜めるの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、溜めるの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, tameru no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai mengumpulkan, menimbun, menabung, membiarkan menumpuk? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Kenjiさん！ もし昨日来られていたなら、会えたのに。。",furigana:"はい、Kenjiさん！ もし昨日来られていたなら、会えたのに。。",romaji:"Hai, Kenji-san! もし〜たなら / 〜たら de susumete imasu.",idText:"Ya, Kenji! Seandainya kemarin bisa datang, pasti bisa bertemu.."},{id:"d3",speaker:"Kenji",speakerRole:"Senior Engineer",avatar:"👨‍💻",jp:"なるほど。実際に試してみないことには、わからない。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。実際に試してみないことには、わからない。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Kalau tidak mencoba langsung, tidak akan tahu hasilnya.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-01853",word:"溜める",reading:"ためる",romaji:"tameru",meaning:"mengumpulkan, menimbun, menabung, membiarkan menumpuk",pos:"verb-ru",nuance:"Kata kerja transitif (他動詞). Merupakan aksi aktif menyimpan/menampung sedikit demi sedikit (seperti menabung uang: お金を溜める, menampung air di bak: お風呂に水を溜める), atau membiarkan tugas terbengkalai hingga membukit (seperti menumpuk pekerjaan: 仕事を溜める). Pasangan intransitifnya adalah 溜まる (tamaru).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"溜める【ためる】を 確認【かくにん】します。",furigana:"溜めるを 確認します。",romaji:"tameru o kakunin shimasu.",idText:"Memeriksa mengumpulkan, menimbun, menabung, membiarkan menumpuk."}},{id:"vg-n3-01859",word:"誕生",reading:"たんじょう",romaji:"tanjou",meaning:"kelahiran, lahirnya (juga pembentukan hal/tokoh baru)",pos:"verb-suru",nuance:"Dapat berarti kelahiran anak/bayi ke dunia (paling lazim dalam frasa 誕生日 = hari ulang tahun atau 誕生する = lahir), maupun kemunculan/lahirnya sesuatu yang baru secara sosial (misalnya kabinet menteri baru, lahirnya juara baru, produk baru). Berbeda dengan 出産 (shussan) yang memandang proses persalinan dari sudut sang ibu melahirkan, 誕生 memandang wujud sang anak atau entitas yang lahir.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"誕生【たんじょう】を 確認【かくにん】します。",furigana:"誕生を 確認します。",romaji:"tanjou o kakunin shimasu.",idText:"Memeriksa kelahiran, lahirnya (juga pembentukan hal/tokoh baru)."}},{id:"vg-n3-01860",word:"ダンス",reading:"ダンス",romaji:"dansu",meaning:"tarian, dansa",pos:"verb-suru",nuance:"Kata serapan dari bahasa Inggris 'dance', mengacu pada seni gerak tari modern, tari barat, balet, dansa ballroom, atau gaya kontemporer/hip-hop (biasa dalam pola ダンスをする / ダンスを踊る). Berbeda dengan 踊り (odori) yang sering mengacu pada tarian rakyat tradisional Jepang seperti tari Bon Festival.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"ダンスを 確認【かくにん】します。",furigana:"ダンスを 確認します。",romaji:"dansu o kakunin shimasu.",idText:"Memeriksa tarian, dansa."}},{id:"vg-n3-01874",word:"遅刻",reading:"ちこく",romaji:"chikoku",meaning:"keterlambatan, datang terlambat",pos:"verb-suru",nuance:"Menyatakan tindakan atau status datang melewati batas waktu yang telah ditentukan (sekolah, kantor, rapat, janji temu), umum dalam frasa 遅刻する (datang terlambat) atau 遅刻届 (surat izin terlambat). Berbeda dengan 遅れる (okureru) yang bermakna umum untuk keterlambatan apa pun (termasuk jadwal kereta atau perkembangan), 遅刻 khusus mengacu pada keterlambatan orang hadir di tempat tujuan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"遅刻【ちこく】を 確認【かくにん】します。",furigana:"遅刻を 確認します。",romaji:"chikoku o kakunin shimasu.",idText:"Memeriksa keterlambatan, datang terlambat."}},{id:"vg-n3-01885",word:"中止",reading:"ちゅうし",romaji:"chuushi",meaning:"pembatalan, penghentian, penundaan hingga batal",pos:"verb-suru",nuance:"Menyatakan keputusan untuk tidak melanjutkan atau membatalkan suatu rencana acara, perjalanan, pertandingan, atau operasi yang sedianya akan diadakan (contoh: 雨天中止 = batal jika hujan; 試合を中止する = membatalkan pertandingan). Berbeda dengan 延期 (enki) yang berarti ditunda ke tanggal lain di kemudian hari, 中止 menandakan penghentian total/pembatalan acara untuk saat itu.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"中止【ちゅうし】を 確認【かくにん】します。",furigana:"中止を 確認します。",romaji:"chuushi o kakunin shimasu.",idText:"Memeriksa pembatalan, penghentian, penundaan hingga batal."}},{id:"vg-n3-01886",word:"駐車",reading:"ちゅうしゃ",romaji:"chuusha",meaning:"parkir, memarkir kendaraan",pos:"verb-suru",nuance:"Merujuk pada tindakan menghentikan dan menempatkan kendaraan (mobil, motor, dsb.) di suatu tempat untuk jangka waktu tertentu. Sering dipakai dalam bentuk gabungan seperti 駐車場 (tempat parkir) atau 駐車違反 (pelanggaran parkir liar). Berbeda dengan 停車 (teisha) yang berarti berhenti sejenak tanpa pengemudi meninggalkan kendaraan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"駐車【ちゅうしゃ】を 確認【かくにん】します。",furigana:"駐車を 確認します。",romaji:"chuusha o kakunin shimasu.",idText:"Memeriksa parkir, memarkir kendaraan."}},{id:"vg-n3-01889",word:"注目",reading:"ちゅうもく",romaji:"chuumoku",meaning:"perhatian, sorotan, memusatkan perhatian",pos:"verb-suru",nuance:"Bermakna mengarahkan mata dan minat secara seksama ke suatu hal yang menarik atau penting. Sering digunakan dalam frasa 注目を集める (menarik perhatian masyarakat/publik) atau 注目を浴びる (menjadi sorotan). Berbeda dengan 注意 (chuui) yang lebih bermakna berhati-hati atau mewaspadai bahaya/kesalahan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"注目【ちゅうもく】を 確認【かくにん】します。",furigana:"注目を 確認します。",romaji:"chuumoku o kakunin shimasu.",idText:"Memeriksa perhatian, sorotan, memusatkan perhatian."}},{id:"vg-n3-01890",word:"注文",reading:"ちゅうもん",romaji:"chuumon",meaning:"pesanan, permintaan, memesan",pos:"verb-suru",nuance:"Bisa berarti memesan makanan/minuman di restoran, memesan barang di toko, atau mengajukan syarat/permintaan khusus terhadap seseorang atau penyedia layanan (misal: 注文をつける = menuntut/banyak minta syarat). Berbeda dengan 頼み (tanomi) yang bersifat meminta tolong secara personal.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"注文【ちゅうもん】を 確認【かくにん】します。",furigana:"注文を 確認します。",romaji:"chuumon o kakunin shimasu.",idText:"Memeriksa pesanan, permintaan, memesan."}}],explanations:[{id:"exp-1",grammarId:"gn3-00017",title:"Pola: もし〜たなら / 〜たら",formula:"もし + V/Adj + たなら / たら",meaning:"seandainya / kalau saja (hipotetis kuat)",nuanceNotes:"もし〜たなら memperkuat nuansa hipotetis atau tidak nyata dari kondisi.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"もし〜たなら / 〜たら",idText:"seandainya / kalau saja (hipotetis kuat)"}],examples:[{jp:"もし昨日来られていたなら、会えたのに。",romaji:"",idText:"Seandainya kemarin bisa datang, pasti bisa bertemu."},{jp:"もし一人で住んでいたら、何を作りますか。",romaji:"",idText:"Kalau tinggal sendiri, apa yang akan kamu masak?"}]},{id:"exp-2",grammarId:"gn3-00139",title:"Pola: 〜ないことには",formula:"V-ない + ことには / N + でないことには",meaning:"kalau tidak ..., tanpa ... tidak mungkin ...",nuanceNotes:'〜ないことには menyatakan kondisi yang harus dipenuhi terlebih dahulu agar sesuatu yang lain bisa terjadi. Klausa setelah ことには biasanya berisi ungkapan negatif seperti 〜ない、〜できない、〜わからない. Artinya: "tanpa melakukan X, Y tidak mungkin terjadi".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ないことには",idText:"kalau tidak ..., tanpa ... tidak mungkin ..."}],examples:[{jp:"実際に試してみないことには、わからない。",romaji:"",idText:"Kalau tidak mencoba langsung, tidak akan tahu hasilnya."},{jp:"本人に会わないことには、判断できない。",romaji:"",idText:"Tanpa bertemu orangnya langsung, tidak bisa membuat keputusan."},{jp:"努力しないことには、夢は叶わない。",romaji:"",idText:"Tanpa usaha, impian tidak akan terwujud."}]},{id:"exp-3",grammarId:"gn3-00005",title:"Pola: 〜なぜなら〜からだ",formula:"文1。なぜなら、文2 + からだ。",meaning:"karena ... (penjelasan alasan)",nuanceNotes:"〜なぜなら〜からだ digunakan untuk menjelaskan alasan dari kalimat sebelumnya. Pola formal untuk memaparkan alasan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜なぜなら〜からだ",idText:"karena ... (penjelasan alasan)"}],examples:[{jp:"私はお酒を飲まない。なぜなら、アレルギーがあるからだ。",romaji:"",idText:"Saya tidak minum alkohol. Karena saya punya alergi."},{jp:"この仕事は難しい。なぜなら、専門知識が必要だから。",romaji:"",idText:"Pekerjaan ini sulit. Karena membutuhkan pengetahuan khusus."}]},{id:"exp-4",grammarId:"gn3-00011",title:"Pola: 〜てはじめて",formula:"Vて + はじめて",meaning:"baru setelah ... / justru ketika ... baru sadar",nuanceNotes:'〜てはじめて menyatakan bahwa suatu pemahaman, pengalaman, atau kemampuan baru terwujud setelah suatu tindakan tertentu. "Baru setelah X, Y baru terjadi".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜てはじめて",idText:"baru setelah ... / justru ketika ... baru sadar"}],examples:[{jp:"日本に来てはじめて、日本語の難しさが分かった。",romaji:"",idText:"Baru setelah datang ke Jepang, saya menyadari sulitnya bahasa Jepang."},{jp:"失ってはじめて、その大切さに気づく。",romaji:"",idText:"Baru setelah kehilangan, kita menyadari betapa berharganya itu."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "溜める"?',sentencePrompt:'Makna kata "溜める" (ためる) dalam situasi kerja ini adalah:',options:["mengumpulkan, menimbun, menabung, membiarkan menumpuk","kelahiran, lahirnya (juga pembentukan hal/tokoh baru)","tarian, dansa","keterlambatan, datang terlambat"],correctAnswer:"mengumpulkan, menimbun, menabung, membiarkan menumpuk",explanation:'Makna yang tepat untuk "溜める" adalah "mengumpulkan, menimbun, menabung, membiarkan menumpuk".',diagnosticFeedback:{"kelahiran, lahirnya (juga pembentukan hal/tokoh baru)":'Salah: Pilihan "kelahiran, lahirnya (juga pembentukan hal/tokoh baru)" adalah makna dari kata "誕生" (たんじょう), bukan arti kata "溜める".',"tarian, dansa":'Salah: Pilihan "tarian, dansa" adalah makna dari kata "ダンス" (ダンス), bukan arti kata "溜める".',"keterlambatan, datang terlambat":'Salah: Pilihan "keterlambatan, datang terlambat" adalah makna dari kata "遅刻" (ちこく), bukan arti kata "溜める".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"（　　）昨日来られていた（　　）、会えたのに。",options:["もし","ないことには","なぜなら〜からだ","はずだ / 〜はずがない"],correctAnswer:"もし",explanation:'Pola もし〜たなら / 〜たら bermakna "seandainya / kalau saja (hipotetis kuat)". Kalimat lengkap: "もし昨日来られていたなら、会えたのに。".',diagnosticFeedback:{ないことには:'Salah: Pola "ないことには" bermakna "kalau tidak ..., tanpa ... tidak mungkin ...", yang tidak sesuai konteks kalimat ini.',"なぜなら〜からだ":'Salah: Pola "なぜなら〜からだ" bermakna "karena ... (penjelasan alasan)", yang tidak sesuai konteks kalimat ini.',"はずだ / 〜はずがない":'Salah: Pola "はずだ / 〜はずがない" bermakna "seharusnya ... / tidak mungkin ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola もし〜たなら / 〜たら secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["もし一人で住んでいたら、何を作りますか。","もし一人で住んでいたら、何を作りますか。でした","実際に試してみないことには、わからない。","この建物では、禁煙することになっている。"],correctAnswer:"もし一人で住んでいたら、何を作りますか。",explanation:'Kalimat yang benar dan alami adalah "もし一人で住んでいたら、何を作りますか。" (Kalau tinggal sendiri, apa yang akan kamu masak?).',diagnosticFeedback:{"もし一人で住んでいたら、何を作りますか。でした":"Jebakan Konjugasi: Pola もし〜たなら / 〜たら membutuhkan aturan sambung (もし + V/Adj + たなら / たら), bukan bentuk ini.","実際に試してみないことには、わからない。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜ないことには: kalau tidak ..., tanpa ... tidak mungkin ...), bukan kaidah もし〜たなら / 〜たら.","この建物では、禁煙することになっている。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola もし〜たなら / 〜たら secara tepat (seandainya / kalau saja (hipotetis kuat))."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["実際に 試してみない ことには、 わからない。","試してみない 実際に ことには、 わからない。","実際に ことには、 試してみない わからない。","わからない。 実際に 試してみない ことには、"],correctAnswer:"実際に 試してみない ことには、 わからない。",explanation:'Susunan yang benar: "実際に 試してみない ことには、 わからない。" (Kalau tidak mencoba langsung, tidak akan tahu hasilnya.).',diagnosticFeedback:{"試してみない 実際に ことには、 わからない。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","実際に ことには、 試してみない わからない。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","わからない。 実際に 試してみない ことには、":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["実際に","試してみない","ことには、","わからない。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Area bengkel mesin perkakas saat mendiagnosis motor listrik yang mogok.", saat Kenji menyampaikan arahan: 「なるほど。実際に試してみないことには、わからない。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan もし〜たなら / 〜たら dan 〜ないことには secara mandiri.",situation:"Situasi komunikasi profesional di Area bengkel mesin perkakas saat mendiagnosis motor listrik yang mogok.",promptTask:"Sampaikan laporan koordinasi menggunakan pola もし〜たなら / 〜たら!",modelAnswer:"はい、Kenjiさん！ もし昨日来られていたなら、会えたのに。。",modelAnswerId:"Ya, Kenji! Seandainya kemarin bisa datang, pasti bisa bertemu..",culturalEtiquette:"Saat rekan kerja tampak kesulitan, tawarkan bantuan dengan kalimat ajakan empatik sebelum mengambil alih.",skillUnlocked:["Menguasai formulasi pola もし〜たなら / 〜たら","Mampu menerapkan prinsip koordinasi komunikasi kerja Kehendak Spontan, Upaya Maksimal & Aksi Mendekat"]},pocket_summary:{keyFormula:"もし〜たなら / 〜たら (seandainya / kalau saja (hipotetis kuat))",coreWords:["溜める【ためる】 (mengumpulkan, menimbun, menabung, membiarkan menumpuk)","誕生【たんじょう】 (kelahiran, lahirnya (juga pembentukan hal/tokoh baru))","ダンス【ダンス】 (tarian, dansa)","遅刻【ちこく】 (keterlambatan, datang terlambat)"],coreWarning:"Jangan menghakimi sikap rekan dengan 〜you to shinai secara langsung di hadapan orang bersangkutan.",quickDialogue:"A: ブディさん、溜めるの 状況【じょうきょう】は どう... → B: はい、Kenjiさん！ もし昨日来られていたなら、..."}}},k={"les-n3-u07-01":{pedagogical_framework:{what:{summary:"Pengandaian Kondisional & Rangkaian Sebab Akibat (Fondasi & Pemahaman Pola). Menguasai penggunaan pola 〜はずだ / 〜はずがない, 〜わけだ, 〜わけにはいかない, 〜ということだ, 〜によれば / 〜によると dan penerapannya dalam situasi nyata.",canDo:"Mampu memahami dan menerapkan pola 〜はずだ / 〜はずがない dan 〜わけだ dalam percakapan kerja wajar.",targetPatterns:["〜はずだ / 〜はずがない (seharusnya ... / tidak mungkin ...)","〜わけだ (jadi ... / pantas saja ... / memang wajar)","〜わけにはいかない (tidak bisa ... / tidak boleh ...)","〜ということだ (artinya ... / kesimpulannya ...)","〜によれば / 〜によると (menurut ... / berdasarkan ...)"],coreVocabSample:["ねがう","ねっちゅう","のこす","のせる","のせる","のぞく","のぞく","のぞむ"]},sensei_context:{sceneIntro:"Simulasi tanggap darurat bencana alam dan pemadaman daya listrik darurat di gedung pabrik. Tahap fondasi berfokus pada penguasaan bentuk konjugasi dan nuansa dasar.",dailyMission:"Terapkan pola 〜はずだ / 〜はずがない dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Pengandaian Kondisional & Rangkaian Sebab Akibat",etiquette:"Sampaikan mitigasi risiko secara terstruktur menggunakan data dan urutan langkah yang jelas.",taboos:"Jangan menyepelekan klausul prasyarat mutlak (nai koto ni wa) pada instruksi keselamatan bertegangan tinggi."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜はずだ / 〜はずがない",moraNote:"Beri penekanan jeda tipis setelah partikel ba atau to shitara untuk menandai anak kalimat syarat.",soundTip:"Ucapkan 〜はずだ / 〜はずがない dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜はずだ / 〜はずがない",caseScenario:"Menggunakan 〜はずだ / 〜はずがない tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜はずだ / 〜はずがない.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜はずだ / 〜はずがない sesuai kaidah.",explanation:"Kaidah koneksi 〜はずだ / 〜はずがない: V/Adj plain / N + の + はずだ / はずがない."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Simulasi tanggap darurat bencana alam dan pemadaman daya listrik darurat di gedung pabrik.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Pengandaian Kondisional & Rangkaian Sebab Akibat (Fondasi & Pemahaman Pola)",setting:"Simulasi tanggap darurat bencana alam dan pemadaman daya listrik darurat di gedung pabrik.",narrative:"Budi dan Kenji berkoordinasi mengenai alur operasional kerja menggunakan pola 〜はずだ / 〜はずがない."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Senior Engineer",avatar:"👨‍💻",jp:"ブディさん、願うの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、願うの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, negau no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai memohon, mengharapkan, berdoa mendambakan, meminta? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Kenjiさん！ 今ごろ着いているはずです。。",furigana:"はい、Kenjiさん！ 今ごろ着いているはずです。。",romaji:"Hai, Kenji-san! はずだ / 〜はずがない de susumete imasu.",idText:"Ya, Kenji! Seharusnya sekarang sudah sampai.."},{id:"d3",speaker:"Kenji",speakerRole:"Senior Engineer",avatar:"👨‍💻",jp:"なるほど。10年も日本に住んでいるんだから、日本語が上手なわけだ。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。10年も日本に住んでいるんだから、日本語が上手なわけだ。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Sudah tinggal 10 tahun di Jepang, jadi wajar saja bahasa Jepangnya bagus.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-02061",word:"願う",reading:"ねがう",romaji:"negau",meaning:"memohon, mengharapkan, berdoa mendambakan, meminta",pos:"verb-u",nuance:"Verba transitif yang dipakai untuk mengharapkan terwujudnya kebaikan hidup atau memohon pertolongan orang lain dengan penuh kerendahan hati. Berbeda dengan 祈る (inoru) yang lebih bernuansa doa peribadatan spiritual kepada Yang Mahakuasa, 願う sering dipakai dalam interaksi sosial kemanusiaan untuk meminta kesediaan rekan (seperti お願いする).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"願う【ねがう】を 確認【かくにん】します。",furigana:"願うを 確認します。",romaji:"negau o kakunin shimasu.",idText:"Memeriksa memohon, mengharapkan, berdoa mendambakan, meminta."}},{id:"vg-n3-02064",word:"熱中",reading:"ねっちゅう",romaji:"necchuu",meaning:"asyik tenggelam dalam, terobsesi fokus, keranjingan",pos:"verb-suru",nuance:"Kondisi mencurahkan segenap atensi dan energi batin pada hobi atau kesibukan tertentu hingga mengabaikan sekelilingnya (pola: [Hal] に熱中する). Berbeda dengan 夢中 (muchuu) yang berkonotasi tersihir terlena secara impulsif, 熱中 lebih menitikberatkan pada konsentrasi tekun yang membakar semangat. Ingat pula gangguan sengatan panas 熱中症 (necchuushou).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"熱中【ねっちゅう】を 確認【かくにん】します。",furigana:"熱中を 確認します。",romaji:"necchuu o kakunin shimasu.",idText:"Memeriksa asyik tenggelam dalam, terobsesi fokus, keranjingan."}},{id:"vg-n3-02077",word:"残す",reading:"のこす",romaji:"nokosu",meaning:"menyisakan, meninggalkan, mencatatkan warisan",pos:"verb-u",nuance:"Verba transitif (他動詞) yang berarti membiarkan sebagian benda/kuantitas tersisa tanpa dihabiskan (makanan: ご飯を残す), meninggalkan pesan memo (伝言を残す), atau menorehkan warisan karya di kemudian hari (名を残す). Pasangan intransitifnya adalah 残る (nokoru, tersisa). Berbeda dengan 捨てる (suteru, membuang) atau 忘れる (wasureru, melupakan).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"残す【のこす】を 確認【かくにん】します。",furigana:"残すを 確認します。",romaji:"nokosu o kakunin shimasu.",idText:"Memeriksa menyisakan, meninggalkan, mencatatkan warisan."}},{id:"vg-n3-02079",word:"乗せる",reading:"のせる",romaji:"noseru",meaning:"menaikkan penumpang, memboncengkan, mengangkut tumpangan",pos:"verb-ru",nuance:"Dipakai khusus untuk menaikkan penumpang bernyawa (orang atau hewan piaraan) ke atas sarana mobilitas transportasi seperti mobil, bus, perahu, atau sepeda (contoh: 友人を車に乗せる / memberi tumpangan mobil kepada sahabat). Berbeda dengan kanji homofon 載せる yang dikhususkan bagi barang kargo benda mati atau memuat terbitan data di media cetak.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"乗せる【のせる】を 確認【かくにん】します。",furigana:"乗せるを 確認します。",romaji:"noseru o kakunin shimasu.",idText:"Memeriksa menaikkan penumpang, memboncengkan, mengangkut tumpangan."}},{id:"vg-n3-02080",word:"載せる",reading:"のせる",romaji:"noseru",meaning:"memuat, menaruh di atas, menerbitkan mempublikasikan",pos:"verb-ru",nuance:"Dipakai untuk: (1) meletakkan muatan barang mati ke atas rak, meja, atau bak truk kargo (荷物を棚に載せる), serta (2) menerbitkan atau mengunggah artikel warta, gambar foto, atau iklan ke surat kabar, majalah, atau situs web internet (記事を新聞に載せる). Berbeda dengan kanji homofon 乗せる yang khusus diperuntukkan bagi manusia atau makhluk hidup penunggang.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"載せる【のせる】を 確認【かくにん】します。",furigana:"載せるを 確認します。",romaji:"noseru o kakunin shimasu.",idText:"Memeriksa memuat, menaruh di atas, menerbitkan mempublikasikan."}},{id:"vg-n3-02081",word:"覗く",reading:"のぞく",romaji:"nozoku",meaning:"mengintip, melongok, menjenguk sekilas",pos:"verb-u",nuance:"Menunjukkan perbuatan melihat dari sela sempit, mengintip melalui lubang kunci, atau melongokkan kepala dari ketinggian (contoh: 隙間から覗く / mengintip dari celah). Dapat pula berkonotasi mampir menjenguk toko atau acara sekilas sambil lalu (店を覗く). Berbeda dengan 除く yang berarti menyingkirkan atau mengecualikan meski memiliki lafal sama persis.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"覗く【のぞく】を 確認【かくにん】します。",furigana:"覗くを 確認します。",romaji:"nozoku o kakunin shimasu.",idText:"Memeriksa mengintip, melongok, menjenguk sekilas."}},{id:"vg-n3-02082",word:"除く",reading:"のぞく",romaji:"nozoku",meaning:"mengecualikan, menyingkirkan, menghilangkan kotoran",pos:"verb-u",nuance:"Verba transitif (他動詞) yang berarti memisahkan atau mengecualikan elemen tertentu dari suatu himpunan (seperti pola tata bahasa 〜を除いて / kecuali / di luar dari), serta menyingkirkan hambatan, kecemasan, atau kotoran (不安を除く). Berbeda dengan kanji homofon 覗く (nozoku, mengintip), 除く berfokus pada eliminasi pengecualian logis.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"除く【のぞく】を 確認【かくにん】します。",furigana:"除くを 確認します。",romaji:"nozoku o kakunin shimasu.",idText:"Memeriksa mengecualikan, menyingkirkan, menghilangkan kotoran."}},{id:"vg-n3-02084",word:"望む",reading:"のぞむ",romaji:"nozomu",meaning:"menginginkan, mengharapkan, mendambakan, menghadap pemandangan",pos:"verb-u",nuance:"Verba transitif yang memiliki dua ranah makna: (1) mendambakan perwujudan hal ideal bagi masa depan (contoh: 平和を望む / mendambakan kedamaian), dan (2) memandang ke arah pemandangan alam luas dari ketinggian (seperti 海を望む丘 / bukit menghadap laut). Berbeda dengan kanji homofon 臨む (nozomu) yang bermakna menghadiri pertemuan genting atau menghadapi cobaan.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"望む【のぞむ】を 確認【かくにん】します。",furigana:"望むを 確認します。",romaji:"nozomu o kakunin shimasu.",idText:"Memeriksa menginginkan, mengharapkan, mendambakan, menghadap pemandangan."}}],explanations:[{id:"exp-1",grammarId:"gn3-00027",title:"Pola: 〜はずだ / 〜はずがない",formula:"V/Adj plain / N + の + はずだ / はずがない",meaning:"seharusnya ... / tidak mungkin ...",nuanceNotes:"〜はずだ: ekspektasi logis berdasarkan informasi/fakta yang diketahui. 〜はずがない: mustahil berdasarkan logika.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜はずだ / 〜はずがない",idText:"seharusnya ... / tidak mungkin ..."}],examples:[{jp:"今ごろ着いているはずです。",romaji:"",idText:"Seharusnya sekarang sudah sampai."},{jp:"彼がそんなことを言うはずがない。",romaji:"",idText:"Tidak mungkin dia mengatakan hal seperti itu."}]},{id:"exp-2",grammarId:"gn3-00028",title:"Pola: 〜わけだ",formula:"V/Adj plain / N + な/の + わけだ",meaning:"jadi ... / pantas saja ... / memang wajar",nuanceNotes:'〜わけだ menyatakan bahwa suatu kesimpulan logis dapat ditarik dari kondisi yang ada: "jadi wajar saja", "pantas saja".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜わけだ",idText:"jadi ... / pantas saja ... / memang wajar"}],examples:[{jp:"10年も日本に住んでいるんだから、日本語が上手なわけだ。",romaji:"",idText:"Sudah tinggal 10 tahun di Jepang, jadi wajar saja bahasa Jepangnya bagus."},{jp:"彼は3日も寝ていないそうだ。疲れているわけだ。",romaji:"",idText:"Katanya dia tidak tidur 3 hari. Pantas saja kelelahan."}]},{id:"exp-3",grammarId:"gn3-00030",title:"Pola: 〜わけにはいかない",formula:"Vる / Vない + わけにはいかない",meaning:"tidak bisa ... / tidak boleh ...",nuanceNotes:"〜わけにはいかない menyatakan bahwa suatu tindakan tidak dapat atau tidak boleh dilakukan karena alasan sosial, moral, atau situasional.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜わけにはいかない",idText:"tidak bisa ... / tidak boleh ..."}],examples:[{jp:"病気でも、この仕事だけは休むわけにはいかない。",romaji:"",idText:"Meskipun sakit, pekerjaan ini saja tidak bisa saya tinggalkan."},{jp:"親友を裏切るわけにはいかない。",romaji:"",idText:"Saya tidak bisa mengkhianati sahabat."}]},{id:"exp-4",grammarId:"gn3-00031",title:"Pola: 〜ということだ",formula:"V/Adj plain / N + ということだ",meaning:"artinya ... / kesimpulannya ...",nuanceNotes:'〜ということだ digunakan untuk menyatakan kesimpulan atau penafsiran dari suatu informasi: "artinya", "yang berarti". Juga bisa menyatakan kabar yang didengar.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ということだ",idText:"artinya ... / kesimpulannya ..."}],examples:[{jp:"電車が止まっているということは、何か事故があったということだ。",romaji:"",idText:"Kereta berhenti, artinya ada sesuatu yang terjadi."},{jp:"彼が来ないということは、断ったということだろう。",romaji:"",idText:"Dia tidak datang, artinya dia menolak."}]},{id:"exp-5",grammarId:"gn3-00032",title:"Pola: 〜によれば / 〜によると",formula:"N + によれば / によると",meaning:"menurut ... / berdasarkan ...",nuanceNotes:'〜によれば / 〜によると digunakan untuk mengutip sumber informasi: "menurut", "berdasarkan".',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜によれば / 〜によると",idText:"menurut ... / berdasarkan ..."}],examples:[{jp:"天気予報によれば、明日は大雨だそうです。",romaji:"",idText:"Menurut ramalan cuaca, besok katanya hujan deras."},{jp:"彼女の話によると、二人は別れたらしい。",romaji:"",idText:"Menurut cerita dia, katanya keduanya sudah putus."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "願う"?',sentencePrompt:'Makna kata "願う" (ねがう) dalam situasi kerja ini adalah:',options:["memohon, mengharapkan, berdoa mendambakan, meminta","asyik tenggelam dalam, terobsesi fokus, keranjingan","menyisakan, meninggalkan, mencatatkan warisan","menaikkan penumpang, memboncengkan, mengangkut tumpangan"],correctAnswer:"memohon, mengharapkan, berdoa mendambakan, meminta",explanation:'Makna yang tepat untuk "願う" adalah "memohon, mengharapkan, berdoa mendambakan, meminta".',diagnosticFeedback:{"asyik tenggelam dalam, terobsesi fokus, keranjingan":'Salah: Pilihan "asyik tenggelam dalam, terobsesi fokus, keranjingan" adalah makna dari kata "熱中" (ねっちゅう), bukan arti kata "願う".',"menyisakan, meninggalkan, mencatatkan warisan":'Salah: Pilihan "menyisakan, meninggalkan, mencatatkan warisan" adalah makna dari kata "残す" (のこす), bukan arti kata "願う".',"menaikkan penumpang, memboncengkan, mengangkut tumpangan":'Salah: Pilihan "menaikkan penumpang, memboncengkan, mengangkut tumpangan" adalah makna dari kata "乗せる" (のせる), bukan arti kata "願う".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"今ごろ着いている（　　）。",options:["はずです","わけだ","わけにはいかない","こそ"],correctAnswer:"はずです",explanation:'Pola 〜はずだ / 〜はずがない bermakna "seharusnya ... / tidak mungkin ...". Kalimat lengkap: "今ごろ着いているはずです。".',diagnosticFeedback:{わけだ:'Salah: Pola "わけだ" bermakna "jadi ... / pantas saja ... / memang wajar", yang tidak sesuai konteks kalimat ini.',わけにはいかない:'Salah: Pola "わけにはいかない" bermakna "tidak bisa ... / tidak boleh ...", yang tidak sesuai konteks kalimat ini.',こそ:'Salah: Pola "こそ" bermakna "justru ... / (inilah) yang sesungguhnya ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜はずだ / 〜はずがない secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["彼がそんなことを言うはずがない。","彼がそんなことを言うはずがない。でした","10年も日本に住んでいるんだから、日本語が上手なわけだ。","試験、うまくいくといいですね。"],correctAnswer:"彼がそんなことを言うはずがない。",explanation:'Kalimat yang benar dan alami adalah "彼がそんなことを言うはずがない。" (Tidak mungkin dia mengatakan hal seperti itu.).',diagnosticFeedback:{"彼がそんなことを言うはずがない。でした":"Jebakan Konjugasi: Pola 〜はずだ / 〜はずがない membutuhkan aturan sambung (V/Adj plain / N + の + はずだ / はずがない), bukan bentuk ini.","10年も日本に住んでいるんだから、日本語が上手なわけだ。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜わけだ: jadi ... / pantas saja ... / memang wajar), bukan kaidah 〜はずだ / 〜はずがない.","試験、うまくいくといいですね。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜はずだ / 〜はずがない secara tepat (seharusnya ... / tidak mungkin ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["10年も日本に 住んでいるんだ から、日本語が 上手なわけだ。","住んでいるんだ 10年も日本に から、日本語が 上手なわけだ。","10年も日本に から、日本語が 住んでいるんだ 上手なわけだ。","上手なわけだ。 10年も日本に 住んでいるんだ から、日本語が"],correctAnswer:"10年も日本に 住んでいるんだ から、日本語が 上手なわけだ。",explanation:'Susunan yang benar: "10年も日本に 住んでいるんだ から、日本語が 上手なわけだ。" (Sudah tinggal 10 tahun di Jepang, jadi wajar saja bahasa Jepangnya bagus.).',diagnosticFeedback:{"住んでいるんだ 10年も日本に から、日本語が 上手なわけだ。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","10年も日本に から、日本語が 住んでいるんだ 上手なわけだ。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","上手なわけだ。 10年も日本に 住んでいるんだ から、日本語が":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["10年も日本に","住んでいるんだ","から、日本語が","上手なわけだ。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Simulasi tanggap darurat bencana alam dan pemadaman daya listrik darurat di gedung pabrik.", saat Kenji menyampaikan arahan: 「なるほど。10年も日本に住んでいるんだから、日本語が上手なわけだ。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memahami dan menerapkan pola 〜はずだ / 〜はずがない dan 〜わけだ dalam percakapan kerja wajar.",situation:"Situasi komunikasi profesional di Simulasi tanggap darurat bencana alam dan pemadaman daya listrik darurat di gedung pabrik.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜はずだ / 〜はずがない!",modelAnswer:"はい、Kenjiさん！ 今ごろ着いているはずです。。",modelAnswerId:"Ya, Kenji! Seharusnya sekarang sudah sampai..",culturalEtiquette:"Sampaikan mitigasi risiko secara terstruktur menggunakan data dan urutan langkah yang jelas.",skillUnlocked:["Menguasai formulasi pola 〜はずだ / 〜はずがない","Mampu menerapkan prinsip koordinasi komunikasi kerja Pengandaian Kondisional & Rangkaian Sebab Akibat"]},pocket_summary:{keyFormula:"〜はずだ / 〜はずがない (seharusnya ... / tidak mungkin ...)",coreWords:["願う【ねがう】 (memohon, mengharapkan, berdoa mendambakan, meminta)","熱中【ねっちゅう】 (asyik tenggelam dalam, terobsesi fokus, keranjingan)","残す【のこす】 (menyisakan, meninggalkan, mencatatkan warisan)","乗せる【のせる】 (menaikkan penumpang, memboncengkan, mengangkut tumpangan)"],coreWarning:"Jangan menyepelekan klausul prasyarat mutlak (nai koto ni wa) pada instruksi keselamatan bertegangan tinggi.",quickDialogue:"A: ブディさん、願うの 状況【じょうきょう】は どうで... → B: はい、Kenjiさん！ 今ごろ着いているはずです。..."}},"les-n3-u07-02":{pedagogical_framework:{what:{summary:"Pengandaian Kondisional & Rangkaian Sebab Akibat (Produksi Aktif & Aplikasi Nyata). Menguasai penggunaan pola 〜べきだ / 〜べきではない, 〜ことはない, 〜しかない, 〜させてください dan penerapannya dalam situasi nyata.",canDo:"Mampu memproduksi ujaran terstruktur menggunakan 〜べきだ / 〜べきではない dan 〜ことはない secara mandiri.",targetPatterns:["〜べきだ / 〜べきではない (seharusnya ... / sudah sewajarnya ...)","〜ことはない (tidak perlu ... / tidak ada perlunya ...)","〜しかない (tidak ada pilihan selain ... / terpaksa ...)","〜させてください (izinkan saya ... / perbolehkan saya ...)"],coreVocabSample:["ほえる","ほしょう","ほぞん","まかせる","まく","まく","まく","まざる"]},sensei_context:{sceneIntro:"Simulasi tanggap darurat bencana alam dan pemadaman daya listrik darurat di gedung pabrik. Tahap pendalaman fokus pada aplikasi produksi mandiri dan mitigasi miskomunikasi.",dailyMission:"Terapkan pola 〜べきだ / 〜べきではない dengan santun dan wajar saat berinteraksi di lingkungan profesional.",whyOrder:"Pola ini esensial pada tingkat N3 untuk menjembatani kalimat sederhana N4 menuju wacana profesional yang padu dan berterima."},cultural_notes:{title:"Etika Komunikasi: Pengandaian Kondisional & Rangkaian Sebab Akibat",etiquette:"Sampaikan mitigasi risiko secara terstruktur menggunakan data dan urutan langkah yang jelas.",taboos:"Jangan menyepelekan klausul prasyarat mutlak (nai koto ni wa) pada instruksi keselamatan bertegangan tinggi."},pronunciation_tips:{title:"Tips Pelafalan & Pacing: 〜べきだ / 〜べきではない",moraNote:"Beri penekanan jeda tipis setelah partikel ba atau to shitara untuk menandai anak kalimat syarat.",soundTip:"Ucapkan 〜べきだ / 〜べきではない dengan tempo ritmis tanpa menghentak di akhir mora."},common_pitfalls:[{title:"Jebakan Nuansa: 〜べきだ / 〜べきではない",caseScenario:"Menggunakan 〜べきだ / 〜べきではない tanpa memperhatikan syarat batas wacana.",pitfallWarning:"Mengabaikan batasan gramatikal pola 〜べきだ / 〜べきではない.",rightSolution:"Perhatikan bentuk penghubung yang tepat sebelum 〜べきだ / 〜べきではない sesuai kaidah.",explanation:"Kaidah koneksi 〜べきだ / 〜べきではない: Vる + べきだ / べきではない."},{title:"Jebakan Derajat Kesantunan & Konteks Relasi",caseScenario:"Memilih pola yang terlalu santai atau kaku saat berbicara dengan kolega kerja.",pitfallWarning:"Mencampuradukkan ragam santai di hadapan pimpinan atau klien.",rightSolution:"Gunakan bentuk Teineigo terstandar yang selaras dengan hierarki kerja Jepang.",explanation:"Dalam konteks kerja Jepang, pemilihan bentuk predikat penutup mencerminkan respek sosial (Keigo/Teineigo)."}],who_and_when:{situational_context:"Simulasi tanggap darurat bencana alam dan pemadaman daya listrik darurat di gedung pabrik.",social_relations:"Ragam profesional antara rekan kerja, supervisor kerja, dan mitra industri.",when_not_to_use:"Hindari penggunaan di luar konteks wewenang peran formal."},scenario:{title:"Skenario Kerja: Pengandaian Kondisional & Rangkaian Sebab Akibat (Produksi Aktif & Aplikasi Nyata)",setting:"Simulasi tanggap darurat bencana alam dan pemadaman daya listrik darurat di gedung pabrik.",narrative:"Budi dan Kenji berkoordinasi mengenai alur operasional kerja menggunakan pola 〜べきだ / 〜べきではない."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Senior Engineer",avatar:"👨‍💻",jp:"ブディさん、吠えるの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",furigana:"ブディさん、吠えるの 状況【じょうきょう】は どうですか？ 順調【じゅんちょう】ですか？",romaji:"Budi-san, hoeru no joukyou wa dou desu ka? Junchou desu ka?",idText:"Budi, bagaimana situasi mengenai menggonggong, melolong, meraung? Apakah lancar?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、Kenjiさん！ 人の失敗を笑うべきではない。。",furigana:"はい、Kenjiさん！ 人の失敗を笑うべきではない。。",romaji:"Hai, Kenji-san! べきだ / 〜べきではない de susumete imasu.",idText:"Ya, Kenji! Tidak seharusnya menertawakan kegagalan orang lain.."},{id:"d3",speaker:"Kenji",speakerRole:"Senior Engineer",avatar:"👨‍💻",jp:"なるほど。そんなに謝ることはないよ。ように 気【き】を つけて 進【すす】めてくださいね。",furigana:"なるほど。そんなに謝ることはないよ。ように 気【き】を つけて 進【すす】めてくださいね。",romaji:"Naruhodo. Ki o tsukete susumete kudasai ne.",idText:'Begitu ya. Perhatikan baik-baik: "Tidak perlu meminta maaf sebanyak itu.". Lanjutkan dengan hati-hati ya.',note:"Mengangguk ramah dan memberi arahan kerja (Aizuchi)"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",furigana:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",romaji:"Shouchi itashimashita! Anzen daiichi de shikkari kakunin shite shinkou itashimasu.",idText:"Dimengerti! Dengan mengutamakan keselamatan kerja, saya akan memastikan dan menjalankannya dengan cermat."}],vocab_breakdown:[{id:"vg-n3-02262",word:"吠える",reading:"ほえる",romaji:"hoeru",meaning:"menggonggong, melolong, meraung",pos:"verb-ru",nuance:"Verba intransitif yang khusus menggambarkan suara keras yang dikeluarkan binatang berkaki empat, terutama gonggongan anjing, lolongan serigala, atau raungan singa (犬が吠える anjing menggonggong). Secara kiasan, dapat juga dipakai untuk orang yang berkoar-koar atau membual dari kejauhan (負け犬の遠吠え). Berbeda dengan 鳴く (naku) yang merupakan kata umum untuk suara hewan dan burung.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"吠える【ほえる】を 確認【かくにん】します。",furigana:"吠えるを 確認します。",romaji:"hoeru o kakunin shimasu.",idText:"Memeriksa menggonggong, melolong, meraung."}},{id:"vg-n3-02270",word:"保証",reading:"ほしょう",romaji:"hoshou",meaning:"garansi, jaminan mutu, penjaminan",pos:"verb-suru",nuance:"Jaminan tertulis atau janji pasti bahwa suatu produk akan berfungsi dengan baik atau bahwa suatu hal dapat dipastikan kebenarannya (保証書 kartu garansi, 保証期間 masa garansi). Homofon dengan 保障 (perlindungan keamanan sosial/hak) dan 補償 (ganti rugi kompensasi); 保証 fokus pada kepastian mutu dan pertanggungjawaban barang/orang.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"保証【ほしょう】を 確認【かくにん】します。",furigana:"保証を 確認します。",romaji:"hoshou o kakunin shimasu.",idText:"Memeriksa garansi, jaminan mutu, penjaminan."}},{id:"vg-n3-02271",word:"保存",reading:"ほぞん",romaji:"hozon",meaning:"penyimpanan data, pengawetan makanan, pelestarian",pos:"verb-suru",nuance:"Menjaga agar data digital, bahan makanan, atau artefak bersejarah tetap utuh dan terlindung dari kerusakan atau kehilangan (保存する). Di dunia komputasi dan telepon pintar, ini adalah istilah baku untuk perintah 'Save' (ファイルを保存する menyimpan file).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"保存【ほぞん】を 確認【かくにん】します。",furigana:"保存を 確認します。",romaji:"hozon o kakunin shimasu.",idText:"Memeriksa penyimpanan data, pengawetan makanan, pelestarian."}},{id:"vg-n3-02290",word:"任せる",reading:"まかせる",romaji:"makaseru",meaning:"menyerahkan, mempercayakan (tugas/tanggung jawab)",pos:"verb-ru",nuance:"Dipakai ketika menyerahkan suatu wewenang, pengambilan keputusan, atau pekerjaan kepada orang lain karena percaya pada kemampuannya (orang yang diserahi tugas ditandai partikel に). Frasa yang sering terdengar: 任せてください (serahkan pada saya!), お任せします (saya serahkan pada Anda).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"任せる【まかせる】を 確認【かくにん】します。",furigana:"任せるを 確認します。",romaji:"makaseru o kakunin shimasu.",idText:"Memeriksa menyerahkan, mempercayakan (tugas/tanggung jawab)."}},{id:"vg-n3-02291",word:"巻く",reading:"まく",romaji:"maku",meaning:"menggulung, melilitkan, membalut",pos:"verb-u",nuance:"Menyatakan tindakan melilitkan benda panjang/elastis pada tubuh atau benda lain (misal: マフラーを巻く = melilitkan syal, 包帯を巻く = membalut dengan perban). Juga dipakai untuk menggulung tikar/kertas (ポスターを巻く) atau memutar pegas jam mekanik (ねじを巻く). Jangan tertukar dengan kanji homofon 蒔く (menyemai) atau 撒く (menyebar).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"巻く【まく】を 確認【かくにん】します。",furigana:"巻くを 確認します。",romaji:"maku o kakunin shimasu.",idText:"Memeriksa menggulung, melilitkan, membalut."}},{id:"vg-n3-02292",word:"蒔く",reading:"まく",romaji:"maku",meaning:"menabur, menyemai (benih atau biji tanaman)",pos:"verb-u",nuance:"Secara khusus menggunakan kanji 蒔 untuk menabur biji atau benih tanaman ke dalam tanah agar tumbuh (misal: 種を蒔く = menyemai bibit). Sering pula dipakai dalam peribahasa 自分で蒔いた種 (benih yang ditanam sendiri = menanggung akibat dari perbuatannya sendiri).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"蒔く【まく】を 確認【かくにん】します。",furigana:"蒔くを 確認します。",romaji:"maku o kakunin shimasu.",idText:"Memeriksa menabur, menyemai (benih atau biji tanaman)."}},{id:"vg-n3-02293",word:"撒く",reading:"まく",romaji:"maku",meaning:"menyiramkan, memercikkan (air); menyebarkan (selebaran); mengecoh/meloloskan diri dari kejaran",pos:"verb-u",nuance:"Menggunakan kanji 撒 (ada radikal tangan 手), bermakna menghamburkan atau memercikkan zat cair atau benda kecil ke berbagai arah (misal: 庭に水を撒く = menyiram air di kebun, チラシを撒く = menyebar pamflet). Dalam ragam cerita kriminal/kasual juga berarti melepaskan diri dari kejaran musuh (追手を撒く).",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"撒く【まく】を 確認【かくにん】します。",furigana:"撒くを 確認します。",romaji:"maku o kakunin shimasu.",idText:"Memeriksa menyiramkan, memercikkan (air); menyebarkan (selebaran); mengecoh/meloloskan diri dari kejaran."}},{id:"vg-n3-02297",word:"混ざる",reading:"まざる",romaji:"mazaru",meaning:"bercampur, terbaur (hingga menyatu/larut)",pos:"verb-u",nuance:"Kata kerja intransitif (自動詞). Menggunakan kanji 混 (campuran zat cair/cairan atau substansi homogen di mana wujud aslinya menyatu dan tak lagi terpisahkan, misal warna cat, minyak dan air). Berbeda dengan 交ざる yang lebih condong pada benda atau manusia berbeda kelompok yang berbaur tetapi wujud aslinya tetap jelas.",particleTip:"Gunakan bersama partikel yang tepat dalam kalimat.",exampleSentence:{jp:"混ざる【まざる】を 確認【かくにん】します。",furigana:"混ざるを 確認します。",romaji:"mazaru o kakunin shimasu.",idText:"Memeriksa bercampur, terbaur (hingga menyatu/larut)."}}],explanations:[{id:"exp-1",grammarId:"gn3-00034",title:"Pola: 〜べきだ / 〜べきではない",formula:"Vる + べきだ / べきではない",meaning:"seharusnya ... / sudah sewajarnya ...",nuanceNotes:'〜べきだ menyatakan kewajiban moral atau norma yang seharusnya diikuti: "seharusnya", "sudah sewajarnya". Lebih kuat dari ほうがいい.',patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜べきだ / 〜べきではない",idText:"seharusnya ... / sudah sewajarnya ..."}],examples:[{jp:"人の失敗を笑うべきではない。",romaji:"",idText:"Tidak seharusnya menertawakan kegagalan orang lain."},{jp:"約束は守るべきだ。",romaji:"",idText:"Janji seharusnya ditepati."}]},{id:"exp-2",grammarId:"gn3-00035",title:"Pola: 〜ことはない",formula:"Vる + ことはない",meaning:"tidak perlu ... / tidak ada perlunya ...",nuanceNotes:"〜ことはない menyatakan bahwa suatu tindakan tidak perlu dilakukan. Sering digunakan untuk menenangkan atau meyakinkan seseorang.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜ことはない",idText:"tidak perlu ... / tidak ada perlunya ..."}],examples:[{jp:"そんなに謝ることはないよ。",romaji:"",idText:"Tidak perlu meminta maaf sebanyak itu."},{jp:"心配することはない。きっと大丈夫。",romaji:"",idText:"Tidak perlu khawatir. Pasti baik-baik saja."}]},{id:"exp-3",grammarId:"gn3-00036",title:"Pola: 〜しかない",formula:"Vる + しかない",meaning:"tidak ada pilihan selain ... / terpaksa ...",nuanceNotes:"〜しかない menyatakan bahwa tidak ada pilihan lain selain melakukan sesuatu.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜しかない",idText:"tidak ada pilihan selain ... / terpaksa ..."}],examples:[{jp:"もうやるしかない！",romaji:"",idText:"Tidak ada pilihan selain melakukannya!"},{jp:"電車が止まっているから、歩くしかない。",romaji:"",idText:"Kereta berhenti, jadi tidak ada pilihan selain jalan kaki."}]},{id:"exp-4",grammarId:"gn3-00038",title:"Pola: 〜させてください",formula:"Vさせて + ください",meaning:"izinkan saya ... / perbolehkan saya ...",nuanceNotes:"〜させてください digunakan untuk meminta izin melakukan sesuatu dengan sopan.",patternLogic:"Perhatikan susunan kata sebelum pola dan keterikatan logika predikat.",particleNotes:"Partikel penanda membantu memperjelas relasi semantis antar klausul.",formVariations:[{label:"Bentuk Standar",jp:"〜させてください",idText:"izinkan saya ... / perbolehkan saya ..."}],examples:[{jp:"発表させてください。",romaji:"",idText:"Izinkan saya untuk berpresentasi."},{jp:"お礼を言わせてください。",romaji:"",idText:"Perbolehkan saya mengucapkan terima kasih."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Arti Kosakata): Apakah makna kontekstual dari kata "吠える"?',sentencePrompt:'Makna kata "吠える" (ほえる) dalam situasi kerja ini adalah:',options:["menggonggong, melolong, meraung","garansi, jaminan mutu, penjaminan","penyimpanan data, pengawetan makanan, pelestarian","menyerahkan, mempercayakan (tugas/tanggung jawab)"],correctAnswer:"menggonggong, melolong, meraung",explanation:'Makna yang tepat untuk "吠える" adalah "menggonggong, melolong, meraung".',diagnosticFeedback:{"garansi, jaminan mutu, penjaminan":'Salah: Pilihan "garansi, jaminan mutu, penjaminan" adalah makna dari kata "保証" (ほしょう), bukan arti kata "吠える".',"penyimpanan data, pengawetan makanan, pelestarian":'Salah: Pilihan "penyimpanan data, pengawetan makanan, pelestarian" adalah makna dari kata "保存" (ほぞん), bukan arti kata "吠える".',"menyerahkan, mempercayakan (tugas/tanggung jawab)":'Salah: Pilihan "menyerahkan, mempercayakan (tugas/tanggung jawab)" adalah makna dari kata "任せる" (まかせる), bukan arti kata "吠える".'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kalimat): Lengkapi kalimat berikut dengan pola tata bahasa yang tepat sesuai konteks:",sentencePrompt:"人の失敗を笑う（　　）。",options:["べきではない","ことはない","しかない","こそ"],correctAnswer:"べきではない",explanation:'Pola 〜べきだ / 〜べきではない bermakna "seharusnya ... / sudah sewajarnya ...". Kalimat lengkap: "人の失敗を笑うべきではない。".',diagnosticFeedback:{ことはない:'Salah: Pola "ことはない" bermakna "tidak perlu ... / tidak ada perlunya ...", yang tidak sesuai konteks kalimat ini.',しかない:'Salah: Pola "しかない" bermakna "tidak ada pilihan selain ... / terpaksa ...", yang tidak sesuai konteks kalimat ini.',こそ:'Salah: Pola "こそ" bermakna "justru ... / (inilah) yang sesungguhnya ...", yang tidak sesuai konteks kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Deteksi Pola & Kalimat Alami): Manakah kalimat yang menggunakan kaidah pola 〜べきだ / 〜べきではない secara tepat dan alami?",sentencePrompt:"Pilihlah kalimat yang menggunakan kaidah tata bahasa Jepang yang benar:",options:["約束は守るべきだ。","約束は守るべきだ。でした","そんなに謝ることはないよ。","試験、うまくいくといいですね。"],correctAnswer:"約束は守るべきだ。",explanation:'Kalimat yang benar dan alami adalah "約束は守るべきだ。" (Janji seharusnya ditepati.).',diagnosticFeedback:{"約束は守るべきだ。でした":"Jebakan Konjugasi: Pola 〜べきだ / 〜べきではない membutuhkan aturan sambung (Vる + べきだ / べきではない), bukan bentuk ini.","そんなに謝ることはないよ。":"Jebakan Nuansa: Kalimat ini menggunakan pola berbeda (〜ことはない: tidak perlu ... / tidak ada perlunya ...), bukan kaidah 〜べきだ / 〜べきではない.","試験、うまくいくといいですね。":"Jebakan Konteks: Kalimat ini tidak menggunakan pola 〜べきだ / 〜べきではない secara tepat (seharusnya ... / sudah sewajarnya ...)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Susun potongan frasa berikut menjadi kalimat padu yang benar:",sentencePrompt:"Susunlah kata-kata berikut agar membentuk kalimat yang gramatikal:",options:["そんなに 謝る ことは ないよ。","謝る そんなに ことは ないよ。","そんなに ことは 謝る ないよ。","ないよ。 そんなに 謝る ことは"],correctAnswer:"そんなに 謝る ことは ないよ。",explanation:'Susunan yang benar: "そんなに 謝る ことは ないよ。" (Tidak perlu meminta maaf sebanyak itu.).',diagnosticFeedback:{"謝る そんなに ことは ないよ。":"Jebakan Urutan Klausul: Frasa penjelas diletakkan terbalik sehingga memutarbalikkan logika kalimat.","そんなに ことは 謝る ないよ。":"Jebakan Susunan Modifikasi: Partikel atau kata sambung diletakkan sebelum frasa yang diterangkannya.","ないよ。 そんなに 謝る ことは":"Jebakan Posisi Predikat: Dalam struktur SOV bahasa Jepang, kata kerja utama wajib berada di akhir kalimat."},tokens:["そんなに","謝る","ことは","ないよ。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Respons Situasional & Etiket): Dalam situasi "Simulasi tanggap darurat bencana alam dan pemadaman daya listrik darurat di gedung pabrik.", saat Kenji menyampaikan arahan: 「なるほど。そんなに謝ることはないよ。ように 気【き】を つけて 進【すす】めてくださいね。」, bagaimana respons terbaik Anda?',sentencePrompt:"Respons terbaik yang paling sopan dan tepat adalah:",options:["承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。","いいえ、やりたくありません。自分【じぶん】で やってください。","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。"],correctAnswer:"承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。",explanation:'Jawaban "承知【しょうち】いたしました！ 安全【あんぜん】第一【だいいち】で しっかり 確認【かくにん】して 進行【しんこう】いたします。" adalah respons standar dunia kerja yang menunjukkan sikap sigap dan bertanggung jawab.',diagnosticFeedback:{"いいえ、やりたくありません。自分【じぶん】で やってください。":"Salah: Sangat tidak sopan dan menolak arahan kerja secara konfrontatif dalam budaya kerja Jepang.","今日【きょう】は 天気【てんき】が いいですね。散歩【さんぽ】に 行【い】きましょう。":"Salah: Mengabaikan substansi pembicaraan kerja dan berbicara di luar topik komunikasi.","難【むずか】しすぎて 私【わたし】には 絶対【ぜったい】に 無理【むり】です。":"Salah: Sikap menyerah tanpa berusaha melanggar etika profesionalitas kerja (Hourensou)."}}],can_do_challenge:{statement:"Mampu memproduksi ujaran terstruktur menggunakan 〜べきだ / 〜べきではない dan 〜ことはない secara mandiri.",situation:"Situasi komunikasi profesional di Simulasi tanggap darurat bencana alam dan pemadaman daya listrik darurat di gedung pabrik.",promptTask:"Sampaikan laporan koordinasi menggunakan pola 〜べきだ / 〜べきではない!",modelAnswer:"はい、Kenjiさん！ 人の失敗を笑うべきではない。。",modelAnswerId:"Ya, Kenji! Tidak seharusnya menertawakan kegagalan orang lain..",culturalEtiquette:"Sampaikan mitigasi risiko secara terstruktur menggunakan data dan urutan langkah yang jelas.",skillUnlocked:["Menguasai formulasi pola 〜べきだ / 〜べきではない","Mampu menerapkan prinsip koordinasi komunikasi kerja Pengandaian Kondisional & Rangkaian Sebab Akibat"]},pocket_summary:{keyFormula:"〜べきだ / 〜べきではない (seharusnya ... / sudah sewajarnya ...)",coreWords:["吠える【ほえる】 (menggonggong, melolong, meraung)","保証【ほしょう】 (garansi, jaminan mutu, penjaminan)","保存【ほぞん】 (penyimpanan data, pengawetan makanan, pelestarian)","任せる【まかせる】 (menyerahkan, mempercayakan (tugas/tanggung jawab))"],coreWarning:"Jangan menyepelekan klausul prasyarat mutlak (nai koto ni wa) pada instruksi keselamatan bertegangan tinggi.",quickDialogue:"A: ブディさん、吠えるの 状況【じょうきょう】は どう... → B: はい、Kenjiさん！ 人の失敗を笑うべきではない..."}}};export{r as a,t as b,i as c,e as d,n as e,a as f,k as u};
